// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
    case "existing": return "keep";
    case "imported": return "import";
    default: return "create"; // unknown source: treat as the gated case
  }
}

export type AssetDenial = { assetId: string; kind: AssetKind; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

/** Every asset slot of a spec the plan may not create/edit (no changes). The build service request runs this too. */
export function gateSpecAssets(spec: Pick<ModSpec, "assets">, plan: unknown): AssetDenial[] {
  const out: AssetDenial[] = [];
  for (const a of spec.assets) {
    const d = canAsset(plan, a.kind, assetOpForSource(a.source));
    if (!d.ok) out.push({ assetId: a.id, kind: a.kind, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
  }
  return out;
}

const FALLBACK: Record<AssetKind, string> = { sound: "a vanilla sound", texture: "a vanilla look", model: "a vanilla model", ui: "plain text and standard menus" };

/**
 * Router downgrade: strip the gated asset slots instead of failing the build, with a customer-visible reason
 * per slot. Requirements stay (the mod still does what was asked, without the custom asset). Pure: returns a copy.
 */
export function downgradeSpecAssets<S extends Pick<ModSpec, "assets">>(spec: S, plan: unknown): { spec: S; removed: AssetDenial[]; notices: string[] } {
  const removed = gateSpecAssets(spec, plan);
  if (!removed.length) return { spec, removed, notices: [] };
  const drop = new Set(removed.map((r) => r.assetId));
  const notices = removed.map((r) => `${r.reason} Cyrus will build "${r.assetId}" with ${FALLBACK[r.kind]} instead.`);
  return { spec: { ...spec, assets: spec.assets.filter((a) => !drop.has(a.id)) }, removed, notices };
}
// Cyrus engine core: the pure half of the revision store (file manifests, diffs, engine records).
// A revision's file manifest lists every file of the mod project at that revision as { path, sha256, role }.
// Pure + client-safe; the DB half is lib/cyrus/engine-core/store.ts.
import type { SpecIssue } from "./spec";

export const REVISION_KINDS = ["generated", "edited", "imported", "asset", "revert"] as const;
export type RevisionKind = (typeof REVISION_KINDS)[number];
export const REVISION_STATUSES = ["pending", "passed", "failed"] as const;
export type RevisionStatus = (typeof REVISION_STATUSES)[number];

export const FILE_ROLES = ["source", "resource", "config", "asset", "resourcePack", "dataPack", "test", "doc", "artifact", "other"] as const;
export type FileRole = (typeof FILE_ROLES)[number];
export type ManifestEntry = { path: string; sha256: string; role: FileRole };
export const MAX_MANIFEST_FILES = 5000;

const SHA256 = /^[0-9a-f]{64}$/;

/** A safe project-relative path: forward slashes, no leading slash, no empty / "." / ".." segments, no control chars. */
export function isSafeProjectPath(p: unknown): p is string {
  if (typeof p !== "string" || p.length === 0 || p.length > 512) return false;
  if (p.startsWith("/") || p.includes("\\") || /[\u0000-\u001f]/.test(p)) return false;
  return p.split("/").every((s) => s.length > 0 && s !== "." && s !== "..");
}

export type ManifestResult = { ok: true; entries: ManifestEntry[] } | { ok: false; errors: SpecIssue[] };

/** Untrusted manifest -> entries sorted by path (a stable order, so equal manifests serialise identically). */
export function validateManifest(raw: unknown): ManifestResult {
  if (!Array.isArray(raw)) return { ok: false, errors: [{ path: "manifest", code: "not_array", message: "manifest must be an array" }] };
  if (raw.length > MAX_MANIFEST_FILES) return { ok: false, errors: [{ path: "manifest", code: "too_many_files", message: `at most ${MAX_MANIFEST_FILES} files` }] };
  const errors: SpecIssue[] = [];
  const seen = new Set<string>();
  const entries: ManifestEntry[] = [];
  raw.forEach((e, i) => {
    const at = `manifest[${i}]`;
    const r = (e ?? {}) as Record<string, unknown>;
    if (!isSafeProjectPath(r.path)) { errors.push({ path: `${at}.path`, code: "bad_path", message: "path must be a safe relative path" }); return; }
    if (typeof r.sha256 !== "string" || !SHA256.test(r.sha256)) errors.push({ path: `${at}.sha256`, code: "bad_sha256", message: "sha256 must be 64 lowercase hex characters" });
    if (!(FILE_ROLES as readonly string[]).includes(r.role as string)) errors.push({ path: `${at}.role`, code: "bad_role", message: `role must be one of ${FILE_ROLES.join(", ")}` });
    if (seen.has(r.path)) errors.push({ path: `${at}.path`, code: "duplicate_path", message: `${r.path} is listed twice` });
    seen.add(r.path);
    entries.push({ path: r.path, sha256: String(r.sha256), role: r.role as FileRole });
  });
  if (errors.length) return { ok: false, errors };
  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  return { ok: true, entries };
}

export type ManifestDiff = {
  added: ManifestEntry[];
  removed: ManifestEntry[];
  changed: { path: string; from: ManifestEntry; to: ManifestEntry }[];
  unchanged: number;
};

/** Files added, removed and changed (content or role) going from `from` to `to`. Pure. */
export function diffManifests(from: readonly ManifestEntry[], to: readonly ManifestEntry[]): ManifestDiff {
  const a = new Map(from.map((e) => [e.path, e]));
  const b = new Map(to.map((e) => [e.path, e]));
  const out: ManifestDiff = { added: [], removed: [], changed: [], unchanged: 0 };
  for (const [p, e] of b) {
    const old = a.get(p);
    if (!old) out.added.push(e);
    else if (old.sha256 !== e.sha256 || old.role !== e.role) out.changed.push({ path: p, from: old, to: e });
    else out.unchanged++;
  }
  for (const [p, e] of a) if (!b.has(p)) out.removed.push(e);
  const byPath = (x: { path: string }, y: { path: string }) => (x.path < y.path ? -1 : 1);
  out.added.sort(byPath); out.removed.sort(byPath); out.changed.sort(byPath);
  return out;
}

/**
 * What produced a revision, as far as it is known (MASTER-PLAN R0 "per-build engine-release record").
 * Every field optional: record what is known, never invent a value.
 */
export type EngineRecord = {
  promptVersion?: string;
  /** API sheets given to the model: name + content hash where known. */
  sheets?: { name: string; sha256?: string }[];
  rulesVersion?: string;
  scannerHash?: string;
  /** Build-service image digest (sha256:...) where known. */
  imageDigest?: string;
  model?: string;
  toolchain?: string;
  /** Set on a revert: the revision whose content this one restores. */
  revertOf?: string;
};
const ENGINE_KEYS = new Set(["promptVersion", "sheets", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf"]);

export function validateEngineRecord(raw: unknown): { ok: true; record: EngineRecord } | { ok: false; errors: SpecIssue[] } {
  if (raw === undefined || raw === null) return { ok: true, record: {} };
  if (typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: [{ path: "engine", code: "not_object", message: "engine record must be an object" }] };
  const errors: SpecIssue[] = [];
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!ENGINE_KEYS.has(k)) errors.push({ path: `engine.${k}`, code: "unknown_field", message: `unknown engine record field ${k}` });
  for (const k of ["promptVersion", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf"]) {
    if (r[k] !== undefined && (typeof r[k] !== "string" || (r[k] as string).length > 200)) errors.push({ path: `engine.${k}`, code: "bad_value", message: `${k} must be a string (max 200)` });
  }
  if (r.sheets !== undefined) {
    const ok = Array.isArray(r.sheets) && r.sheets.length <= 50 && r.sheets.every((s) => s && typeof s === "object" && typeof (s as { name?: unknown }).name === "string" && ((s as { sha256?: unknown }).sha256 === undefined || SHA256.test(String((s as { sha256?: unknown }).sha256))));
    if (!ok) errors.push({ path: "engine.sheets", code: "bad_value", message: "sheets must be up to 50 { name, sha256? } entries" });
  }
  return errors.length ? { ok: false, errors } : { ok: true, record: r as EngineRecord };
}
// The Cyrus public launch is TWO switches that must move together: the studio (cyrus_studio_public_enabled)
// and the token economy (cyrus_tok_live). Studio open to the public while tokens are off means builds that nobody
// meters or pays for, and (before this guard) a free choice of any model. This pure module is the one place that
// decides what the pair means; everything that opens Cyrus to non-preview accounts must go through it.
// Pure (unit-tested without any framework imports).

export type LaunchState =
  /** Studio flag off: only the private preview can build. (Tokens may or may not be live; that is fine.) */
  | "closed"
  /** Both on: the public may build, metered by tokens. */
  | "public"
  /** Studio flag on but tokens off: INVALID. Non-preview accounts are refused (fail closed). */
  | "unmetered";

export function launchState(o: { studioPublic: boolean; tokensLive: boolean }): LaunchState {
  if (!o.studioPublic) return "closed";
  return o.tokensLive ? "public" : "unmetered";
}

/** True only when the public may open the studio and build. */
export const publicMayBuild = (o: { studioPublic: boolean; tokensLive: boolean }): boolean => launchState(o) === "public";

/** The message an operator sees when the flags are in the invalid combination. */
export const UNMETERED_NOTICE =
  "Cyrus studio is set public but the token economy is off: the public is blocked until cyrus_tok_live is on too (they must be turned on together).";
// Procedural item textures, drawn by CODE (no image generation). The model never writes arbitrary drawing code:
// it writes a small declarative spec (this file's TextureSpec), and Nxeon's own renderer draws it, so the output is
// deterministic, bounded in size and time, and cannot run anything. Pure and dependency-free.

export const TEXTURE_SIZES = [16, 32, 64] as const;
export const MAX_OPS = 400;
export const MAX_PALETTE = 24;

export type Op =
  | { op: "fill"; c: string }
  | { op: "px"; x: number; y: number; c: string }
  | { op: "rect"; x: number; y: number; w: number; h: number; c: string }
  | { op: "line"; x1: number; y1: number; x2: number; y2: number; c: string }
  | { op: "circle"; x: number; y: number; r: number; c: string; ring?: boolean }
  | { op: "poly"; pts: [number, number][]; c: string }
  | { op: "gradient"; x: number; y: number; w: number; h: number; c1: string; c2: string; dir?: "v" | "h" }
  | { op: "noise"; amount: number; seed?: number; x?: number; y?: number; w?: number; h?: number }
  | { op: "shade"; amount?: number }
  | { op: "outline"; c: string };

export type TextureSpec = {
  name: string;
  size: (typeof TEXTURE_SIZES)[number];
  palette: Record<string, string>;
  /** Draw the left half and mirror it to the right. */
  mirror?: boolean;
  ops: Op[];
};

const HEX = /^#[0-9a-fA-F]{6}$/;
const KEY = /^[a-z][a-z0-9_]{0,23}$/;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;

export type Checked = { ok: true; spec: TextureSpec } | { ok: false; error: string };

const num = (v: unknown, lo: number, hi: number) => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;

/** Validate untrusted JSON into a TextureSpec. Every number is range-checked against the canvas, every colour must be in the palette. */
export function checkSpec(raw: unknown): Checked {
  if (!raw || typeof raw !== "object") return { ok: false, error: "texture must be an object" };
  const r = raw as Record<string, unknown>;
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size as number)) return { ok: false, error: "size must be 16, 32 or 64" };
  const size = r.size as TextureSpec["size"];
  if (!r.palette || typeof r.palette !== "object") return { ok: false, error: "palette is required" };
  const palette: Record<string, string> = {};
  const entries = Object.entries(r.palette as Record<string, unknown>);
  if (entries.length === 0 || entries.length > MAX_PALETTE) return { ok: false, error: `palette needs 1-${MAX_PALETTE} colours` };
  for (const [k, v] of entries) {
    if (!KEY.test(k)) return { ok: false, error: `bad palette key ${k}` };
    if (typeof v !== "string" || !HEX.test(v)) return { ok: false, error: `palette ${k} must be #rrggbb` };
    palette[k] = v.toLowerCase();
  }
  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > MAX_OPS) return { ok: false, error: `ops needs 1-${MAX_OPS} entries` };
  const col = (c: unknown) => typeof c === "string" && c in palette;
  const pos = (v: unknown) => num(v, -size, size * 2);
  const ops: Op[] = [];
  for (const [i, o] of (r.ops as unknown[]).entries()) {
    const at = `ops[${i}]`;
    if (!o || typeof o !== "object") return { ok: false, error: `${at} must be an object` };
    const p = o as Record<string, unknown>;
    switch (p.op) {
      case "fill": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "fill", c: p.c as string }); break;
      case "px": if (!pos(p.x) || !pos(p.y) || !col(p.c)) return { ok: false, error: `${at}: bad px` }; ops.push({ op: "px", x: p.x as number, y: p.y as number, c: p.c as string }); break;
      case "rect": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c)) return { ok: false, error: `${at}: bad rect` }; ops.push({ op: "rect", x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number, c: p.c as string }); break;
      case "line": if (![p.x1, p.y1, p.x2, p.y2].every(pos) || !col(p.c)) return { ok: false, error: `${at}: bad line` }; ops.push({ op: "line", x1: p.x1 as number, y1: p.y1 as number, x2: p.x2 as number, y2: p.y2 as number, c: p.c as string }); break;
      case "circle": if (!pos(p.x) || !pos(p.y) || !num(p.r, 0, size) || !col(p.c)) return { ok: false, error: `${at}: bad circle` }; ops.push({ op: "circle", x: p.x as number, y: p.y as number, r: p.r as number, c: p.c as string, ring: p.ring === true }); break;
      case "poly": {
        if (!Array.isArray(p.pts) || p.pts.length < 3 || p.pts.length > 40 || !col(p.c)) return { ok: false, error: `${at}: poly needs 3-40 points and a colour` };
        const pts: [number, number][] = [];
        for (const q of p.pts as unknown[]) { if (!Array.isArray(q) || q.length !== 2 || !pos(q[0]) || !pos(q[1])) return { ok: false, error: `${at}: bad point` }; pts.push([q[0] as number, q[1] as number]); }
        ops.push({ op: "poly", pts, c: p.c as string }); break;
      }
      case "gradient": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c1) || !col(p.c2)) return { ok: false, error: `${at}: bad gradient` }; ops.push({ op: "gradient", x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number, c1: p.c1 as string, c2: p.c2 as string, dir: p.dir === "h" ? "h" : "v" }); break;
      case "noise": if (!num(p.amount, 0, 60)) return { ok: false, error: `${at}: noise amount 0-60` }; ops.push({ op: "noise", amount: p.amount as number, seed: num(p.seed, 0, 1e9) ? (p.seed as number) : 1, ...(num(p.x, 0, size) && num(p.y, 0, size) && num(p.w, 0, size) && num(p.h, 0, size) ? { x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number } : {}) }); break;
      case "shade": ops.push({ op: "shade", amount: num(p.amount, 0, 60) ? (p.amount as number) : 28 }); break;
      case "outline": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "outline", c: p.c as string }); break;
      default: return { ok: false, error: `${at}: unknown op ${String(p.op)}` };
    }
  }
  return { ok: true, spec: { name: r.name, size, palette, mirror: r.mirror === true, ops } };
}

// Cyrus engine core: the project + revision store and the identifier registry (DB half). SERVER ONLY.
// The only writer of CyrusProject / CyrusRevision / CyrusProjectAsset / CyrusIdentifier.
// Rules: revisions are append-only (no function here edits or deletes their content); a revision's status moves
// once, pending -> passed | failed; a project always records its last passing revision; a revert is a NEW revision
// that copies an older one's content. Appends lock the project row (FOR UPDATE), so seq has no gaps and two writers
// cannot both build on the same head.
import { randomBytes } from "node:crypto";
import { Prisma, type CyrusIdentifier, type CyrusProject, type CyrusRevision } from "@prisma/client";
import { db } from "../../db";
import { getAdapter } from "../adapters";
import { validateModSpec, GAME_ID_RE, type ModSpec, type SpecIssue } from "./spec";
import { diffManifests, validateEngineRecord, validateManifest, REVISION_KINDS, type EngineRecord, type ManifestDiff, type ManifestEntry, type RevisionKind, type RevisionStatus } from "./revisions";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, GLYPH_BLOCKS, namespaceFromSeed, type IdentifierKind } from "./identifiers";

export class EngineStoreError extends Error {
  constructor(public code: string, message: string, public issues: SpecIssue[] = []) {
    super(message);
    this.name = "EngineStoreError";
  }
}

const isUniqueViolation = (e: unknown, field?: string): boolean => {
  if (!(e instanceof Prisma.PrismaClientKnownRequestError) || e.code !== "P2002") return false;
  if (!field) return true;
  const t = (e.meta as { target?: unknown } | undefined)?.target;
  return (Array.isArray(t) ? t.join(",") : String(t ?? "")).includes(field);
};

// ---------------------------------------------------------------------------
// Projects
// ---------------------------------------------------------------------------

export type CreateProjectInput = { userId: string; game: string; title?: string | null; rootBuildId?: string | null };
export type CreateProjectOptions = {
  /** Test hook: the namespace to try on each attempt (default: namespaceFromSeed of the project id + attempt). */
  namespaceFor?: (projectId: string, attempt: number) => string;
  maxAttempts?: number;
};

/** Create a project and reserve its unique namespace. A namespace clash (another project holds it) retries with a new seed. */
export async function createProject(input: CreateProjectInput, opts: CreateProjectOptions = {}): Promise<CyrusProject> {
  if (!input.userId) throw new EngineStoreError("bad_input", "userId is required");
  if (!GAME_ID_RE.test(input.game) || !getAdapter(input.game)) throw new EngineStoreError("unknown_game", `no game adapter for "${input.game}"`);
  const id = "cp" + randomBytes(10).toString("hex");
  const nsFor = opts.namespaceFor ?? ((pid: string, n: number) => namespaceFromSeed(n === 0 ? pid : `${pid}:${n}`));
  const max = opts.maxAttempts ?? 8;
  for (let attempt = 0; attempt < max; attempt++) {
    const namespace = nsFor(id, attempt);
    try {
      return await db.cyrusProject.create({
        data: { id, userId: input.userId, game: input.game, namespace, title: input.title ?? null, rootBuildId: input.rootBuildId ?? null },
      });
    } catch (e) {
      if (isUniqueViolation(e, "namespace")) continue;
      if (isUniqueViolation(e, "rootBuildId")) throw new EngineStoreError("root_taken", "that build chain already has a project");
      throw e;
    }
  }
  throw new EngineStoreError("namespace_exhausted", `could not reserve a free namespace in ${max} attempts`);
}

export const getProject = (id: string) => db.cyrusProject.findUnique({ where: { id } });
export const projectForRootBuild = (rootBuildId: string) => db.cyrusProject.findUnique({ where: { rootBuildId } });

// ---------------------------------------------------------------------------
// Revisions
// ---------------------------------------------------------------------------

export type AddRevisionInput = {
  kind: Exclude<RevisionKind, "revert">;
  manifest: unknown;
  spec?: unknown;
  modBuildId?: string | null;
  engine?: EngineRecord | null;
  status?: RevisionStatus;
  message?: string | null;
  /** Optimistic check: the head this revision builds on (null = the project has no revisions yet). Omit to append to whatever the head is. */
  expectedHeadId?: string | null;
};

type InsertRow = {
  kind: RevisionKind; spec: ModSpec | null; manifest: ManifestEntry[]; modBuildId: string | null; engine: EngineRecord | null;
  status: RevisionStatus; message: string | null; revertOfId: string | null; expectedHeadId?: string | null;
};

const lockProject = async (tx: Prisma.TransactionClient, projectId: string) => {
  const rows = await tx.$queryRaw<{ id: string; namespace: string; game: string; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number }[]>`
    SELECT "id", "namespace", "game", "headRevisionId", "lastPassingRevisionId", "revisionCount"
    FROM "CyrusProject" WHERE "id" = ${projectId} FOR UPDATE`;
  if (!rows.length) throw new EngineStoreError("not_found", "project not found");
  return rows[0];
};

/** Appends queue on the project row lock; give queued writers room before Prisma's 2 s default gives up. */
const TX = { maxWait: 10_000, timeout: 15_000 };

async function insertRevision(projectId: string, row: InsertRow): Promise<CyrusRevision> {
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, projectId);
    if (row.expectedHeadId !== undefined && row.expectedHeadId !== p.headRevisionId) {
      throw new EngineStoreError("stale_head", "the project moved on since this change was started; reload and try again");
    }
    if (row.spec && (row.spec.namespace !== p.namespace || row.spec.game !== p.game)) {
      throw new EngineStoreError("spec_mismatch", "the spec's game or namespace is not this project's");
    }
    const rev = await tx.cyrusRevision.create({
      data: {
        projectId, seq: p.revisionCount + 1, parentId: p.headRevisionId, kind: row.kind,
        spec: row.spec ? (row.spec as unknown as Prisma.InputJsonValue) : Prisma.DbNull,
        manifest: row.manifest as unknown as Prisma.InputJsonValue,
        modBuildId: row.modBuildId, engine: row.engine ? (row.engine as Prisma.InputJsonValue) : Prisma.DbNull,
        status: row.status, message: row.message, revertOfId: row.revertOfId,
      },
    });
    await tx.cyrusProject.update({
      where: { id: projectId },
      data: { headRevisionId: rev.id, revisionCount: rev.seq, ...(rev.status === "passed" ? { lastPassingRevisionId: rev.id } : {}) },
    });
    return rev;
  }, TX);
}

/** Append a revision on top of the project's head. Validates spec, manifest and engine record first. */
export async function addRevision(projectId: string, input: AddRevisionInput): Promise<CyrusRevision> {
  if (!(REVISION_KINDS as readonly string[]).includes(input.kind) || input.kind === ("revert" as string)) throw new EngineStoreError("bad_kind", `kind must be generated, edited, imported or asset (use revertTo for a revert)`);
  const status = input.status ?? "pending";
  if (!["pending", "passed", "failed"].includes(status)) throw new EngineStoreError("bad_status", "status must be pending, passed or failed");
  const m = validateManifest(input.manifest);
  if (!m.ok) throw new EngineStoreError("bad_manifest", "the file manifest is invalid", m.errors);
  const eng = validateEngineRecord(input.engine);
  if (!eng.ok) throw new EngineStoreError("bad_engine_record", "the engine record is invalid", eng.errors);
  let spec: ModSpec | null = null;
  if (input.spec !== undefined && input.spec !== null) {
    const v = validateModSpec(input.spec, { adapterFor: getAdapter });
    if (!v.ok) throw new EngineStoreError("bad_spec", "the mod spec is invalid", v.errors);
    spec = v.spec;
  }
  return insertRevision(projectId, {
    kind: input.kind, spec, manifest: m.entries, modBuildId: input.modBuildId ?? null, engine: input.engine ? eng.record : null,
    status, message: input.message ?? null, revertOfId: null, expectedHeadId: input.expectedHeadId,
  });
}

/** The one allowed change to a revision: pending -> passed | failed. A pass becomes the project's last passing revision if it is newer. */
export async function setRevisionStatus(revisionId: string, status: "passed" | "failed"): Promise<CyrusRevision> {
  if (status !== "passed" && status !== "failed") throw new EngineStoreError("bad_status", "status must be passed or failed");
  const rev = await db.cyrusRevision.findUnique({ where: { id: revisionId } });
  if (!rev) throw new EngineStoreError("not_found", "revision not found");
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, rev.projectId);
    const n = await tx.cyrusRevision.updateMany({ where: { id: revisionId, status: "pending" }, data: { status } });
    if (n.count !== 1) throw new EngineStoreError("not_pending", "only a pending revision can change status");
    if (status === "passed") {
      const current = p.lastPassingRevisionId ? await tx.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId }, select: { seq: true } }) : null;
      if (!current || current.seq < rev.seq) await tx.cyrusProject.update({ where: { id: rev.projectId }, data: { lastPassingRevisionId: rev.id } });
    }
    return { ...rev, status };
  }, TX);
}

export async function getHead(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } });
  return p?.headRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.headRevisionId } }) : null;
}

export async function lastPassing(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { lastPassingRevisionId: true } });
  return p?.lastPassingRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId } }) : null;
}

export const getRevision = (id: string) => db.cyrusRevision.findUnique({ where: { id } });
export const listRevisions = (projectId: string) => db.cyrusRevision.findMany({ where: { projectId }, orderBy: { seq: "asc" } });

export const manifestOf = (rev: Pick<CyrusRevision, "manifest">): ManifestEntry[] => (Array.isArray(rev.manifest) ? (rev.manifest as unknown as ManifestEntry[]) : []);

/** Files added / removed / changed going from revision `fromId` to `toId` (same project). */
export async function diffRevisions(fromId: string, toId: string): Promise<ManifestDiff> {
  const [a, b] = await Promise.all([getRevision(fromId), getRevision(toId)]);
  if (!a || !b) throw new EngineStoreError("not_found", "revision not found");
  if (a.projectId !== b.projectId) throw new EngineStoreError("bad_input", "revisions belong to different projects");
  return diffManifests(manifestOf(a), manifestOf(b));
}

/**
 * Revert = a NEW revision on top of the head that restores `targetId`'s spec, files and build link. History is kept.
 * The status carries over: the files are byte-identical (same manifest hashes), so the same checks apply.
 */
export async function revertTo(projectId: string, targetId: string, opts: { message?: string; expectedHeadId?: string | null } = {}): Promise<CyrusRevision> {
  const t = await getRevision(targetId);
  if (!t || t.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const engine = { ...((t.engine as EngineRecord | null) ?? {}), revertOf: t.id };
  return insertRevision(projectId, {
    kind: "revert", spec: (t.spec as unknown as ModSpec | null) ?? null, manifest: manifestOf(t), modBuildId: t.modBuildId, engine,
    status: t.status as RevisionStatus, message: opts.message ?? `Revert to revision ${t.seq}`, revertOfId: t.id, expectedHeadId: opts.expectedHeadId,
  });
}

// ---------------------------------------------------------------------------
// Assets (content-addressed; recording the same content twice returns the first row)
// ---------------------------------------------------------------------------

export type RecordAssetInput = {
  revisionId: string; assetKey: string; kind: "texture" | "sound" | "model" | "ui"; sha256: string; size: number;
  origin: "generated" | "library" | "upload" | "edited" | "imported"; mime?: string | null; path?: string | null; provenance?: Record<string, unknown> | null;
};

export async function recordAsset(projectId: string, a: RecordAssetInput) {
  if (!/^[0-9a-f]{64}$/.test(a.sha256)) throw new EngineStoreError("bad_input", "sha256 must be 64 lowercase hex characters");
  const rev = await getRevision(a.revisionId);
  if (!rev || rev.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const where = { projectId_kind_assetKey_sha256: { projectId, kind: a.kind, assetKey: a.assetKey, sha256: a.sha256 } };
  try {
    return await db.cyrusProjectAsset.create({
      data: { projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ? (a.provenance as Prisma.InputJsonValue) : Prisma.DbNull },
    });
  } catch (e) {
    if (isUniqueViolation(e)) { const row = await db.cyrusProjectAsset.findUnique({ where }); if (row) return row; }
    throw e;
  }
}
export const listProjectAssets = (projectId: string) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" } });

// ---------------------------------------------------------------------------
// Identifier registry
// ---------------------------------------------------------------------------

/**
 * Reserve an identifier in the project's namespace. Idempotent: reserving the same (kind, key) again returns the
 * existing row. Glyphs get the first free codepoint from the namespace's home block (unique across all projects).
 */
export async function reserveIdentifier(projectId: string, kind: IdentifierKind, key: string): Promise<CyrusIdentifier> {
  const p = await getProject(projectId);
  if (!p) throw new EngineStoreError("not_found", "project not found");
  const built = buildIdentifier(p.namespace, kind, key);
  if (!built.ok) throw new EngineStoreError("bad_identifier", built.error);
  const where = { namespace_kind_key: { namespace: p.namespace, kind, key } };
  const existing = await db.cyrusIdentifier.findUnique({ where });
  if (existing) return existing;
  const base = { projectId, namespace: p.namespace, kind, key, fullId: built.id };
  if (kind !== "glyph") {
    try {
      return await db.cyrusIdentifier.create({ data: base });
    } catch (e) {
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  const home = glyphHomeBlock(p.namespace);
  let tries = 0;
  for (let b = 0; b < GLYPH_BLOCKS && tries < 64; ) {
    const start = glyphBlockStart(home + b);
    const taken = new Set((await db.cyrusIdentifier.findMany({ where: { codepoint: { gte: start, lt: start + GLYPH_BLOCK } }, select: { codepoint: true } })).map((r) => r.codepoint));
    let cp = -1;
    for (let c = start; c < start + GLYPH_BLOCK; c++) if (!taken.has(c)) { cp = c; break; }
    if (cp < 0) { b++; continue; }
    tries++;
    try {
      return await db.cyrusIdentifier.create({ data: { ...base, codepoint: cp } });
    } catch (e) {
      if (isUniqueViolation(e, "codepoint")) continue; // another project took it: look again
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  throw new EngineStoreError("glyphs_exhausted", "no free glyph codepoint");
}

export const listIdentifiers = (projectId: string) => db.cyrusIdentifier.findMany({ where: { projectId }, orderBy: [{ kind: "asc" }, { key: "asc" }] });

// Deterministic pixel-art renderer for a validated TextureSpec: RGBA, no anti-aliasing (crisp like game art).
import type { Op, TextureSpec } from "./dsl";

export type Raster = { size: number; px: Uint8ClampedArray };

const rgb = (hex: string): [number, number, number] => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const clamp = (v: number) => Math.max(0, Math.min(255, Math.round(v)));

/** Small deterministic PRNG so the same spec always yields the same bytes. */
function rng(seed: number) { let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }

export function render(spec: TextureSpec): Raster {
  const n = spec.size;
  const px = new Uint8ClampedArray(n * n * 4); // transparent
  const P = (k: string) => rgb(spec.palette[k]);
  const set = (x: number, y: number, c: [number, number, number]) => {
    x = Math.round(x); y = Math.round(y);
    if (x < 0 || y < 0 || x >= n || y >= n) return;
    const i = (y * n + x) * 4; px[i] = c[0]; px[i + 1] = c[1]; px[i + 2] = c[2]; px[i + 3] = 255;
  };
  const opaque = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && px[(y * n + x) * 4 + 3] > 0;

  const draw = (o: Op) => {
    switch (o.op) {
      case "fill": { const c = P(o.c); for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) set(x, y, c); break; }
      case "px": set(o.x, o.y, P(o.c)); break;
      case "rect": { const c = P(o.c); for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) set(x, y, c); break; }
      case "line": {
        const c = P(o.c); let x0 = Math.round(o.x1), y0 = Math.round(o.y1); const x1 = Math.round(o.x2), y1 = Math.round(o.y2);
        const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1; let err = dx + dy;
        for (let guard = 0; guard < 4096; guard++) { set(x0, y0, c); if (x0 === x1 && y0 === y1) break; const e2 = 2 * err; if (e2 >= dy) { err += dy; x0 += sx; } if (e2 <= dx) { err += dx; y0 += sy; } }
        break;
      }
      case "circle": {
        const c = P(o.c);
        for (let y = Math.floor(o.y - o.r - 1); y <= Math.ceil(o.y + o.r + 1); y++) for (let x = Math.floor(o.x - o.r - 1); x <= Math.ceil(o.x + o.r + 1); x++) {
          const d = Math.hypot(x + 0.5 - o.x, y + 0.5 - o.y);
          if (o.ring ? d <= o.r && d > o.r - 1.2 : d <= o.r) set(x, y, c);
        }
        break;
      }
      case "poly": {
        const c = P(o.c); const ys = o.pts.map((p) => p[1]); const y0 = Math.max(0, Math.floor(Math.min(...ys))), y1 = Math.min(n - 1, Math.ceil(Math.max(...ys)));
        for (let y = y0; y <= y1; y++) {
          const yc = y + 0.5; const xs: number[] = [];
          for (let i = 0; i < o.pts.length; i++) {
            const [ax, ay] = o.pts[i], [bx, by] = o.pts[(i + 1) % o.pts.length];
            if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) xs.push(ax + ((yc - ay) / (by - ay)) * (bx - ax));
          }
          xs.sort((a, b) => a - b);
          for (let k = 0; k + 1 < xs.length; k += 2) for (let x = Math.ceil(xs[k] - 0.5); x <= Math.floor(xs[k + 1] - 0.5); x++) set(x, y, c);
        }
        break;
      }
      case "gradient": {
        const a = P(o.c1), b = P(o.c2);
        for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) {
          const t = o.dir === "h" ? (o.w <= 1 ? 0 : (x - Math.floor(o.x)) / (o.w - 1)) : (o.h <= 1 ? 0 : (y - Math.floor(o.y)) / (o.h - 1));
          set(x, y, [clamp(a[0] + (b[0] - a[0]) * t), clamp(a[1] + (b[1] - a[1]) * t), clamp(a[2] + (b[2] - a[2]) * t)]);
        }
        break;
      }
      case "noise": {
        const r = rng(o.seed ?? 1); const x0 = o.x ?? 0, y0 = o.y ?? 0, w = o.w ?? n, h = o.h ?? n;
        for (let y = y0; y < y0 + h; y++) for (let x = x0; x < x0 + w; x++) {
          const i = (y * n + x) * 4; const d = (r() - 0.5) * 2 * o.amount; // draw the number even on transparent pixels so the pattern doesn't depend on shape
          if (px[i + 3] > 0) { px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d); }
        }
        break;
      }
      case "shade": {
        // light from the top-left: lighten pixels whose up/left neighbour is empty, darken those whose down/right neighbour is empty
        const a = o.amount ?? 28; const src = px.slice();
        const has = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && src[(y * n + x) * 4 + 3] > 0;
        for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
          if (!has(x, y)) continue; const i = (y * n + x) * 4; let d = 0;
          if (!has(x, y - 1) || !has(x - 1, y)) d += a; if (!has(x, y + 1) || !has(x + 1, y)) d -= a;
          px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d);
        }
        break;
      }
      case "outline": {
        const c = P(o.c); const add: [number, number][] = [];
        for (let y = -1; y <= n; y++) for (let x = -1; x <= n; x++) {
          if (opaque(x, y)) continue;
          if (opaque(x + 1, y) || opaque(x - 1, y) || opaque(x, y + 1) || opaque(x, y - 1)) add.push([x, y]);
        }
        for (const [x, y] of add) set(x, y, c);
        break;
      }
    }
  };

  // mirror: ops draw the left half; copy it across after every op so later ops see a symmetric image
  const mirrorNow = () => { for (let y = 0; y < n; y++) for (let x = 0; x < n / 2; x++) { const a = (y * n + x) * 4, b = (y * n + (n - 1 - x)) * 4; if (px[a + 3]) { px[b] = px[a]; px[b + 1] = px[a + 1]; px[b + 2] = px[a + 2]; px[b + 3] = px[a + 3]; } } };
  for (const o of spec.ops) { draw(o); if (spec.mirror && o.op !== "outline") mirrorNow(); }
  return { size: n, px };
}
// Quality bar v1 for generated textures (MASTER-PLAN 4.7 "Quality bar", GAPS-AND-IDEAS D). Automatic, deterministic
// checks on the RENDERED pixels of every texture Cyrus generates. A failing check is never shipped silently: the build
// service sends it back to the model as repair feedback (bounded), and anything still failing is dropped with a
// customer-visible reason (a downgrade). The same rules run in the build service (services/modbuilder/textures.js);
// test/cyrus-assets.test.ts proves both give identical reports on the shared fixtures. Pure and dependency-free.
import type { Raster } from "./render";

export const QUALITY_VERSION = "tq-1";
export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
export type QualityCheck = { id: string; status: CheckStatus; value: number | null; limit: string; message: string };
export type QualityReport = { version: string; verdict: "pass" | "warn" | "fail"; size: number; checks: QualityCheck[]; profile?: "tile" };
/**
 * "item" (default): a silhouette on a clear background (what builds generate; the JS twin implements only this).
 * "tile": a block face / skin swatch (texture library, uploads): fully solid is expected, outline does not apply,
 * and a `seam` check compares the wrap-around edges with the texture's own interior. TS only for now: the build
 * service does not generate tiles yet (when it does, port the profile to services/modbuilder/textures.js).
 */
export type QualityProfile = "item" | "tile";

/** Per-size limits. Vanilla item art is 16x16 with a few ramps of 3-5 shades; bigger canvases may use a little more. */
const PALETTE_LIMIT: Record<number, { warn: number; fail: number }> = { 16: { warn: 32, fail: 48 }, 32: { warn: 48, fail: 96 }, 64: { warn: 64, fail: 128 } };
// "Grain": neighbouring solid pixels that are almost, but not exactly, the same colour (RGB distance 1..GRAIN_MAX).
// That is what the noise op and smooth gradients produce; hand-made pixel art uses flat clusters plus deliberate
// shade steps (vanilla ramps step by more than this), so a high grain ratio means noisy, muddy art.
const GRAIN_MAX = 24;
const GRAIN = { warn: 0.2, fail: 0.35 };
const CONTRAST = { fail: 1.6, warn: 2.5 };
const COVERAGE = { failLow: 0.04, warnLow: 0.1, warnHigh: 0.85 };
const OUTLINE_DARK = 0.12; // relative luminance at or below which a silhouette pixel reads as an outline
const OUTLINE_WARN = 0.5;
// tile profile: mean RGB step across the wrap edges / (mean interior step + SEAM_FLOOR)
const SEAM = { warn: 1.8, fail: 3 };
const SEAM_FLOOR = 6;

const lin = (c: number) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
const lum = (r: number, g: number, b: number) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
const r4 = (v: number) => Math.round(v * 10000) / 10000;

/** `tileable: false` or `framed: true` (tile profile only) skip the seam check: a nine-slice panel or a log end is not meant to repeat. */
export function textureQuality(img: Raster, opts: { profile?: QualityProfile; tileable?: boolean; framed?: boolean } = {}): QualityReport {
  const tile = opts.profile === "tile";
  const n = img.size, px = img.px;
  const at = (x: number, y: number) => (y * n + x) * 4;
  const opaque = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && px[at(x, y) + 3] === 255;
  const dist = (a: number, b: number) => Math.hypot(px[a] - px[b], px[a + 1] - px[b + 1], px[a + 2] - px[b + 2]);
  let count = 0, partial = 0, lo = Infinity, hi = -Infinity, pairs = 0, grain = 0, rim = 0, rimDark = 0;
  const colours = new Set<number>();
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const i = at(x, y), a = px[i + 3];
    if (a !== 0 && a !== 255) partial++;
    if (a !== 255) continue;
    count++;
    colours.add((px[i] << 16) | (px[i + 1] << 8) | px[i + 2]);
    const L = lum(px[i], px[i + 1], px[i + 2]);
    if (L < lo) lo = L;
    if (L > hi) hi = L;
    let edgeOfShape = false;
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      if (!opaque(x + dx, y + dy)) { edgeOfShape = true; continue; }
      if (dx < 0 || dy < 0) continue; // count each pair once (right and down)
      pairs++;
      const d = dist(i, at(x + dx, y + dy));
      if (d > 0 && d <= GRAIN_MAX) grain++;
    }
    if (edgeOfShape) { rim++; if (L <= OUTLINE_DARK) rimDark++; }
  }
  const total = n * n;
  const checks: QualityCheck[] = [];
  const lim = PALETTE_LIMIT[n] ?? PALETTE_LIMIT[64];

  const coverage = count / total;
  if (tile) {
    if (partial > 0) checks.push({ id: "transparency", status: "fail", value: partial, limit: "alpha 0 or 255 only", message: `${partial} pixels are semi-transparent; use fully clear or fully solid pixels` });
    else if (coverage < COVERAGE.failLow) checks.push({ id: "transparency", status: "fail", value: r4(coverage), limit: `coverage >= ${COVERAGE.failLow}`, message: "the tile is almost empty" });
    else checks.push({ id: "transparency", status: "pass", value: r4(coverage), limit: "alpha 0 or 255 only", message: count === total ? "solid tile" : "tile with clear cut-outs" });
  } else if (partial > 0) checks.push({ id: "transparency", status: "fail", value: partial, limit: "alpha 0 or 255 only", message: `${partial} pixels are semi-transparent; item textures use fully clear or fully solid pixels` });
  else if (coverage < COVERAGE.failLow) checks.push({ id: "transparency", status: "fail", value: r4(coverage), limit: `coverage >= ${COVERAGE.failLow}`, message: "the texture is almost empty; draw the item so it fills a good part of the canvas" });
  else if (count === total) checks.push({ id: "transparency", status: "fail", value: 1, limit: "some clear pixels", message: "every pixel is solid, so the item shows as a square tile; leave the background transparent around the item's silhouette" });
  else if (coverage < COVERAGE.warnLow || coverage > COVERAGE.warnHigh) checks.push({ id: "transparency", status: "warn", value: r4(coverage), limit: `${COVERAGE.warnLow}-${COVERAGE.warnHigh}`, message: coverage < COVERAGE.warnLow ? "the item is very small on its canvas" : "the item covers almost the whole canvas" });
  else checks.push({ id: "transparency", status: "pass", value: r4(coverage), limit: `${COVERAGE.warnLow}-${COVERAGE.warnHigh}`, message: "clear background, solid silhouette" });

  const pal = colours.size;
  checks.push({
    id: "palette_size", status: pal > lim.fail ? "fail" : pal > lim.warn ? "warn" : "pass", value: pal, limit: `<= ${lim.warn} (fail above ${lim.fail})`,
    message: pal > lim.fail ? `${pal} distinct colours; vanilla-style art uses a few short shade ramps (reduce noise and gradients)` : pal > lim.warn ? `${pal} distinct colours is on the busy side` : `${pal} distinct colours`,
  });

  const contrast = count ? (hi + 0.05) / (lo + 0.05) : 0;
  checks.push({
    id: "contrast", status: count === 0 || contrast < CONTRAST.fail ? "fail" : contrast < CONTRAST.warn ? "warn" : "pass", value: r4(contrast), limit: `>= ${CONTRAST.warn} (fail below ${CONTRAST.fail})`,
    message: contrast < CONTRAST.fail ? "light and dark are too close, the item will read as a flat blob; add a dark outline and a highlight" : contrast < CONTRAST.warn ? "low contrast between the darkest and lightest shades" : "clear light and dark shades",
  });

  const grainy = pairs ? grain / pairs : 0;
  checks.push({
    id: "noise", status: grainy > GRAIN.fail ? "fail" : grainy > GRAIN.warn ? "warn" : "pass", value: r4(grainy), limit: `grain <= ${GRAIN.warn} (fail above ${GRAIN.fail})`,
    message: grainy > GRAIN.fail ? "the texture is grainy (noise or smooth gradients); use flat areas with a few deliberate shade steps" : grainy > GRAIN.warn ? "a lot of fine grain" : "clean pixel clusters",
  });

  const outline = rim ? rimDark / rim : 0;
  if (tile) {
    // wrap seam: the step from the last column to the first (and last row to the first) against the interior steps
    let wrap = 0, wn = 0, inner = 0, inn = 0;
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      if (!opaque(x, y)) continue;
      const i = at(x, y);
      const right = (x + 1) % n, down = (y + 1) % n;
      if (opaque(right, y)) { const d = dist(i, at(right, y)); if (x === n - 1) { wrap += d; wn++; } else { inner += d; inn++; } }
      if (opaque(x, down)) { const d = dist(i, at(x, down)); if (y === n - 1) { wrap += d; wn++; } else { inner += d; inn++; } }
    }
    const seam = wn ? (wrap / wn) / ((inn ? inner / inn : 0) + SEAM_FLOOR) : 0;
    if (opts.framed) checks.push({ id: "seam", status: "not_run", value: r4(seam), limit: "unframed tiles only", message: "framed tile: repeats as a grid of bevelled slabs by design" });
    else if (opts.tileable === false) checks.push({ id: "seam", status: "not_run", value: r4(seam), limit: "tileable textures only", message: "not meant to repeat, so the wrap seam is not checked" });
    else checks.push({
      id: "seam", status: seam > SEAM.fail ? "fail" : seam > SEAM.warn ? "warn" : "pass", value: r4(seam), limit: `<= ${SEAM.warn} (fail above ${SEAM.fail})`,
      message: seam > SEAM.fail ? "the edges do not continue across the wrap; the tile will show a grid when repeated" : seam > SEAM.warn ? "the wrap edges are a little harder than the interior" : "repeats without a visible seam",
    });
    checks.push({ id: "outline", status: "not_run", value: r4(outline), limit: "items only", message: "tiles have no silhouette, so the outline rule does not apply" });
  } else checks.push({
    id: "outline", status: outline >= OUTLINE_WARN ? "pass" : "warn", value: r4(outline), limit: `>= ${OUTLINE_WARN} of the silhouette dark`,
    message: outline >= OUTLINE_WARN ? "consistent dark outline" : "the silhouette has no consistent dark outline (Style DNA: outline every item the same way)",
  });

  checks.push({ id: "vanilla_lookalike", status: "not_run", value: null, limit: "perceptual hash vs vanilla textures", message: "not built yet: needs the vanilla texture set on the build host (GAPS finding 15)" });

  const verdict = checks.some((c) => c.status === "fail") ? "fail" : checks.some((c) => c.status === "warn") ? "warn" : "pass";
  return { version: QUALITY_VERSION, verdict, size: n, checks, ...(tile ? { profile: "tile" as const } : {}) };
}

/** One line per failing check, for repair feedback and customer notices. */
export const qualityProblems = (r: QualityReport): string[] => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.message} (value ${c.value}, limit ${c.limit})`);
// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
// Cyrus R1 sound slice: the SAME pack also carries the mod's rendered sounds (one pack per mod, one pack.mcmeta):
//   assets/<ns>/sounds/<set>/<event>_<n>.ogg   mono Ogg Vorbis from the render host
//   assets/<ns>/sounds.json                    "<set>.<event>": { subtitle, sounds: [{ name "<ns>:<set>/<event>_<n>", weight }] }
//   assets/<ns>/lang/en_us.json                the subtitle texts (key subtitles.<ns>.<set>.<event>)
// New namespaced keys only (never `replace`, never a minecraft: key); the plugin plays "<ns>:<set>.<event>".
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "./dsl";
import { encodePng } from "./png";
import { render } from "./render";
import { zip } from "./zip";
import { getVersion, resourcePackFormat } from "../versions/registry";

/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
export function packFormatFor(mc: string): number {
  const r = resourcePackFormat(mc);
  if (!r.ok) throw new Error(r.error);
  return r.format.major;
}

export type PackSoundEvent = { set: string; event: string; subtitle: string; files: { index: number; weight: number; data: Buffer }[] };
export type BuiltPack = { packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[]; sounds: { key: string; subtitleKey: string; files: number }[] };

const SET_RE = /^[a-z][a-z0-9_]{1,31}$/;
const EVENT_RE = /^[a-z][a-z0-9_]{0,23}$/;

export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  const sounds = opts.sounds ?? [];
  if (opts.textures.length > 24) return { ok: false, error: "a pack holds at most 24 textures" };
  if (opts.textures.length === 0 && sounds.length === 0) return { ok: false, error: "a pack needs at least one texture or sound" };
  if (sounds.length > 24) return { ok: false, error: "a pack holds at most 24 sound events" };
  const seen = new Set<string>();
  for (const e of sounds) {
    if (!SET_RE.test(e.set) || !EVENT_RE.test(e.event)) return { ok: false, error: `bad sound key ${e.set}.${e.event}` };
    if (seen.has(`${e.set}.${e.event}`)) return { ok: false, error: `duplicate sound event ${e.set}.${e.event}` };
    seen.add(`${e.set}.${e.event}`);
    if (!e.files.length || e.files.length > 4) return { ok: false, error: `sound ${e.set}.${e.event} needs 1-4 files` };
    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3) return { ok: false, error: `sound ${e.set}.${e.event} has no subtitle` };
    for (const f of e.files) if (f.data.subarray(0, 4).toString("latin1") !== "OggS") return { ok: false, error: `sound ${e.set}.${e.event} file ${f.index} is not Ogg` };
  }
  const specs: TextureSpec[] = [];
  for (const [i, t] of opts.textures.entries()) { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; if (specs.some((s) => s.name === c.spec.name)) return { ok: false, error: `duplicate texture name ${c.spec.name}` }; specs.push(c.spec); }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: opts.textures.length > 0 });
  if (!pf.ok) return { ok: false, error: pf.error };
  const fmt = pf.format.major;
  // item model definitions need format 46+ (1.21.4); a sound-only pack also works on older versions (sounds.json is stable since 1.13)
  const minF = opts.textures.length ? 46 : Math.min(46, fmt);
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: minF, max_inclusive: 999 }, min_format: minF, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
  ];
  const ns = opts.namespace;
  for (const s of specs) {
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(render(s)) });
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` } }, null, 2)) });
    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const packSounds: BuiltPack["sounds"] = [];
  if (sounds.length) {
    const json: Record<string, unknown> = {};
    const lang: Record<string, string> = {};
    for (const e of [...sounds].sort((a, b) => (`${a.set}.${a.event}` < `${b.set}.${b.event}` ? -1 : 1))) {
      const key = `${e.set}.${e.event}`, sub = `subtitles.${ns}.${key}`;
      const list = [...e.files].sort((a, b) => a.index - b.index);
      for (const f of list) files.push({ path: `assets/${ns}/sounds/${e.set}/${e.event}_${f.index}.ogg`, data: f.data });
      json[key] = { subtitle: sub, sounds: list.map((f) => ({ name: `${ns}:${e.set}/${e.event}_${f.index}`, weight: f.weight })) };
      lang[sub] = e.subtitle.trim().slice(0, 60);
      packSounds.push({ key: `${ns}:${key}`, subtitleKey: sub, files: list.length });
    }
    files.push({ path: `assets/${ns}/sounds.json`, data: Buffer.from(JSON.stringify(json, null, 2)) });
    files.push({ path: `assets/${ns}/lang/en_us.json`, data: Buffer.from(JSON.stringify(lang, null, 2)) });
  }
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })), sounds: packSounds } };
}
import { deflateSync } from "node:zlib";
import type { Raster } from "./render";

const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
export function crc32(buf: Uint8Array): number { let c = 0xffffffff; for (let i = 0; i < buf.length; i++) c = CRC[(c ^ buf[i]) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; }

function chunk(type: string, data: Uint8Array): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0); out.write(type, 4, "ascii"); Buffer.from(data).copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
}

/** Encode an RGBA raster as a PNG (8-bit, filter 0). */
export function encodePng(r: Raster): Buffer {
  const n = r.size; const raw = Buffer.alloc(n * (n * 4 + 1));
  for (let y = 0; y < n; y++) { raw[y * (n * 4 + 1)] = 0; Buffer.from(r.px.buffer, r.px.byteOffset + y * n * 4, n * 4).copy(raw, y * (n * 4 + 1) + 1); }
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(n, 0); ihdr.writeUInt32BE(n, 4); ihdr[8] = 8; ihdr[9] = 6;
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw, { level: 9 })), chunk("IEND", Buffer.alloc(0))]);
}

// The catalog service: plan gate + providers + unified search, behind injectable host seams (plan lookup, asset
// store). Cyrus reaches Nxeon ONLY through `CatalogDeps.planOf` (today: lib/cyrus/tokens/access tierOf, wired by
// the route that will call this) and the UserAssetStore. Server code calls it per request; nothing here caches
// across users.
import { canBrowse, type BrowseDecision } from "./gate";
import { searchAssets, similarAssets, type UnifiedQuery, type UnifiedResult } from "./search";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset, type LibraryKind, type LibraryProvider, type LibrarySource, type ProviderContext } from "./types";

export type CatalogDeps = {
  providers: readonly LibraryProvider[];
  /** the viewer's raw plan (any spelling asset-gate understands); throw or return null when unknown -> fail closed */
  planOf: (userId: string) => Promise<unknown>;
};
export type BrowseRequest = { userId: string | null; projectId?: string | null; query?: UnifiedQuery };
export type Denial = { kind: LibraryKind; source: LibrarySource; code: Exclude<BrowseDecision, { ok: true }>["code"]; reason: string; needs?: string };
export type BrowseResponse = UnifiedResult & { denied: Denial[] };

async function visible(deps: CatalogDeps, req: BrowseRequest, kinds: readonly LibraryKind[]): Promise<{ assets: LibraryAsset[]; denied: Denial[] }> {
  const denied: Denial[] = [];
  if (!req.userId) {
    for (const kind of kinds) denied.push({ kind, source: "builtin", code: "sign_in", reason: "Sign in to browse the asset library." });
    return { assets: [], denied };
  }
  let plan: unknown = null;
  try { plan = await deps.planOf(req.userId); } catch { plan = null; } // unknown plan: fail closed (project assets stay visible)
  const viewer = { signedIn: true, plan };
  const ctx: ProviderContext = { userId: req.userId, projectId: req.projectId ?? null };
  const assets: LibraryAsset[] = [];
  for (const kind of kinds) {
    const allowed = new Set<LibrarySource>();
    for (const source of LIBRARY_SOURCES) {
      if (source === "project" && !ctx.projectId) continue;
      if (!deps.providers.some((p) => p.kind === kind && p.sources.includes(source))) continue;
      const d = canBrowse(viewer, kind, source);
      if (d.ok) allowed.add(source);
      else denied.push({ kind, source, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
    }
    if (!allowed.size) continue;
    for (const p of deps.providers) if (p.kind === kind) for (const a of await p.list(ctx, allowed)) if (allowed.has(a.source)) assets.push(a);
  }
  return { assets, denied };
}

/** Browse / search the catalog as this viewer. Gated sources are left out and listed in `denied` (for an upgrade hint). */
export async function browseLibrary(deps: CatalogDeps, req: BrowseRequest): Promise<BrowseResponse> {
  const q = req.query ?? {};
  const kinds = (q.kinds?.length ? q.kinds : LIBRARY_KINDS).filter((k) => (LIBRARY_KINDS as readonly string[]).includes(k));
  const { assets, denied } = await visible(deps, req, kinds);
  return { ...searchAssets(assets, q), denied };
}

/** "Similar to" within what the viewer may see. */
export async function similarInLibrary(deps: CatalogDeps, req: BrowseRequest & { ref: string; limit?: number }): Promise<LibraryAsset[]> {
  const kind = req.ref.split("/")[0] as LibraryKind;
  if (!(LIBRARY_KINDS as readonly string[]).includes(kind)) return [];
  const { assets } = await visible(deps, req, [kind]);
  return similarAssets(req.ref, assets, req.limit);
}
// Browse gate for the asset catalog (pure, client-safe; the server calls it again on every request).
// Owner rules (MASTER-PLAN section 2 + Asset Library): browsing a library follows the STUDIO gate of its kind:
//   sound   -> Saka and the top plan        texture / model -> the top plan only        free / Katara -> none
// It is the plan-tier rule of lib/cyrus/engine-core/asset-gate.ts (`canAsset(plan, kind, "create")`, because picking
// from a library puts new content into a project); it does NOT spend or check generation tokens (no generate gate).
// Fail closed: not signed in or an unknown plan denies. Assets ALREADY IN THE CURRENT PROJECT (source "project")
// are never gated for a signed-in owner: keeping / installing / rebuilding them is never plan-gated.
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { LibraryKind, LibrarySource } from "./types";

export type BrowseViewer = { signedIn: boolean; plan: unknown };
export type BrowseDecision = { ok: true } | { ok: false; code: "sign_in" | "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: string };

export function canBrowse(viewer: BrowseViewer, kind: LibraryKind, source: LibrarySource): BrowseDecision {
  if (!viewer.signedIn) return { ok: false, code: "sign_in", reason: "Sign in to browse the asset library." };
  if (source === "project") return { ok: true };
  const d: AssetDecision = canAsset(viewer.plan, kind, "create");
  if (d.ok) return { ok: true };
  return { ok: false, code: d.code, reason: d.reason.replace("Creating or editing", "Browsing and using"), ...(d.needs ? { needs: d.needs } : {}) };
}
// Cyrus unified asset catalog (R1): ONE shape for every library asset, whatever its kind (sound, texture, later
// models) and wherever it comes from (built-in libraries, the customer's uploads and other projects, the current
// project). Pure types, client-safe. MASTER-PLAN "Asset Library (owner requirement, 2026-10-10)".
import type { SlotKey } from "../texture-library/compile";

export const LIBRARY_KINDS = ["sound", "texture", "model"] as const;
export type LibraryKind = (typeof LIBRARY_KINDS)[number];
/** builtin = shipped by Cyrus (owner/Cyrus libraries); user = the customer's uploads and assets of their OTHER projects; project = already in the current project. */
export const LIBRARY_SOURCES = ["builtin", "user", "project"] as const;
export type LibrarySource = (typeof LIBRARY_SOURCES)[number];

/** Licence / provenance ledger. `original` is true only for art authored from scratch by Cyrus (never asserted for uploads or third-party files). */
export type LibraryLedger = { provenance: string; licence: string | null; licenceStatus: string; author: string | null; original: boolean; derivedFrom: string | null };

/** How a client previews the asset without the catalog shipping bytes. */
export type PreviewRef =
  | { type: "texture-template"; itemId: string; templateId: string; ramps: Partial<Record<SlotKey, string>>; dna: string; pngSha256: string }
  | { type: "texture-asset"; assetId: string; sha256: string; mime: string | null }
  | { type: "sound-render-host"; libraryId: string; sha256: string }
  | { type: "sound-asset"; assetId: string; sha256: string }
  | { type: "none" };

export type DescriptorValue = string | number | boolean | null;
export type LibraryAsset = {
  kind: LibraryKind;
  source: LibrarySource;
  /** unique within (kind, source); `ref` is globally unique */
  id: string;
  ref: string;
  name: string;
  category: string;
  subcategory: string | null;
  useCases: string[];
  tags: string[];
  descriptors: Record<string, DescriptorValue>;
  ledger: LibraryLedger;
  preview: PreviewRef;
  /** user/project assets: the project that holds it */
  projectId: string | null;
};
export const assetRef = (kind: LibraryKind, source: LibrarySource, id: string) => `${kind}/${source}/${id}`;

export type ProviderContext = { userId: string; projectId: string | null };
export interface LibraryProvider {
  readonly kind: LibraryKind;
  /** the sources this provider can return (the gate decides per source) */
  readonly sources: readonly LibrarySource[];
  list(ctx: ProviderContext, allowed: ReadonlySet<LibrarySource>): Promise<readonly LibraryAsset[]>;
}
// Built-in catalog providers (pure, client-safe): the owner's sound library and the Cyrus texture templates,
// mapped into LibraryAsset. User/project assets come from ./user-assets.ts (an injected store).
import { librarySounds, type LibrarySound } from "../sound/library";
import { libraryTextures, type TextureLibraryItem } from "../texture-library/library";
import { assetRef, type LibraryAsset, type LibraryProvider } from "./types";

export function soundAsset(s: LibrarySound): LibraryAsset {
  const d = s.descriptors;
  return {
    kind: "sound", source: "builtin", id: s.id, ref: assetRef("sound", "builtin", s.id), name: s.prefix ? `${s.prefix} (${s.id})` : s.id,
    category: s.category, subcategory: null, useCases: [...s.useCases], tags: [...s.tags],
    descriptors: { durationClass: d.durationClass, intensity: d.intensity, pitchBand: d.pitchBand, character: d.character, loopable: d.loopable, channels: d.channels, duration: s.duration },
    ledger: { provenance: s.ledger.provenance, licence: null, licenceStatus: s.ledger.licenceStatus, author: null, original: false, derivedFrom: null },
    // the audio stays on the render host; the file name is not exposed to browsers
    preview: { type: "sound-render-host", libraryId: s.id, sha256: s.sha256 },
    projectId: null,
  };
}

export function textureAsset(t: TextureLibraryItem): LibraryAsset {
  const ramps = Object.fromEntries(Object.entries(t.ramps).filter(([, v]) => v)) as Record<string, string>;
  return {
    kind: "texture", source: "builtin", id: t.id, ref: assetRef("texture", "builtin", t.id), name: t.name,
    category: t.category, subcategory: t.sub, useCases: [...t.useCases], tags: [...t.tags],
    descriptors: { ...t.descriptors, template: t.templateId, quality: t.quality.verdict },
    ledger: { provenance: t.ledger.provenance, licence: t.ledger.licence, licenceStatus: t.ledger.licenceStatus, author: t.ledger.author, original: t.ledger.original, derivedFrom: t.ledger.derivedFrom },
    preview: { type: "texture-template", itemId: t.id, templateId: t.templateId, ramps, dna: t.dna, pngSha256: t.pngSha256 },
    projectId: null,
  };
}

let soundCache: LibraryAsset[] | null = null;
let textureCache: LibraryAsset[] | null = null;
export const builtinSoundAssets = (): readonly LibraryAsset[] => (soundCache ??= librarySounds().map(soundAsset));
export const builtinTextureAssets = (): readonly LibraryAsset[] => (textureCache ??= libraryTextures().map(textureAsset));

export const SoundLibraryProvider: LibraryProvider = {
  kind: "sound", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinSoundAssets() : []),
};
export const TextureLibraryProvider: LibraryProvider = {
  kind: "texture", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinTextureAssets() : []),
};
// Unified search over LibraryAsset (pure, client-safe): one query across sounds, textures and (later) models, with
// both taxonomies' synonym tables (sound taxonomy.json + texture taxonomy.json), ranking
//   exact tag (5; 4 via a synonym) > use case / category / subcategory / kind (3) > tag prefix (2) > name words (1),
//   +0.5 each when the word is the asset's subcategory / its primary material,
// where EVERY query word must match something; filters, facets, pagination and `similarTo`.
// Same rules as lib/cyrus/sound/library-search.ts (which stays the sound-only API the Sound Studio already uses).
import { TAXONOMY as SOUND_TAX, categoryLabel } from "../sound/classify";
import { TEXTURE_TAXONOMY as TEX_TAX } from "../texture-library/compile";
import type { DescriptorValue, LibraryAsset, LibraryKind, LibrarySource } from "./types";

export type UnifiedFilters = {
  kinds?: LibraryKind[]; sources?: LibrarySource[]; category?: string | string[]; subcategory?: string | string[]; useCase?: string | string[];
  tags?: string[]; descriptors?: Record<string, DescriptorValue[]>;
};
export type UnifiedQuery = UnifiedFilters & { text?: string; limit?: number; offset?: number };
export const FACET_DESCRIPTORS = ["size", "transparency", "tileable", "material", "durationClass", "intensity", "pitchBand", "quality", "moderation"] as const;
export type UnifiedFacets = { kind: Record<string, number>; source: Record<string, number>; category: Record<string, number>; subcategory: Record<string, number>; useCase: Record<string, number>; descriptors: Record<string, Record<string, number>> };
export type UnifiedResult = { total: number; items: LibraryAsset[]; facets: UnifiedFacets; expanded: string[][] };

const STOP = new Set([...SOUND_TAX.stopWords, ...TEX_TAX.stopWords]);
const canon = (w: string) => TEX_TAX.synonyms[w] ?? SOUND_TAX.synonyms[w] ?? w;
export const queryWords = (text: string) => text.toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter((w) => w && !STOP.has(w));

/** A query word, its canonical forms in both taxonomies, and both query-synonym tables (one level + nested aliases). */
export function expandTerm(w: string): string[] {
  const out = new Set<string>([w]);
  for (const c of [TEX_TAX.synonyms[w], SOUND_TAX.synonyms[w]]) if (c) out.add(c);
  for (const x of [...out]) for (const table of [TEX_TAX.querySynonyms, SOUND_TAX.querySynonyms]) {
    for (const s of table[x] ?? []) { out.add(s); for (const t of TEX_TAX.querySynonyms[s] ?? []) out.add(t); for (const t of SOUND_TAX.querySynonyms[s] ?? []) out.add(t); }
  }
  return [...out];
}

const arr = <T>(v: T | T[] | undefined) => (v == null ? null : Array.isArray(v) ? v : [v]);
function matches(a: LibraryAsset, f: UnifiedFilters): boolean {
  if (f.kinds && !f.kinds.includes(a.kind)) return false;
  if (f.sources && !f.sources.includes(a.source)) return false;
  const cats = arr(f.category), subs = arr(f.subcategory), ucs = arr(f.useCase);
  if (cats && !cats.includes(a.category)) return false;
  if (subs && !(a.subcategory && subs.includes(a.subcategory))) return false;
  if (ucs && !ucs.some((u) => a.useCases.includes(u))) return false;
  if (f.tags && f.tags.some((t) => !a.tags.includes(t.toLowerCase()))) return false;
  if (f.descriptors) for (const [k, vs] of Object.entries(f.descriptors)) if (!vs.includes(a.descriptors[k] ?? null)) return false;
  return true;
}

const label = (a: LibraryAsset) => (a.kind === "sound" ? categoryLabel(a.category) : TEX_TAX.categories.find((c) => c.id === a.category)?.label ?? a.category).toLowerCase();

function scoreWord(a: LibraryAsset, word: string, terms: string[], nameWords: string[]): number {
  let best = 0;
  const self = new Set([word, canon(word)]);
  for (const t of terms) {
    if (a.tags.includes(t)) best = Math.max(best, self.has(t) ? 5 : 4);
    else if (a.useCases.includes(t) || a.category === t || a.subcategory === t || label(a) === t || a.kind === t) best = Math.max(best, 3);
    else if (t.length >= 3 && a.tags.some((x) => x.startsWith(t))) best = Math.max(best, 2);
    else if (t.length >= 3 && nameWords.some((n) => n.includes(t))) best = Math.max(best, 1);
    if (best === 5) break;
  }
  // tie-break inside a score: the word names what the asset IS (its subcategory or primary material), not only
  // something it carries (a stone-family ramp on a brick's mortar, an iron rim on a shield)
  if (best && terms.some((t) => a.subcategory === t)) best += 0.5;
  if (best && terms.some((t) => a.descriptors.material === t)) best += 0.5;
  return best;
}

const SOURCE_RANK: Record<LibrarySource, number> = { project: 0, user: 1, builtin: 2 };

export function searchAssets(assets: readonly LibraryAsset[], q: UnifiedQuery = {}): UnifiedResult {
  const words = queryWords(q.text ?? "");
  const expanded = words.map(expandTerm);
  const scored: { a: LibraryAsset; score: number }[] = [];
  for (const a of assets) {
    if (!matches(a, q)) continue;
    const nameWords = queryWords(`${a.name} ${a.id}`);
    let score = 0, miss = false;
    for (const [i, w] of words.entries()) { const v = scoreWord(a, w, expanded[i], nameWords); if (!v) { miss = true; break; } score += v; }
    if (!miss) scored.push({ a, score });
  }
  scored.sort((x, y) => y.score - x.score || SOURCE_RANK[x.a.source] - SOURCE_RANK[y.a.source] || (x.a.ref < y.a.ref ? -1 : 1));
  const facets: UnifiedFacets = { kind: {}, source: {}, category: {}, subcategory: {}, useCase: {}, descriptors: {} };
  const inc = (m: Record<string, number>, k: string) => { m[k] = (m[k] ?? 0) + 1; };
  for (const { a } of scored) {
    inc(facets.kind, a.kind); inc(facets.source, a.source); inc(facets.category, a.category);
    if (a.subcategory) inc(facets.subcategory, a.subcategory);
    for (const u of a.useCases) inc(facets.useCase, u);
    for (const k of FACET_DESCRIPTORS) if (a.descriptors[k] !== undefined) inc((facets.descriptors[k] ??= {}), String(a.descriptors[k]));
  }
  const off = Math.max(0, Math.floor(q.offset ?? 0)), lim = Math.min(200, Math.max(1, Math.floor(q.limit ?? 50)));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.a), facets, expanded };
}

/** Assets like this one (same kind): category, subcategory, shared use cases, tags and descriptor values. */
export function similarAssets(ref: string, assets: readonly LibraryAsset[], limit = 10): LibraryAsset[] {
  const me = assets.find((a) => a.ref === ref);
  if (!me) return [];
  return assets.filter((a) => a.ref !== ref && a.kind === me.kind).map((a) => {
    let s = 0;
    if (a.category === me.category) s += 4;
    if (a.subcategory && a.subcategory === me.subcategory) s += 2;
    s += 2 * a.useCases.filter((u) => me.useCases.includes(u)).length;
    s += Math.min(4, a.tags.filter((t) => me.tags.includes(t)).length);
    for (const k of FACET_DESCRIPTORS) if (me.descriptors[k] != null && a.descriptors[k] === me.descriptors[k]) s += 1;
    if (a.kind === "texture" && a.descriptors.template === me.descriptors.template) s -= 3; // prefer other shapes over recolours
    return { a, s };
  }).filter((x) => x.s >= 5).sort((x, y) => y.s - x.s || (x.a.ref < y.a.ref ? -1 : 1)).slice(0, limit).map((x) => x.a);
}

