166	/** Pure validation (no gate, no storage): decode, pixel rules, quality, clean re-encode. */
167	export function validateTextureUpload(bytes: Buffer, opts: { profile?: QualityProfile; allowTranslucent?: boolean } = {}): ValidatedUpload | UploadError {
168	  if (!Buffer.isBuffer(bytes)) return { ok: false, code: "bad_request", error: "no file" };
169	  const d = decodePng(bytes, UPLOAD_LIMITS);
170	  if (!d.ok) return d;
171	  const px = d.raster.px; let partial = 0, clear = 0;
172	  const colours = new Set<number>();
173	  for (let i = 0; i < px.length; i += 4) {
174	    const a = px[i + 3];
175	    if (a === 0) { clear++; px[i] = px[i + 1] = px[i + 2] = 0; continue; } // normalise hidden colour under alpha 0 (no data in the RGB of clear pixels)
176	    if (a !== 255) partial++;
177	    colours.add((px[i] << 16) | (px[i + 1] << 8) | px[i + 2]);
178	  }
179	  const alpha: AlphaMode = partial ? "translucent" : clear ? "binary" : "opaque";
180	  if (alpha === "translucent" && !opts.allowTranslucent) return { ok: false, code: "translucent", error: `${partial} pixels are semi-transparent; use fully clear or fully solid pixels` };
181	  if (colours.size > UPLOAD_LIMITS.maxColours) return { ok: false, code: "too_many_colours", error: `${colours.size} distinct colours; pixel-art textures use at most ${UPLOAD_LIMITS.maxColours} (this looks like a photo or a smooth render)` };
182	  const quality = textureQuality(d.raster, { profile: opts.profile ?? "item" });
183	  if (quality.verdict === "fail") return { ok: false, code: "quality", error: qualityProblems(quality)[0] ?? "failed the texture checks", quality };
184	  const png = encodePng(d.raster);
185	  return { ok: true, png, sha256: sha(png), width: d.width, alpha, colours: colours.size, quality, stripped: d.skipped, originalSha256: sha(bytes), originalBytes: bytes.length };
186	}
