429	/** Darken a hex colour until its relative luminance is at or below `max` (outline colours read as outlines). */
430	export function darkenTo(hex: string, max = 0.08): string {
431	  let [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
432	  const lin = (c: number) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
433	  const lum = () => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
434	  // start at 70 % so even a dark shade gets visibly darker than the ramp's own darkest (the outline must separate)
435	  r = Math.round(r * 0.7); g = Math.round(g * 0.7); b = Math.round(b * 0.7);
436	  for (let i = 0; i < 40 && lum() > max; i++) { r = Math.round(r * 0.85); g = Math.round(g * 0.85); b = Math.round(b * 0.85); }
437	  return `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
