export const dynamic = "force-dynamic";

/** Change, cancel (at period end) or resume the account's Cyrus plan. */
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user || !(await tokensActiveFor(user))) return NOT_FOUND();
  const rl = checkRateLimit(`cyrus:plan:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many tries. Wait ${rl.retryAfterSec}s.` }, { status: 429 });
  const body = (await req.json().catch(() => ({}))) as { action?: string; tier?: unknown };
  try {
    if (body.action === "change" && isPlanTier(body.tier)) {
      const r = await changePlan(user, body.tier);
      return r.ok ? NextResponse.json({ ok: true, message: r.message }) : NextResponse.json({ error: r.error }, { status: 400 });
    }
    if (body.action === "cancel" || body.action === "resume") {
      const r = await setCancelAtPeriodEnd(user, body.action === "cancel");
      return r.ok ? NextResponse.json({ ok: true }) : NextResponse.json({ error: r.error }, { status: 400 });
    }
    return NextResponse.json({ error: "Unknown action." }, { status: 400 });
  } catch (e) {
    console.error("[cyrus-tokens] plan", user.id, (e as Error).message);
    return NextResponse.json({ error: "We couldn't update your plan. Nothing was charged." }, { status: 502 });
  }
}
