  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.3), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --code-bg: rgb(250 248 255 / 0.8);
  --tok-k: #8a2bc5;
