// Cyrus Texture Studio: how painted pixels are stored (R1b). Pure + client-safe.
//
// PERSISTENCE DECISION. A studio texture is a TextureDoc: the locked generated BASE (an ordinary DSL TextureSpec,
// bounded by MAX_OPS = 400) plus an optional sparse PAINT LAYER on top. Painting never turns into DSL ops, so the
// 400-op limit never applies to strokes: a 64x64 texture can have every pixel painted (4096 entries) and the spec
// keeps its own ops. The paint layer is stored WITH the asset (CyrusProjectAsset provenance, mime TEXTURE_DOC_MIME)
// and composited everywhere the pixels matter: the studio canvas, the quality checks, the pack builder
// (lib/cyrus/textures/pack.ts accepts a doc) and the PNG. Composite = render(spec), then each painted pixel replaces
// the base pixel (always fully opaque) and each "clear" pixel erases it to alpha 0.
//   colors: up to 256 distinct "#rrggbb" (paint is opaque only: the quality bar forbids semi-transparency)
//   set:    flat [pixelIndex, colorIndex, ...] sorted by pixel index, pixelIndex = y * size + x
//   clear:  sorted pixel indices the paint layer erases from the base
// A doc with spec null is all paint (an upload used in a project): its base is transparent.
import { checkSpec, TEXTURE_SIZES, type TextureSpec } from "../textures/dsl";
import { render, type Raster } from "../textures/render";

export type TextureSize = (typeof TEXTURE_SIZES)[number];
export type PaintLayer = { size: TextureSize; colors: string[]; set: number[]; clear: number[] };
/** What a doc decided about a Cyrus candidate (kept in history; the pixels are the doc's own). */
export type DocDecision = { candidate: string; accepted: boolean };
export type TextureDoc = {
  v: 1;
  name: string;
  size: TextureSize;
  /** the locked base; null = no base (all paint) */
  spec: TextureSpec | null;
  paint: PaintLayer | null;
  /**
   * sha256 (canonical JSON) of generated / candidate SPECS this doc was derived from or rejected. A later build that
   * returns one of them unchanged keeps this doc (lib/cyrus/assets/sync.ts studioDocFor), so studio edits survive
   * unrelated change builds.
   */
  supersedes?: string[];
  decision?: DocDecision;
};

export const TEXTURE_DOC_MIME = "application/vnd.nxeon.texture-doc+json";
export const MAX_PAINT_COLORS = 256;
export const MAX_SUPERSEDES = 32;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;
const HEX = /^#[0-9a-f]{6}$/;
const SHA = /^[0-9a-f]{64}$/;

const int = (v: unknown, lo: number, hi: number): v is number => typeof v === "number" && Number.isInteger(v) && v >= lo && v <= hi;

export type DocCheck = { ok: true; doc: TextureDoc } | { ok: false; error: string };

export function checkPaint(raw: unknown, size: TextureSize): { ok: true; paint: PaintLayer } | { ok: false; error: string } {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: "paint must be an object" };
  const r = raw as Record<string, unknown>;
  if (r.size !== size) return { ok: false, error: "paint size must match the texture size" };
  if (!Array.isArray(r.colors) || r.colors.length > MAX_PAINT_COLORS) return { ok: false, error: `paint needs at most ${MAX_PAINT_COLORS} colours` };
  const colors: string[] = [];
  for (const c of r.colors) { if (typeof c !== "string" || !HEX.test(c.toLowerCase())) return { ok: false, error: "paint colours must be #rrggbb" }; colors.push(c.toLowerCase()); }
  const n = size * size;
  if (!Array.isArray(r.set) || r.set.length % 2 !== 0 || r.set.length > n * 2) return { ok: false, error: "paint.set must be [pixel, colour] pairs" };
  if (!Array.isArray(r.clear) || r.clear.length > n) return { ok: false, error: "paint.clear must be a list of pixels" };
  const seen = new Uint8Array(n);
  let last = -1;
  const set: number[] = [];
  for (let k = 0; k < r.set.length; k += 2) {
    const i = r.set[k], c = r.set[k + 1];
    if (!int(i, 0, n - 1) || !int(c, 0, colors.length - 1)) return { ok: false, error: "paint.set has a pixel or colour out of range" };
    if (i <= last) return { ok: false, error: "paint.set must be sorted by pixel, each pixel once" };
    last = i; seen[i] = 1; set.push(i, c);
  }
  last = -1;
  const clear: number[] = [];
  for (const i of r.clear) {
    if (!int(i, 0, n - 1)) return { ok: false, error: "paint.clear has a pixel out of range" };
    if (i <= last) return { ok: false, error: "paint.clear must be sorted, each pixel once" };
    if (seen[i]) return { ok: false, error: "a pixel cannot be both painted and cleared" };
    last = i; clear.push(i);
  }
  return { ok: true, paint: { size, colors, set, clear } };
}

/** Validate an untrusted doc (the API runs this on every save). */
export function checkDoc(raw: unknown): DocCheck {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: "texture doc must be an object" };
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!["v", "name", "size", "spec", "paint", "supersedes", "decision"].includes(k)) return { ok: false, error: `unknown field ${k}` };
  if (r.v !== 1) return { ok: false, error: "texture doc version must be 1" };
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size as number)) return { ok: false, error: "size must be 16, 32 or 64" };
  const size = r.size as TextureSize;
  let spec: TextureSpec | null = null;
  if (r.spec !== null && r.spec !== undefined) {
    const c = checkSpec(r.spec);
    if (!c.ok) return { ok: false, error: `base: ${c.error}` };
    if (c.spec.size !== size) return { ok: false, error: "the base spec size must match the doc size" };
    spec = { ...c.spec, name: r.name };
  }
  let paint: PaintLayer | null = null;
  if (r.paint !== null && r.paint !== undefined) {
    const p = checkPaint(r.paint, size);
    if (!p.ok) return p;
    paint = p.paint.set.length || p.paint.clear.length ? p.paint : null;
  }
  if (!spec && !paint) return { ok: false, error: "a texture needs a base spec or painted pixels" };
  const doc: TextureDoc = { v: 1, name: r.name, size, spec, paint };
  if (r.supersedes !== undefined) {
    if (!Array.isArray(r.supersedes) || r.supersedes.length > MAX_SUPERSEDES || !r.supersedes.every((s) => typeof s === "string" && SHA.test(s))) return { ok: false, error: "supersedes must be up to 32 sha256 values" };
    if (r.supersedes.length) doc.supersedes = [...new Set(r.supersedes as string[])].sort();
  }
  if (r.decision !== undefined) {
    const d = r.decision as Record<string, unknown> | null;
    if (!d || typeof d.candidate !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(d.candidate) || typeof d.accepted !== "boolean") return { ok: false, error: "decision must be { candidate, accepted }" };
    doc.decision = { candidate: d.candidate, accepted: d.accepted };
  }
  return { ok: true, doc };
}

export const docFromSpec = (spec: TextureSpec): TextureDoc => ({ v: 1, name: spec.name, size: spec.size, spec, paint: null });

/** Composite: paint replaces base pixels (opaque), clear erases them. Returns a NEW raster. */
export function applyPaint(base: Raster, paint: PaintLayer | null): Raster {
  const px = new Uint8ClampedArray(base.px);
  if (!paint) return { size: base.size, px };
  if (paint.size !== base.size) throw new Error("paint size does not match the base");
  const rgb = paint.colors.map((h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]);
  for (let k = 0; k < paint.set.length; k += 2) {
    const o = paint.set[k] * 4, c = rgb[paint.set[k + 1]];
    px[o] = c[0]; px[o + 1] = c[1]; px[o + 2] = c[2]; px[o + 3] = 255;
  }
  for (const i of paint.clear) { const o = i * 4; px[o] = px[o + 1] = px[o + 2] = px[o + 3] = 0; }
  return { size: base.size, px };
}

export const blankRaster = (size: number): Raster => ({ size, px: new Uint8ClampedArray(size * size * 4) });

/** The doc's pixels: what the canvas shows, the quality bar checks and the pack ships. */
export function renderDoc(doc: Pick<TextureDoc, "size" | "spec" | "paint">): Raster {
  return applyPaint(doc.spec ? render(doc.spec) : blankRaster(doc.size), doc.paint);
}

/** Editor buffers (RGBA paint + erase mask) -> stored layer. Null when nothing is painted or erased. */
export function paintFromBuffers(size: TextureSize, rgba: Uint8ClampedArray, cut: Uint8Array): PaintLayer | null {
  const n = size * size;
  const colors: string[] = [];
  const index = new Map<string, number>();
  const set: number[] = [];
  const clear: number[] = [];
  for (let i = 0; i < n; i++) {
    const o = i * 4;
    if (rgba[o + 3]) {
      const h = "#" + [rgba[o], rgba[o + 1], rgba[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");
      let c = index.get(h);
      if (c === undefined) { if (colors.length >= MAX_PAINT_COLORS) throw new Error(`the paint layer holds at most ${MAX_PAINT_COLORS} colours`); c = colors.length; colors.push(h); index.set(h, c); }
      set.push(i, c);
    } else if (cut[i]) clear.push(i);
  }
  return set.length || clear.length ? { size, colors, set, clear } : null;
}

/** Stored layer -> editor buffers. */
export function paintToBuffers(size: number, paint: PaintLayer | null): { rgba: Uint8ClampedArray; cut: Uint8Array } {
  const rgba = new Uint8ClampedArray(size * size * 4), cut = new Uint8Array(size * size);
  if (!paint) return { rgba, cut };
  for (let k = 0; k < paint.set.length; k += 2) {
    const o = paint.set[k] * 4, h = paint.colors[paint.set[k + 1]];
    rgba[o] = parseInt(h.slice(1, 3), 16); rgba[o + 1] = parseInt(h.slice(3, 5), 16); rgba[o + 2] = parseInt(h.slice(5, 7), 16); rgba[o + 3] = 255;
  }
  for (const i of paint.clear) cut[i] = 1;
  return { rgba, cut };
}

/** A full raster as an all-paint doc (an uploaded PNG used in a project). Semi-transparent pixels are refused. */
export function docFromRaster(name: string, r: Raster): DocCheck {
  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size)) return { ok: false, error: "size must be 16, 32 or 64" };
  const cut = new Uint8Array(r.size * r.size);
  for (let i = 0; i < r.size * r.size; i++) { const a = r.px[i * 4 + 3]; if (a !== 0 && a !== 255) return { ok: false, error: "semi-transparent pixels are not allowed" }; }
  const paint = paintFromBuffers(r.size as TextureSize, r.px, cut);
  return checkDoc({ v: 1, name, size: r.size, spec: null, paint });
}

/** Pixels touched by the paint layer (painted or erased). */
export const paintCount = (p: PaintLayer | null) => (p ? p.set.length / 2 + p.clear.length : 0);

