/** 5-shade ramp from one colour: darker shades shift cooler, lighter warmer (classic pixel-art hue shifting). */
export function generateRamp(hex: string): string[] {
  const { h, s, l } = hsl(hex);
  return [-2, -1, 0, 1, 2].map((k) => fromHsl((h + k * -8 + 360) % 360, Math.min(1, s * (1 + Math.abs(k) * 0.04)), Math.max(0.06, Math.min(0.94, l + k * 0.12))));
}

const HUES: [number, string][] = [[15, "Red"], [45, "Amber"], [70, "Yellow"], [160, "Green"], [200, "Teal"], [255, "Blue"], [290, "Violet"], [335, "Pink"], [360, "Red"]];
const hueName = (h: number) => HUES.find(([lim]) => h < lim)![1];
const luminance = (hex: string) => { const [r, g, b] = hexRgb(hex); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };

export type RampGroup = { label: string; keys: string[] };
/**
 * Group a spec palette into ramps for the strip. Library templates name their slots (m1-m5 primary, h1-h5 secondary,
 * x1-x5 accent, f* fixed); any other palette is grouped by hue (low saturation = Neutral), dark to light.
 */
export function paletteRamps(palette: Record<string, string>): RampGroup[] {
  const keys = Object.keys(palette);
  const slot = (k: string) => (/^m\d$/.test(k) ? "Primary" : /^h\d$/.test(k) ? "Secondary" : /^x\d$/.test(k) ? "Accent" : /^f[a-z]$/.test(k) ? "Fixed" : null);
  const named = keys.length > 0 && keys.every((k) => slot(k));
  const groups = new Map<string, string[]>();
  for (const k of keys) {
    const { h, s } = hsl(palette[k]);
    const g = named ? slot(k)! : s < 0.18 ? "Neutral" : hueName(h);
    groups.set(g, [...(groups.get(g) ?? []), k]);
  }
  const order = ["Primary", "Secondary", "Accent", "Neutral", "Fixed"];
  return [...groups.entries()]
    .map(([label, ks]) => ({ label, keys: ks.sort((a, b) => luminance(palette[a]) - luminance(palette[b])) }))
    .sort((a, b) => (order.indexOf(a.label) + 1 || 9) - (order.indexOf(b.label) + 1 || 9) || b.keys.length - a.keys.length);
}

/** The mod's Style DNA as shown on the strip (the build prompt's CUSTOM TEXTURES rules). */
export const DNA_RULES = ["Top-left light", "3-5 shade ramps", "No noise or gradients", "Clear background"] as const;
export function outlineColor(spec: TextureSpec | null): string | null {
  const o = spec?.ops.find((x) => x.op === "outline") as { c: string } | undefined;
  return o ? spec!.palette[o.c] ?? null : null;
}
/** A texture follows the Style DNA when the noise and outline checks pass (what the build service measures). */
export const followsDna = (r: QualityReport) => ["noise", "outline"].every((id) => { const c = r.checks.find((x) => x.id === id); return !c || c.status === "pass" || c.status === "not_run"; });

