export const TOOLS = [
  { id: "pencil", label: "Pencil", key: "B" },
  { id: "eraser", label: "Eraser", key: "E" },
  { id: "fill", label: "Fill", key: "G" },
  { id: "picker", label: "Colour picker", key: "I" },
  { id: "select", label: "Select", key: "M" },
  { id: "line", label: "Line", key: "L" },
  { id: "rect", label: "Rectangle", key: "U" },
] as const;
export type ToolId = (typeof TOOLS)[number]["id"];
export const toolForKey = (k: string): ToolId | null => TOOLS.find((t) => t.key.toLowerCase() === k.toLowerCase())?.id ?? null;

export function linePts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
  const pts: Pt[] = [];
  let x0 = a.x, y0 = a.y;
  const dx = Math.abs(b.x - x0), dy = -Math.abs(b.y - y0), sx = x0 < b.x ? 1 : -1, sy = y0 < b.y ? 1 : -1;
  let err = dx + dy;
  for (let guard = 0; guard < 8192; guard++) {
    pts.push([x0, y0]);
    if (x0 === b.x && y0 === b.y) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x0 += sx; }
    if (e2 <= dx) { err += dx; y0 += sy; }
  }
  return pts;
}

export function rectPts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
  const pts: Pt[] = [];
  const x0 = Math.min(a.x, b.x), x1 = Math.max(a.x, b.x), y0 = Math.min(a.y, b.y), y1 = Math.max(a.y, b.y);
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) if (y === y0 || y === y1 || x === x0 || x === x1) pts.push([x, y]);
  return pts;
}

export const inSel = (sel: Sel, x: number, y: number) => !sel || (x >= sel.x && y >= sel.y && x < sel.x + sel.w && y < sel.y + sel.h);
export const selFrom = (a: { x: number; y: number }, b: { x: number; y: number }): Sel => ({ x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x) + 1, h: Math.abs(b.y - a.y) + 1 });

export const hexRgb = (h: string): [number, number, number] => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
export const rgbHex = (p: ArrayLike<number>, o: number) => "#" + [0, 1, 2].map((j) => p[o + j].toString(16).padStart(2, "0")).join("");

/**
 * Paint (color) or erase (null) a set of points on a COPY of the layers: mirror adds the reflected x, the selection
 * clips. Painting clears the erase mark; erasing drops the paint and marks the pixel clear (it erases the base too).
 */
export function stroke(l: Layers, pts: readonly Pt[], color: string | null, o: { mirror?: boolean; sel?: Sel } = {}): Layers {
  const n = l.size, paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
  const rgb = color ? hexRgb(color) : null;
  const put = (x: number, y: number) => {
    if (x < 0 || y < 0 || x >= n || y >= n || !inSel(o.sel ?? null, x, y)) return;
    const i = y * n + x, q = i * 4;
    if (rgb) { paint[q] = rgb[0]; paint[q + 1] = rgb[1]; paint[q + 2] = rgb[2]; paint[q + 3] = 255; cut[i] = 0; }
    else { paint[q] = paint[q + 1] = paint[q + 2] = paint[q + 3] = 0; cut[i] = 1; }
  };
  for (const [x, y] of pts) { put(x, y); if (o.mirror) put(n - 1 - x, y); }
  return { ...l, paint, cut };
}

/** Flood fill: the 4-connected region of the composite's colour at (x, y) (clear counts as a colour), inside the selection. */
export function floodPts(img: Raster, x: number, y: number, sel: Sel = null): Pt[] {
  const n = img.size;
  if (x < 0 || y < 0 || x >= n || y >= n) return [];
  const key = (i: number) => (img.px[i * 4 + 3] ? (img.px[i * 4] << 16) | (img.px[i * 4 + 1] << 8) | img.px[i * 4 + 2] : -1);
  const target = key(y * n + x);
  const seen = new Uint8Array(n * n), out: Pt[] = [], q: Pt[] = [[x, y]];
  while (q.length) {
    const [a, b] = q.pop()!;
    if (a < 0 || b < 0 || a >= n || b >= n) continue;
    const i = b * n + a;
    if (seen[i] || !inSel(sel, a, b)) continue;
    seen[i] = 1;
    if (key(i) !== target) continue;
    out.push([a, b]);
    q.push([a + 1, b], [a - 1, b], [a, b + 1], [a, b - 1]);
  }
  return out;
}

export function pickColor(img: Raster, x: number, y: number): string | null {
  const o = (y * img.size + x) * 4;
  return img.px[o + 3] ? rgbHex(img.px, o) : null;
}

// ---------------------------------------------------------------------------- compare + partial apply

export function changedMask(a: Raster, b: Raster): Uint8Array {
  const n = a.size, m = new Uint8Array(n * n);
  for (let i = 0; i < n * n; i++) { const o = i * 4; if (a.px[o + 3] !== b.px[o + 3] || (b.px[o + 3] && (a.px[o] !== b.px[o] || a.px[o + 1] !== b.px[o + 1] || a.px[o + 2] !== b.px[o + 2]))) m[i] = 1; }
  return m;
}

export type Region = { id: number; pixels: number[]; x: number; y: number; w: number; h: number; colors: string[]; cleared: number };
export const MAX_REGIONS = 8;

/**
 * Changed pixels grouped into 8-connected regions (biggest first): one checkbox each for a partial apply. Regions
 * past MAX_REGIONS merge into the last one so the list stays short.
 */
export function changeRegions(before: Raster, after: Raster): Region[] {
  const n = before.size, m = changedMask(before, after), seen = new Uint8Array(n * n), regions: number[][] = [];
  for (let s = 0; s < n * n; s++) {
    if (!m[s] || seen[s]) continue;
    const px: number[] = [], q = [s];
    seen[s] = 1;
    while (q.length) {
      const i = q.pop()!; px.push(i);
      const x = i % n, y = (i / n) | 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        const a = x + dx, b = y + dy;
        if ((dx || dy) && a >= 0 && b >= 0 && a < n && b < n) { const j = b * n + a; if (m[j] && !seen[j]) { seen[j] = 1; q.push(j); } }
      }
    }
    regions.push(px.sort((a, b) => a - b));
  }
  regions.sort((a, b) => b.length - a.length || a[0] - b[0]);
  if (regions.length > MAX_REGIONS) { const rest = regions.splice(MAX_REGIONS - 1).flat().sort((a, b) => a - b); regions.push(rest); }
  return regions.map((px, id) => {
    let x0 = n, y0 = n, x1 = -1, y1 = -1, cleared = 0;
    const colors = new Set<string>();
    for (const i of px) {
      const x = i % n, y = (i / n) | 0;
      x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
      if (after.px[i * 4 + 3]) colors.add(rgbHex(after.px, i * 4)); else cleared++;
    }
    return { id, pixels: px, x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, colors: [...colors].slice(0, 4), cleared };
  });
}

/** Write the candidate's pixels for the given indices into the paint layer (a non-destructive, partial apply). */
export function applyPixels(l: Layers, cand: Raster, pixels: Iterable<number>): Layers {
  const paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
  for (const i of pixels) {
    const o = i * 4;
    if (cand.px[o + 3]) { paint[o] = cand.px[o]; paint[o + 1] = cand.px[o + 1]; paint[o + 2] = cand.px[o + 2]; paint[o + 3] = 255; cut[i] = 0; }
    else { paint[o] = paint[o + 1] = paint[o + 2] = paint[o + 3] = 0; cut[i] = 1; }
  }
  return { ...l, paint, cut };
}

export function selectionPixels(size: number, sel: Sel): number[] {
  if (!sel) return [];
  const out: number[] = [];
  for (let y = Math.max(0, sel.y); y < Math.min(size, sel.y + sel.h); y++) for (let x = Math.max(0, sel.x); x < Math.min(size, sel.x + sel.w); x++) out.push(y * size + x);
  return out;
}

/** Quality checks whose status differs between two reports (for the candidate card). */
export function qualityDelta(a: QualityReport, b: QualityReport): { id: string; from: string; to: string }[] {
  return b.checks.flatMap((c) => { const o = a.checks.find((x) => x.id === c.id); return o && o.status !== c.status ? [{ id: c.id, from: o.status, to: c.status }] : []; });
}

// ---------------------------------------------------------------------------- palette, ramps, Style DNA

const hsl = (hex: string) => {
  const [r, g, b] = hexRgb(hex).map((v) => v / 255);
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn, l = (mx + mn) / 2;
  const s = d ? d / (1 - Math.abs(2 * l - 1)) : 0;
  let h = 0;
  if (d) h = mx === r ? ((g - b) / d) % 6 : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return { h: (h * 60 + 360) % 360, s, l };
};
const fromHsl = (H: number, S: number, L: number) => {
  const c = (1 - Math.abs(2 * L - 1)) * S, x = c * (1 - Math.abs(((H / 60) % 2) - 1)), m = L - c / 2;
  const [R, G, B] = H < 60 ? [c, x, 0] : H < 120 ? [x, c, 0] : H < 180 ? [0, c, x] : H < 240 ? [0, x, c] : H < 300 ? [x, 0, c] : [c, 0, x];
  return "#" + [R, G, B].map((v) => Math.round(Math.max(0, Math.min(1, v + m)) * 255).toString(16).padStart(2, "0")).join("");
};

/** 5-shade ramp from one colour: darker shades shift cooler, lighter warmer (classic pixel-art hue shifting). */
export function generateRamp(hex: string): string[] {
  const { h, s, l } = hsl(hex);
  return [-2, -1, 0, 1, 2].map((k) => fromHsl((h + k * -8 + 360) % 360, Math.min(1, s * (1 + Math.abs(k) * 0.04)), Math.max(0.06, Math.min(0.94, l + k * 0.12))));
}

const HUES: [number, string][] = [[15, "Red"], [45, "Amber"], [70, "Yellow"], [160, "Green"], [200, "Teal"], [255, "Blue"], [290, "Violet"], [335, "Pink"], [360, "Red"]];
const hueName = (h: number) => HUES.find(([lim]) => h < lim)![1];
const luminance = (hex: string) => { const [r, g, b] = hexRgb(hex); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };

export type RampGroup = { label: string; keys: string[] };
/**
 * Group a spec palette into ramps for the strip. Library templates name their slots (m1-m5 primary, h1-h5 secondary,
 * x1-x5 accent, f* fixed); any other palette is grouped by hue (low saturation = Neutral), dark to light.
 */
export function paletteRamps(palette: Record<string, string>): RampGroup[] {
  const keys = Object.keys(palette);
  const slot = (k: string) => (/^m\d$/.test(k) ? "Primary" : /^h\d$/.test(k) ? "Secondary" : /^x\d$/.test(k) ? "Accent" : /^f[a-z]$/.test(k) ? "Fixed" : null);
  const named = keys.length > 0 && keys.every((k) => slot(k));
  const groups = new Map<string, string[]>();
  for (const k of keys) {
    const { h, s } = hsl(palette[k]);
    const g = named ? slot(k)! : s < 0.18 ? "Neutral" : hueName(h);
    groups.set(g, [...(groups.get(g) ?? []), k]);
  }
  const order = ["Primary", "Secondary", "Accent", "Neutral", "Fixed"];
  return [...groups.entries()]
    .map(([label, ks]) => ({ label, keys: ks.sort((a, b) => luminance(palette[a]) - luminance(palette[b])) }))
    .sort((a, b) => (order.indexOf(a.label) + 1 || 9) - (order.indexOf(b.label) + 1 || 9) || b.keys.length - a.keys.length);
}

/** The mod's Style DNA as shown on the strip (the build prompt's CUSTOM TEXTURES rules). */
export const DNA_RULES = ["Top-left light", "3-5 shade ramps", "No noise or gradients", "Clear background"] as const;
export function outlineColor(spec: TextureSpec | null): string | null {
  const o = spec?.ops.find((x) => x.op === "outline") as { c: string } | undefined;
  return o ? spec!.palette[o.c] ?? null : null;
}
/** A texture follows the Style DNA when the noise and outline checks pass (what the build service measures). */
export const followsDna = (r: QualityReport) => ["noise", "outline"].every((id) => { const c = r.checks.find((x) => x.id === id); return !c || c.status === "pass" || c.status === "not_run"; });

