// Cyrus studios (R1b): who sees the studios and what each plan may do in them. Pure + client-safe; the API runs
// the same functions again on every request (the UI only shows the result as a hint).
//
// TWO gates, both server side:
//  1. Visibility (`studiosOpen`): the Cyrus studio access rule (lib/modbuilder/access.ts modBuilderUser: private
//     preview, or the public once Cyrus launches) AND the NEW setting `cyrus_studios_enabled` (default OFF).
//     While the setting is off ONLY preview accounts see the studios (same rule as the rest of Cyrus), so nothing
//     visible changes for customers until the owner flips it.
//  2. Plan (`studioPlanView`): lib/cyrus/engine-core/asset-gate.ts canAsset. Texture Studio + Texture Library = the
//     top plan (`all`, shown as "All models"); Sound Studio + Sound Library = Saka and up; Free / Katara none. Only
//     create/edit is gated: assets already in a project are always viewable, installable and exportable. An unknown
//     plan fails CLOSED for editing and never for viewing or keeping.
import { canAsset, downgradeSpecAssets, normalizePlan, PLAN_LABEL, type AssetDecision, type AssetPlan } from "../engine-core/asset-gate";

export const STUDIO_KINDS = ["texture", "sound"] as const;
export type StudioKind = (typeof STUDIO_KINDS)[number];
export const STUDIO_NAME: Record<StudioKind, string> = { texture: "Texture Studio", sound: "Sound Studio" };

/**
 * Owner defaults for the open design questions (2026-10-10). Change them here; DOCUMENTATION.md "Cyrus studios UI
 * (R1b)" lists them.
 */
export const STUDIO_DEFAULTS = {
  /** the prompt dock shows an estimated token cost for an asset edit (a change build) */
  showEditEstimate: true,
  /** packs are optional on join; a per-mod "required" option exists (lib/cyrus/packhost applyPackChange `required`) */
  packRequiredByDefault: false,
  /** the mob-skin row is shown as "coming soon", not hidden */
  mobSkin: "coming_soon" as "coming_soon" | "hidden",
  /** phones get a read-only preview + approve / reject (approving saves a revision) */
  mobile: "review_and_approve" as "review_and_approve" | "view_only",
  /** editors open full page; the inspector has a quick-entry Assets tab */
  editorsOpen: "full_page" as const,
} as const;

/** Visibility gate (both inputs come from the server). */
export const studiosOpen = (o: { cyrusUser: boolean; previewUser: boolean; flagOn: boolean }) => o.cyrusUser && (o.previewUser || o.flagOn);

export type StudioPlanView = {
  plan: AssetPlan | null;
  planLabel: string;
  /** may create/edit (studio, library pick, upload, AI edit) per kind */
  edit: Record<StudioKind, AssetDecision>;
};

export function studioPlanView(rawPlan: unknown): StudioPlanView {
  const plan = normalizePlan(rawPlan);
  return {
    plan, planLabel: plan ? PLAN_LABEL[plan] : "Unknown",
    edit: { texture: canAsset(plan, "texture", "edit"), sound: canAsset(plan, "sound", "edit") },
  };
}

/** The plan matrix of the locked-states page (rows straight from the gate). */
export type MatrixRow = { group: string } | { label: string; allowed: (p: AssetPlan) => boolean };
export const PLAN_ORDER: readonly AssetPlan[] = ["free", "katara", "saka", "all"];
export const PLAN_MATRIX: readonly MatrixRow[] = [
  { group: "Studios" },
  { label: "Sound Studio", allowed: (p) => canAsset(p, "sound", "edit").ok },
  { label: "Sound Library", allowed: (p) => canAsset(p, "sound", "create").ok },
  { label: "Texture Studio", allowed: (p) => canAsset(p, "texture", "edit").ok },
  { label: "Texture Library", allowed: (p) => canAsset(p, "texture", "create").ok },
  { group: "Inside builds" },
  { label: "Cyrus makes custom sounds", allowed: (p) => canAsset(p, "sound", "create").ok },
  { label: "Cyrus makes custom textures", allowed: (p) => canAsset(p, "texture", "create").ok },
  { group: "Every plan" },
  { label: "Keep, install, export assets", allowed: (p) => canAsset(p, "texture", "keep").ok && canAsset(p, "sound", "export").ok },
  { label: "Rebuild unchanged", allowed: (p) => canAsset(p, "texture", "rebuild").ok },
  { label: "Mod Packs", allowed: (p) => canAsset(p, "texture", "compose").ok },
  { label: "Import your own mod", allowed: (p) => canAsset(p, "texture", "import").ok },
];

/** What a build says under "Good to know" on this plan: the router downgrade's own notices (sound first). */
export function buildNotices(rawPlan: unknown, ids: { sound?: string | null; texture?: string | null }): string[] {
  const assets = [
    ...(ids.sound ? [{ id: ids.sound, kind: "sound" as const, purpose: "custom sound", source: "generate" as const, requirementIds: [] }] : []),
    ...(ids.texture ? [{ id: ids.texture, kind: "texture" as const, purpose: "custom texture", source: "generate" as const, requirementIds: [] }] : []),
  ];
  return downgradeSpecAssets({ assets }, normalizePlan(rawPlan)).notices;
}

