// Cyrus studios (R1b): the server-side service behind /api/cyrus/assets/v1. Every dependency is injected (host seam):
// the Cyrus tables through `StudioStore`, the build chain through `chain`, the plan through `planOf`, pack hosting
// through `publish`. lib/cyrus/studios/deps.ts wires the real ones; tests use in-memory fakes. No Nxeon internals here.
//
// Model: a project's texture = the newest CyrusProjectAsset row for its key (kind texture) that is not an undecided
// Cyrus candidate. Rows are append-only and content-addressed; the studio never edits a row or a revision: a save is
// a NEW revision (kind "asset") plus a new asset row holding the TextureDoc (spec + sparse paint layer, ./paint.ts).
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
import type { ManifestEntry } from "../engine-core/revisions";
import type { IdentifierKind } from "../engine-core/identifiers";
import type { MbAssets } from "../../modbuilder/types";
import { checkSpec, type TextureSpec } from "../textures/dsl";
import { encodePng } from "../textures/png";
import { QUALITY_VERSION, type QualityReport } from "../textures/quality";
import { buildPack } from "../textures/pack";
import { canonicalJson, sha256Hex } from "../assets/textures";
import { checkDoc, docFromSpec, docQuality, renderDoc, TEXTURE_DOC_MIME, type DocDecision, type TextureDoc } from "./paint";
import { studioPlanView, type StudioPlanView } from "./access";

export type ProjectRow = { id: string; userId: string; namespace: string; rootBuildId: string | null; headRevisionId: string | null; title: string | null };
export type AssetRow = { id: string; projectId: string; revisionId: string; assetKey: string; kind: string; sha256: string; size: number; origin: string; mime: string | null; path: string | null; provenance: unknown; createdAt: Date | string };
export type RevRow = { id: string; seq: number; kind: string; status: string; message: string | null; createdAt: Date | string; manifest: ManifestEntry[]; modBuildId: string | null };

export interface StudioStore {
  projectForRoot(rootBuildId: string): Promise<ProjectRow | null>;
  project(id: string): Promise<ProjectRow | null>;
  assets(projectId: string): Promise<AssetRow[]>;
  assetById(id: string): Promise<AssetRow | null>;
  revisions(projectId: string): Promise<RevRow[]>;
  addRevision(projectId: string, input: AddRevisionInput): Promise<{ id: string; seq: number }>;
  recordAsset(projectId: string, a: RecordAssetInput): Promise<{ id: string }>;
  reserve(projectId: string, kind: IdentifierKind, key: string): Promise<{ fullId: string }>;
}

/** The mod's build chain as far as the studio needs it (read through the existing ModBuild seam). */
export type ChainInfo = {
  rootBuildId: string;
  latestBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  /** ModBuild.result.assets of the newest build that has one */
  assets: MbAssets | null;
  /** builds the Texture Studio started as AI candidates (change builds with the studio marker) */
  candidateBuilds: { id: string; key: string; status: string; error: string | null; createdAt: string }[];
};

export type PublishResult = { ok: true; url: string; sha1: string } | { ok: false; reason: string };
export type StudioServiceDeps = {
  store: StudioStore;
  planOf: (userId: string) => Promise<unknown>;
  chain: (userId: string, rootBuildId: string) => Promise<ChainInfo | null>;
  /** publish a rebuilt pack; absent / not configured = the pack is built and recorded but not hosted */
  publish?: (zip: Buffer) => Promise<PublishResult>;
  /** CYRUS_MANAGED_PLUGINS_REAL: packs are delivered to servers */
  deliveryOn: () => boolean;
};

export class StudioError extends Error {
  constructor(public status: number, public code: string, message: string, public extra: Record<string, unknown> = {}) { super(message); }
}

export const docSha = (doc: TextureDoc) => { const canonical = canonicalJson(doc); return { canonical, sha256: sha256Hex(canonical) }; };
const ts = (d: Date | string) => new Date(d).getTime();
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

/** The TextureDoc an asset row holds (generated rows hold a bare spec; uploads hold no pixels here: library only). */
export function docOfRow(row: AssetRow): TextureDoc | null {
  if (row.kind !== "texture") return null;
  const p = obj(row.provenance);
  if (row.mime === TEXTURE_DOC_MIME) { const d = checkDoc(p.doc); return d.ok ? d.doc : null; }
  if (p.spec) {
    const c = checkSpec(p.spec);
    if (!c.ok) return null;
    // a generated spec supersedes itself: a later build that returns it unchanged keeps any studio edit on top
    return { ...docFromSpec(c.spec), supersedes: [row.sha256] };
  }
  return null;
}

export type TextureEntry = {
  key: string; assetId: string; origin: string; revisionId: string; createdAt: string;
  doc: TextureDoc; quality: QualityReport; specSha256: string | null;
  history: { assetId: string; origin: string; revisionId: string; createdAt: string; doc: TextureDoc; label: string; decision: DocDecision | null }[];
  candidates: { buildId: string; assetId: string; createdAt: string; doc: TextureDoc; specSha256: string }[];
};

const ORIGIN_LABEL: Record<string, string> = { generated: "Generated by Cyrus", edited: "Edited in Texture Studio", library: "From the Texture Library", imported: "Imported", upload: "Uploaded" };
function labelOf(row: AssetRow, doc: TextureDoc): string {
  const p = obj(row.provenance);
  if (doc.decision && !doc.decision.accepted) return "Kept current (Cyrus candidate rejected)";
  if (doc.decision?.accepted) return "Accepted Cyrus candidate";
  if (p.keptStudioEdit) return "Studio edits kept by a build";
  if (row.origin === "generated" && p.kept) return "Kept unchanged by a build";
  return ORIGIN_LABEL[row.origin] ?? row.origin;
}

/** Pure: resolve each texture key's current doc, its history and its open candidates. */
export function resolveTextures(rows: readonly AssetRow[], candidateBuildIds: ReadonlySet<string>): TextureEntry[] {
  const byKey = new Map<string, AssetRow[]>();
  for (const r of rows) if (r.kind === "texture" && r.mime !== "image/png") byKey.set(r.assetKey, [...(byKey.get(r.assetKey) ?? []), r]);
  const out: TextureEntry[] = [];
  for (const [key, list] of byKey) {
    list.sort((a, b) => ts(a.createdAt) - ts(b.createdAt) || (a.id < b.id ? -1 : 1));
    const docs = list.map((r) => ({ r, doc: docOfRow(r) })).filter((x): x is { r: AssetRow; doc: TextureDoc } => !!x.doc);
    const isCand = (r: AssetRow) => r.origin === "generated" && candidateBuildIds.has(String(obj(r.provenance).modBuildId ?? ""));
    const decided = new Set(docs.flatMap((x) => (x.doc.decision ? [x.doc.decision.candidate] : [])));
    const cur = [...docs].reverse().find((x) => !isCand(x.r));
    if (!cur) continue;
    out.push({
      key, assetId: cur.r.id, origin: cur.r.origin, revisionId: cur.r.revisionId, createdAt: new Date(cur.r.createdAt).toISOString(),
      doc: cur.doc, quality: docQuality(cur.doc), specSha256: cur.doc.spec ? sha256Hex(canonicalJson(cur.doc.spec)) : null,
      history: docs.filter((x) => !isCand(x.r)).reverse().slice(0, 20).map((x) => ({ assetId: x.r.id, origin: x.r.origin, revisionId: x.r.revisionId, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, label: labelOf(x.r, x.doc), decision: x.doc.decision ?? null })),
      candidates: docs.filter((x) => isCand(x.r) && !decided.has(String(obj(x.r.provenance).modBuildId))).map((x) => ({ buildId: String(obj(x.r.provenance).modBuildId), assetId: x.r.id, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, specSha256: x.r.sha256 })),
    });
  }
  return out.sort((a, b) => (a.key < b.key ? -1 : 1));
}

/** The current studio doc of one key, for lib/cyrus/assets/sync.ts (a build keeps studio edits it did not replace). */
export async function currentStudioDoc(store: Pick<StudioStore, "assets">, projectId: string, key: string, candidateBuildIds: ReadonlySet<string> = new Set()) {
  const t = resolveTextures(await store.assets(projectId), candidateBuildIds).find((x) => x.key === key);
  if (!t || (t.origin !== "edited" && t.origin !== "library")) return null; // nothing the studio made
  const { canonical, sha256 } = docSha(t.doc);
  return { doc: t.doc, sha256, canonical };
}

