export type PackStatus = {
  state: "hosted" | "delivery_off" | "unhosted" | "failed" | "none";
  sha1: string | null; bytes: number | null; format: number | null; mcVersion: string; required: boolean;
  textures: number; sounds: number; editedSinceBuild: boolean; notices: string[];
};

export function packStatusOf(chain: ChainInfo, deliveryOn: boolean, editedSinceBuild: boolean): PackStatus {
  const a = chain.assets;
  const state: PackStatus["state"] = !a || !a.pack ? (a?.status === "failed" ? "failed" : "none") : !deliveryOn ? "delivery_off" : a.status === "ready" && a.pack.url ? "hosted" : "unhosted";
  return {
    state, sha1: a?.pack?.sha1 ?? null, bytes: a?.pack?.bytes ?? null, format: a?.pack?.format ?? null, mcVersion: chain.mcVersion,
    required: a?.loader?.required ?? false, textures: a?.textures.length ?? 0, sounds: a?.sounds?.length ?? 0, editedSinceBuild, notices: (a?.notices ?? []).slice(0, 6),
  };
}

export type ProjectAssetsView = {
  project: { id: string; namespace: string; title: string | null; rootBuildId: string | null } | null;
  access: StudioPlanView;
  headRevisionId: string | null;
  textures: TextureEntry[];
  sounds: NonNullable<MbAssets["sounds"]>;
  soundRender: MbAssets["soundRender"] | null;
  pack: PackStatus | null;
};

async function ownedProject(deps: StudioServiceDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}
const planView = async (deps: StudioServiceDeps, userId: string) => studioPlanView(await deps.planOf(userId).catch(() => null));

export async function projectAssets(deps: StudioServiceDeps, userId: string, rootBuildId: string): Promise<ProjectAssetsView> {
  const chain = await deps.chain(userId, rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const access = await planView(deps, userId);
  const p = await deps.store.projectForRoot(chain.rootBuildId);
  if (!p || p.userId !== userId) return { project: null, access, headRevisionId: null, textures: [], sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: chain.assets ? packStatusOf(chain, deps.deliveryOn(), false) : null };
  const textures = resolveTextures(await deps.store.assets(p.id), new Set(chain.candidateBuilds.map((b) => b.id)));
  const lastBuildRev = chain.assets?.revisionId ?? null;
  const edited = textures.some((t) => (t.origin === "edited" || t.origin === "library") && t.revisionId !== lastBuildRev);
  return {
    project: { id: p.id, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId }, access, headRevisionId: p.headRevisionId,
    textures, sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: packStatusOf(chain, deps.deliveryOn(), edited),
  };
}

// ---------------------------------------------------------------------------- writes

const gateOrThrow = (d: AssetDecision) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };

export type SaveInput = {
  userId: string; projectId: string; key: string; doc: unknown;
  /** the asset row the edit started from (null = a new texture) */
  baseAssetId: string | null;
  /** the project head the client saw; a newer head = 409 stale_head */
  expectedHeadId: string | null;
  origin?: "edited" | "library";
  decision?: DocDecision | null;
  /** spec sha256 values this doc also supersedes (server-computed: a rejected / accepted candidate) */
  alsoSupersedes?: string[];
  message?: string | null;
  provenance?: Record<string, unknown>;
};
export type SaveResult = { revisionId: string; seq: number; assetId: string; quality: QualityReport; pack: { sha1: string; hosted: boolean } | { skipped: string } };

export async function saveTexture(deps: StudioServiceDeps, input: SaveInput): Promise<SaveResult> {
  const origin = input.origin ?? "edited";
  gateOrThrow(canAsset(await deps.planOf(input.userId).catch(() => null), "texture", origin === "library" ? "create" : "edit"));
  const project = await ownedProject(deps, input.userId, input.projectId);
  const d = checkDoc(input.doc);
  if (!d.ok) throw new StudioError(400, "bad_doc", d.error);
  if (d.doc.name !== input.key) throw new StudioError(400, "bad_doc", "the texture name must match its key");
  const rows = await deps.store.assets(project.id);
  const base = input.baseAssetId ? rows.find((r) => r.id === input.baseAssetId && r.kind === "texture") : null;
  if (input.baseAssetId && !base) throw new StudioError(404, "not_found", "The texture this edit started from is not in this project.");
  if (!input.baseAssetId && rows.some((r) => r.kind === "texture" && r.assetKey === input.key && r.mime !== "image/png")) throw new StudioError(409, "exists", `This mod already has a texture called ${input.key}.`);
  const baseDoc = base ? docOfRow(base) : null;
  // supersedes is computed here, never taken from the client
  const sup = new Set<string>([...(baseDoc?.supersedes ?? []), ...(input.alsoSupersedes ?? [])]);
  const doc: TextureDoc = { ...d.doc, ...(sup.size ? { supersedes: [...sup].sort() } : {}), ...(input.decision ? { decision: input.decision } : {}) };
  if (!sup.size) delete doc.supersedes;
  if (!input.decision) delete doc.decision;
  const quality = docQuality(doc);
  if (quality.verdict === "fail") throw new StudioError(422, "quality", "This texture fails the quality checks, so it can't be saved. Fix the failing checks first.", { quality });
  const { canonical, sha256 } = docSha(doc);
  const png = encodePng(renderDoc(doc));

  // the pack, rebuilt from every current texture of the mod (sound packs are re-rendered by the next build instead)
  const revs = await deps.store.revisions(project.id);
  const head = revs.length ? revs[revs.length - 1] : null;
  if (input.expectedHeadId !== undefined && (head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const chain = project.rootBuildId ? await deps.chain(input.userId, project.rootBuildId) : null;
  const current = resolveTextures(rows, new Set(chain?.candidateBuilds.map((b) => b.id) ?? [])).filter((t) => t.key !== input.key).map((t) => t.doc);
  let pack: SaveResult["pack"] = { skipped: "no build to rebuild the pack for yet" };
  let packEntry: ManifestEntry | null = null;
  if (chain && chain.assets?.sounds?.length) pack = { skipped: "this pack also carries sounds; the next build rebuilds it with your texture" };
  else if (chain) {
    const built = buildPack({ namespace: project.namespace, description: `${chain.pluginName || "This mod"}: custom textures by Cyrus`.slice(0, 100), mcVersion: chain.mcVersion, textures: [...current, doc].slice(0, 24) });
    if (!built.ok) pack = { skipped: built.error };
    else {
      packEntry = { path: `resourcepack/${built.pack.sha1}.zip`, sha256: sha256Hex(built.pack.zip), role: "resourcePack" };
      const pub = deps.publish ? await deps.publish(built.pack.zip).catch((e) => ({ ok: false as const, reason: (e as Error).message })) : { ok: false as const, reason: "pack hosting is not configured" };
      pack = { sha1: built.pack.sha1, hosted: pub.ok };
    }
  }
  const path = `assets/textures/${input.key}.json`;
  const manifest: ManifestEntry[] = [
    ...(head?.manifest ?? []).filter((e) => e.path !== path && !(packEntry && e.role === "resourcePack")),
    { path, sha256, role: "asset" },
    ...(packEntry ? [packEntry] : []),
  ];
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, {
      kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null,
      engine: { toolchain: `cyrus-texture-studio ${QUALITY_VERSION}` },
      message: (input.message ?? (input.decision ? (input.decision.accepted ? `Accepted Cyrus candidate for ${input.key}` : `Kept ${input.key} (rejected a Cyrus candidate)`) : origin === "library" ? `Added ${input.key} from the Texture Library` : `Edited ${input.key} in Texture Studio`)).slice(0, 200),
    });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const asset = await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: input.key, kind: "texture", sha256, size: Buffer.byteLength(canonical), origin, mime: TEXTURE_DOC_MIME, path,
    provenance: { generator: "cyrus-texture-studio", doc, quality, pngSha256: sha256Hex(png), basedOn: base?.id ?? null, packSha1: "sha1" in pack ? pack.sha1 : null, ...(input.provenance ?? {}) },
  });
  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, quality, pack };
}

// ---------------------------------------------------------------------------- candidates (the AI edit interface)

/**
 * The interface the studio uses to ask Cyrus for a texture edit. The real implementation (./candidates.ts
 * changeBuildCandidates) creates a CHANGE BUILD through the existing flow and returns the build's texture when it
 * completes; tests and devhost use fakeCandidates. A candidate is never applied by the backend: the customer
 * accepts (saves a revision), applies part of it, or rejects it.
 */
export type CandidateRequest = { userId: string; user: unknown; project: ProjectRow; chain: ChainInfo; key: string; prompt: string; current: TextureEntry };
export type CandidatePoll =
  | { status: "pending"; note?: string }
  | { status: "ready"; doc: TextureDoc; specSha256: string; summary: string }
  | { status: "failed"; error: string };
export interface CandidateBackend {
  readonly id: string;
  request(r: CandidateRequest): Promise<{ ok: true; requestId: string } | { ok: false; status: number; code: string; error: string }>;
  poll(r: { userId: string; project: ProjectRow; chain: ChainInfo; key: string; requestId: string }): Promise<CandidatePoll>;
}

export const MAX_PROMPT = 600;

export async function textureForEdit(deps: StudioServiceDeps, userId: string, projectId: string, key: string) {
  gateOrThrow(canAsset(await deps.planOf(userId).catch(() => null), "texture", "edit"));
  const project = await ownedProject(deps, userId, projectId);
  if (!project.rootBuildId) throw new StudioError(409, "no_build", "Build the mod once before asking Cyrus to edit its textures.");
  const chain = await deps.chain(userId, project.rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const t = resolveTextures(await deps.store.assets(project.id), new Set(chain.candidateBuilds.map((b) => b.id))).find((x) => x.key === key);
  if (!t) throw new StudioError(404, "not_found", `No texture called ${key} in this mod.`);
  return { project, chain, texture: t };
}

/** Reject a candidate: keep the current doc as a new revision that records the decision (and supersedes the candidate spec). */
export async function rejectCandidate(deps: StudioServiceDeps, backend: CandidateBackend, i: { userId: string; projectId: string; key: string; requestId: string; expectedHeadId: string | null }) {
  const { project, chain, texture } = await textureForEdit(deps, i.userId, i.projectId, i.key);
  const poll = await backend.poll({ userId: i.userId, project, chain, key: i.key, requestId: i.requestId });
  const also = poll.status === "ready" ? [poll.specSha256] : [];
  return saveTexture(deps, {
    userId: i.userId, projectId: project.id, key: i.key, doc: { ...texture.doc, decision: undefined }, baseAssetId: texture.assetId, expectedHeadId: i.expectedHeadId,
    decision: { candidate: i.requestId, accepted: false }, alsoSupersedes: also,
  });
}

/** A deterministic fake: the "edit" applies the Style DNA (drops noise and gradient ops) or adds a 1 px highlight. */
export function fakeCandidates(opts: { readyAfter?: number } = {}): CandidateBackend & { requests: Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }> } {
  const requests = new Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }>();
  let n = 0;
  return {
    id: "fake", requests,
    async request(r) {
      const requestId = `fake${(++n).toString().padStart(4, "0")}${r.key.slice(0, 8)}`;
      requests.set(requestId, { key: r.key, prompt: r.prompt, base: r.current.doc, polls: 0 });
      return { ok: true, requestId };
    },
    async poll(r) {
      const q = requests.get(r.requestId);
      if (!q || q.key !== r.key) return { status: "failed", error: "unknown candidate" };
      if (++q.polls <= (opts.readyAfter ?? 1)) return { status: "pending", note: "Cyrus is drawing a candidate" };
      const spec = q.base.spec;
      if (!spec) return { status: "failed", error: "this texture has no generated base to edit" };
      let ops = spec.ops.filter((o) => o.op !== "noise" && o.op !== "gradient");
      if (ops.length === spec.ops.length) {
        const light = Object.entries(spec.palette).sort((a, b) => parseInt(b[1].slice(1), 16) - parseInt(a[1].slice(1), 16))[0][0];
        const at = Math.max(0, ops.findIndex((o) => o.op === "shade" || o.op === "outline"));
        ops = [...ops.slice(0, at), { op: "px", x: Math.floor(spec.size / 3), y: Math.floor(spec.size / 3), c: light }, ...ops.slice(at)];
      }
      const cand: TextureSpec = { ...spec, ops };
      return { status: "ready", doc: { ...docFromSpec(cand), name: q.key }, specSha256: sha256Hex(canonicalJson(cand)), summary: q.prompt };
    },
  };
}

