// Cyrus Texture Studio (R1b): the REAL candidate backend. SERVER ONLY. A texture edit is a CHANGE BUILD through the
// existing flow (lib/modbuilder/create.ts createModBuild: plan + token gates, asset request ["texture"]); its change
// request starts with CANDIDATE_MARK so the studio can tell candidate builds apart (lib/cyrus/studios/deps.ts reads
// them per chain). When the build succeeds, the portal's normal asset sync records its texture; poll() returns it as
// the candidate. The studio never applies it on its own (accept = a studio revision; reject = a studio revision that
// records the decision). NOT RUN against the real build service in R1b (no paid model calls): tests use the fake.
import type { User } from "@prisma/client";
import { db } from "../../db";
import { createModBuild } from "../../modbuilder/create";
import { syncBuild } from "../../modbuilder/store";
import { isTerminal } from "../../modbuilder/types";
import type { CandidateBackend } from "./service";
import { docOfRow, resolveTextures, type StudioStore } from "./service";

export const CANDIDATE_MARK = "Texture Studio edit of";
export const candidateRequestText = (key: string, prompt: string) =>
  `${CANDIDATE_MARK} "${key}": ${prompt.trim()}\nChange ONLY the texture spec assets/textures/${key}.json; keep every other file, feature and texture exactly as it is.`;
/** The texture key a change request was made for, or null when it is not a studio candidate. */
export function candidateKeyOf(changeRequest: string | null | undefined): string | null {
  const m = /^Texture Studio edit of "([a-z][a-z0-9_]{1,31})":/.exec(changeRequest ?? "");
  return m ? m[1] : null;
}

export function changeBuildCandidates(store: StudioStore): CandidateBackend {
  return {
    id: "change-build",
    async request(r) {
      const base = r.chain.latestBuildId;
      if (!base) return { ok: false, status: 409, code: "no_build", error: "Build the mod once before asking Cyrus to edit its textures." };
      const res = await createModBuild(r.user as User, { changeRequest: candidateRequestText(r.key, r.prompt), baseBuildId: base, mcVersion: r.chain.mcVersion, model: "yakko", assets: ["texture"] });
      if (!res.ok) return { ok: false, status: res.status, code: String(res.json.code ?? "build_refused"), error: String(res.json.error ?? "Cyrus couldn't start that edit.") };
      return { ok: true, requestId: res.build.id };
    },
    async poll(r) {
      let row = await db.modBuild.findUnique({ where: { id: r.requestId } });
      if (!row || row.userId !== r.userId || candidateKeyOf(row.changeRequest) !== r.key) return { status: "failed", error: "unknown candidate" };
      if (!isTerminal(row.status)) { row = await syncBuild(row).catch(() => row!); if (!isTerminal(row.status)) return { status: "pending", note: "Cyrus is building the edit" }; }
      if (row.status !== "succeeded") return { status: "failed", error: row.error || "The edit didn't build. Nothing changed." };
      const asset = (await store.assets(r.project.id)).filter((a) => a.kind === "texture" && a.assetKey === r.key && (a.provenance as { modBuildId?: string } | null)?.modBuildId === row!.id).pop();
      const doc = asset ? docOfRow(asset) : null;
      if (!asset || !doc) return { status: "failed", error: "The edit built, but it did not change this texture." };
      void resolveTextures;
      return { status: "ready", doc, specSha256: asset.sha256, summary: (row.changeRequest ?? "").split("\n")[0].replace(/^Texture Studio edit of "[^"]+": /, "") };
    },
  };
}

