// Cyrus studios (R1b): the REAL dependencies of the studio API. SERVER ONLY. This is the one file that reaches Nxeon:
// through the existing small seams only (the Cyrus access rule modBuilderUser + the preview list, the settings
// table for the flag, tokens tierOf for the plan, the ModBuild chain the studio already lives on, the rate limiter).
// Everything it writes goes to Cyrus tables through lib/cyrus/engine-core/store.ts.
import type { User } from "@prisma/client";
import { db } from "../../db";
import { modBuilderUser } from "../../modbuilder/access";
import { isPreviewUser } from "../../preview-access";
import { getSettingBool } from "../../settings";
import { checkRateLimit } from "../../rate-limit";
import { readBuildAssets } from "../assets/sync";
import { addRevision, recordAsset, reserveIdentifier } from "../engine-core/store";
import { manifestOf } from "../engine-core/store";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { selectPackStore } from "../packhost/config";
import { publishPack } from "../packhost/publish";
import { builtinSoundAssets } from "../library/providers";
import { SoundLibraryProvider, TextureLibraryProvider } from "../library/providers";
import { userAssetProviders } from "../library/user-assets";
import { prismaUserAssetStore } from "../library/user-store";
import { tierOf } from "../tokens/access";
import { studiosOpen } from "./access";
import { candidateKeyOf, changeBuildCandidates } from "./candidates";
import { fakeCandidates, type CandidateBackend, type ChainInfo, type StudioServiceDeps, type StudioStore } from "./service";
import type { StudioApiDeps, StudioViewer, UploadStore } from "./http";
import { localUploadStore } from "./uploads";

export const CYRUS_STUDIOS_FLAG = "cyrus_studios_enabled";

/** The studios setting. Fails CLOSED: a settings/DB error never opens them. */
export async function studiosFlagOn(): Promise<boolean> {
  try { return await getSettingBool(CYRUS_STUDIOS_FLAG, false); } catch { return false; }
}

/** Who may see the studios now: a Cyrus user (preview or public launch) AND (preview OR the setting is on). */
export async function studioViewer(): Promise<(StudioViewer & { user: User }) | null> {
  const user = await modBuilderUser().catch(() => null);
  if (!user) return null;
  const [previewUser, flagOn] = await Promise.all([isPreviewUser(user, "modbuilder").catch(() => false), studiosFlagOn()]);
  return studiosOpen({ cyrusUser: true, previewUser, flagOn }) ? { userId: user.id, user, preview: previewUser } : null;
}

export const prismaStudioStore: StudioStore = {
  projectForRoot: (root) => db.cyrusProject.findUnique({ where: { rootBuildId: root } }),
  project: (id) => db.cyrusProject.findUnique({ where: { id } }),
  assets: (projectId) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" }, take: 2000 }),
  assetById: (id) => db.cyrusProjectAsset.findUnique({ where: { id } }),
  revisions: async (projectId) => (await db.cyrusRevision.findMany({ where: { projectId }, orderBy: { seq: "asc" } })).map((r) => ({ id: r.id, seq: r.seq, kind: r.kind, status: r.status, message: r.message, createdAt: r.createdAt, manifest: manifestOf(r), modBuildId: r.modBuildId })),
  addRevision: async (projectId, input) => { const r = await addRevision(projectId, input); return { id: r.id, seq: r.seq }; },
  recordAsset: async (projectId, a) => ({ id: (await recordAsset(projectId, a)).id }),
  reserve: async (projectId, kind, key) => ({ fullId: (await reserveIdentifier(projectId, kind, key)).fullId }),
};

/** The mod's build chain (ModBuild rows of the owner: the root and every build that names it). */
export async function chainOf(userId: string, rootBuildId: string): Promise<ChainInfo | null> {
  const rows = await db.modBuild.findMany({
    where: { userId, OR: [{ id: rootBuildId }, { rootBuildId }] },
    orderBy: { createdAt: "desc" }, take: 200,
    select: { id: true, rootBuildId: true, status: true, error: true, createdAt: true, mcVersion: true, pluginName: true, changeRequest: true, result: true },
  });
  if (!rows.length) return null;
  const root = rows.find((r) => r.id === rootBuildId) ? rootBuildId : rows[0].rootBuildId ?? rows[0].id;
  const ok = rows.filter((r) => r.status === "succeeded");
  const regular = ok.filter((r) => !candidateKeyOf(r.changeRequest));
  const withAssets = ok.map((r) => readBuildAssets(r.result)).find(Boolean) ?? null;
  return {
    rootBuildId: root, latestBuildId: ok[0]?.id ?? null, mcVersion: (regular[0] ?? ok[0] ?? rows[0]).mcVersion, pluginName: (regular[0] ?? rows[0]).pluginName,
    assets: withAssets,
    candidateBuilds: rows.flatMap((r) => { const key = candidateKeyOf(r.changeRequest); return key ? [{ id: r.id, key, status: r.status, error: r.error, createdAt: r.createdAt.toISOString() }] : []; }),
  };
}

export function serviceDeps(env: Record<string, string | undefined> = process.env): StudioServiceDeps {
  return {
    store: prismaStudioStore,
    planOf: (userId) => tierOf(userId),
    chain: chainOf,
    deliveryOn: () => env[MANAGED_REAL_FLAG] === "1",
    publish: async (zip) => {
      const sel = selectPackStore(env);
      if (!sel.ok) return { ok: false, reason: sel.reason };
      const r = await publishPack(sel.store, zip, { maxBytes: sel.maxBytes });
      return r.ok ? { ok: true, url: r.url, sha1: r.sha1 } : { ok: false, reason: r.error };
    },
  };
}

/** CYRUS_STUDIO_CANDIDATES=fake (devhost / tests only) swaps the change-build backend for the deterministic fake. */
let fake: CandidateBackend | null = null;
export function candidateBackend(env: Record<string, string | undefined> = process.env): CandidateBackend {
  if (env.CYRUS_STUDIO_CANDIDATES === "fake" && env.NODE_ENV !== "production") return (fake ??= fakeCandidates({ readyAfter: 1 }));
  return changeBuildCandidates(prismaStudioStore);
}

export function apiDeps(env: Record<string, string | undefined> = process.env): StudioApiDeps {
  const uploads: UploadStore | null = env.CYRUS_UPLOAD_STORE === "local" && env.NODE_ENV !== "production" ? localUploadStore(env.CYRUS_UPLOAD_DIR || ".data/cyrus-uploads") : null;
  void builtinSoundAssets;
  return {
    viewer: studioViewer,
    service: serviceDeps(env),
    candidates: candidateBackend(env),
    catalog: { providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(prismaUserAssetStore)], planOf: (userId) => tierOf(userId) },
    rateLimit: (key, max, windowMs) => checkRateLimit(`cyrus:studio:${key}`, { max, windowMs }),
    uploads,
  };
}

