// Every texture library template, in a stable order (the manifest and the contact sheets follow it).
import type { TextureTemplate } from "./compile";
import { HANDGUN, ITEM_TEMPLATES } from "./templates-items";
import { MISC_TEMPLATES } from "./templates-misc";
import { TILE_TEMPLATES } from "./templates-tiles";

export const TEMPLATES: readonly TextureTemplate[] = [...ITEM_TEMPLATES, HANDGUN, ...TILE_TEMPLATES, ...MISC_TEMPLATES];
let byId: Map<string, TextureTemplate> | null = null;
export function template(id: string): TextureTemplate | null {
  if (!byId) byId = new Map(TEMPLATES.map((t) => [t.id, t]));
  return byId.get(id) ?? null;
}
