// Cyrus Texture Studio (R1b): how a studio candidate build is recognised (pure). Its change request starts with the
// marker, so the chain reader can tell candidate builds from ordinary change builds without a new column.
export const CANDIDATE_MARK = "Texture Studio edit of";
export const candidateRequestText = (key: string, prompt: string) =>
  `${CANDIDATE_MARK} "${key}": ${prompt.trim()}\nChange ONLY the texture spec assets/textures/${key}.json; keep every other file, feature and texture exactly as it is.`;
/** The texture key a change request was made for, or null when it is not a studio candidate. */
export function candidateKeyOf(changeRequest: string | null | undefined): string | null {
  const m = /^Texture Studio edit of "([a-z][a-z0-9_]{1,31})":/.exec(changeRequest ?? "");
  return m ? m[1] : null;
}

