// Cyrus Texture Studio (R1b): the "In hand" preview scene. Pure + client-safe (unit-tested), no DOM.
// It applies the SAME display transforms the pack writes into the item model (lib/cyrus/textures/display.ts
// displayFor: vanilla `item/handheld` for tools, re-gripped for handguns) to the extruded item, then projects it.
// The transforms are the game's verified values; the hand position, camera and arm are Cyrus's approximation of the
// game's renderer, so the panel is labelled "approximate". Output: depth-sorted polygons in canvas pixels.
import type { Raster } from "../textures/render";
import { applyDisplay, displayFor, gripKindOf, gripPoint, type DisplayTransform, type Vec3 } from "../textures/display";

export type HeldView = "firstperson" | "thirdperson";
export type Poly = { pts: [number, number][]; fill: string; depth: number; part: "arm" | "item" | "fingers" };
export type HeldScene = { polys: Poly[]; grip: [number, number]; kind: "tool" | "handgun"; transform: DisplayTransform };

const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a: Vec3, k: number): Vec3 => [a[0] * k, a[1] * k, a[2] * k];
const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec3): Vec3 => { const l = Math.hypot(...a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const shade = (hex: string, k: number) => "#" + [1, 3, 5].map((i) => Math.max(0, Math.min(255, Math.round(parseInt(hex.slice(i, i + 2), 16) * k))).toString(16).padStart(2, "0")).join("");
const hexOf = (p: Uint8ClampedArray, o: number) => "#" + [p[o], p[o + 1], p[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");

/**
 * Camera conventions (blocks, y up). First person: the vanilla right-hand item origin (ItemInHandRenderer
 * applyItemArmTransform: 0.56, -0.52, -0.72 with no swing) seen through a 70 degree perspective camera looking down -z.
 * Third person: the right hand of a standing player seen from the side (orthographic), the item in the hand frame the
 * player model gives it (hand pointing forward, palm inwards); screen x = forward.
 */
const FP_HAND: Vec3 = [0.56, -0.52, -0.72];
/** third person: hand frame -> world (side view): the arm points forward and down; item x stays forward. */
const TP_HAND: Vec3 = [0, 0, 0];
const tpBasis = (v: Vec3): Vec3 => [-v[2], v[1], v[0]]; // item frame z (toward the camera in first person) = player forward

/** Glove + sleeve: the brand's deep violet, lit from the top-left like the art. */
export const ARM_COLOURS = { sleeve: "#2b2350", sleeveTop: "#3a3070", cuff: "#7c4dff", glove: "#4a3d86", gloveTop: "#6a5bb0", gloveEdge: "#211a40" };

type Pt3 = Vec3;
function boxFaces(center: Pt3, axis: Pt3, len: number, w: number, h: number, up: Pt3): { quad: Pt3[]; normal: Pt3; face: "top" | "side" | "end" | "bottom" | "start" | "back" }[] {
  const a = norm(axis), u0 = norm(sub(up, mul(a, a[0] * up[0] + a[1] * up[1] + a[2] * up[2]))), s = norm(cross(a, u0));
  const c0 = center, c1 = add(center, mul(a, len));
  const corner = (c: Pt3, i: number, j: number) => add(add(c, mul(s, (i * w) / 2)), mul(u0, (j * h) / 2));
  const P = (end: 0 | 1, i: number, j: number) => corner(end ? c1 : c0, i, j);
  return [
    { quad: [P(0, -1, 1), P(1, -1, 1), P(1, 1, 1), P(0, 1, 1)], normal: u0, face: "top" },
    { quad: [P(0, -1, -1), P(0, 1, -1), P(1, 1, -1), P(1, -1, -1)], normal: mul(u0, -1), face: "bottom" },
    { quad: [P(0, 1, -1), P(0, 1, 1), P(1, 1, 1), P(1, 1, -1)], normal: s, face: "side" },
    { quad: [P(0, -1, -1), P(1, -1, -1), P(1, -1, 1), P(0, -1, 1)], normal: mul(s, -1), face: "back" },
    { quad: [P(1, -1, -1), P(1, 1, -1), P(1, 1, 1), P(1, -1, 1)], normal: a, face: "end" },
    { quad: [P(0, -1, -1), P(0, -1, 1), P(0, 1, 1), P(0, 1, -1)], normal: mul(a, -1), face: "start" },
  ];
}

export function heldScene(r: Raster, name: string, view: HeldView, W: number, H: number): HeldScene {
  const kind = gripKindOf(name);
  const disp = displayFor(name, r);
  const t = view === "firstperson" ? disp.firstperson_righthand : disp.thirdperson_righthand;
  const n = r.size, k = 16 / n;
  // model point (0..16) -> world (blocks)
  const world = (v: Vec3): Vec3 => { const p = mul(applyDisplay(t, v), 1 / 16); return view === "firstperson" ? add(FP_HAND, p) : add(TP_HAND, tpBasis(p)); };
  // world -> screen (before fitting) + depth (bigger = nearer the camera)
  const f = 1 / Math.tan((35 * Math.PI) / 180);
  const proj = (p: Vec3): { x: number; y: number; d: number } =>
    view === "firstperson" ? { x: (f * p[0]) / -p[2], y: (-f * p[1]) / -p[2], d: p[2] } : { x: p[0], y: -p[1], d: p[2] };
  const camDir = (p: Vec3): Vec3 => (view === "firstperson" ? norm(mul(p, -1)) : [0, 0, 1]);

  type Q = { w: Pt3[]; fill: string; part: Poly["part"]; bias: number };
  const quads: Q[] = [];
  const visible = (quad: Pt3[], normal: Pt3) => { const c = mul(quad.reduce((s, q) => add(s, q), [0, 0, 0] as Vec3), 1 / quad.length); const d = camDir(c); return normal[0] * d[0] + normal[1] * d[1] + normal[2] * d[2] > 0; };
  // the item: one voxel slab per opaque texel (front, back and the outer edges), like builtin/generated
  const op = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && r.px[(y * n + x) * 4 + 3] > 0;
  const fN = sub(world([8, 8, 9]), world([8, 8, 8]));
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (!op(x, y)) continue;
    const col = hexOf(r.px, (y * n + x) * 4);
    const x0 = x * k, x1 = (x + 1) * k, y0 = 16 - (y + 1) * k, y1 = 16 - y * k;
    const V = (a: number, b: number, z: number) => world([a, b, z]);
    const front = [V(x0, y0, 8.5), V(x1, y0, 8.5), V(x1, y1, 8.5), V(x0, y1, 8.5)];
    const back = [V(x0, y0, 7.5), V(x0, y1, 7.5), V(x1, y1, 7.5), V(x1, y0, 7.5)];
    if (visible(front, fN)) quads.push({ w: front, fill: col, part: "item", bias: 0 });
    else quads.push({ w: back, fill: shade(col, 0.62), part: "item", bias: 0 });
    const edges: [boolean, Pt3[], number][] = [
      [!op(x, y - 1), [V(x0, y1, 7.5), V(x0, y1, 8.5), V(x1, y1, 8.5), V(x1, y1, 7.5)], 0.92],
      [!op(x, y + 1), [V(x0, y0, 7.5), V(x1, y0, 7.5), V(x1, y0, 8.5), V(x0, y0, 8.5)], 0.55],
      [!op(x - 1, y), [V(x0, y0, 7.5), V(x0, y0, 8.5), V(x0, y1, 8.5), V(x0, y1, 7.5)], 0.78],
      [!op(x + 1, y), [V(x1, y0, 7.5), V(x1, y1, 7.5), V(x1, y1, 8.5), V(x1, y0, 8.5)], 0.68],
    ];
    for (const [open, q, s] of edges) if (open) quads.push({ w: q, fill: shade(col, s), part: "item", bias: 0 });
  }
