input.content:
/* Cyrus studios (R1b): Texture Studio, Sound Studio shell, locked states, the mod Assets tab, the Library browser.
   Ported from the approved mockups (/root/agent-notes/cyrus-designs/src/common.css + texture/locked/mod-assets),
   which copy the v5 tokens of app/dashboard/cyrus/studio.css. Everything hangs off .cys inside .cyrus-root and every
   class is cys-* (the portal's globals also define .glass / .btn / .kbd ...). One accent (violet); cyan only means
   "live"; green/amber/red only mean pass/warn/fail. Light theme follows the portal toggle (html[data-theme=light]). */

.cyrus-root .cys {
  --line-3: rgb(167 139 250 / 0.4);
  --accent-solid: #7c4dff; --on-accent: #fff;
  --accent-soft: rgb(167 139 250 / 0.14); --accent-line: rgb(167 139 250 / 0.5);
  --ok: #34e3a2; --warn: #ffb44f; --bad: #ff6b8a;
  --ok-soft: rgb(52 227 162 / 0.1); --warn-soft: rgb(255 180 79 / 0.1); --bad-soft: rgb(255 90 130 / 0.1);
  --pop-shadow: 0 26px 70px -20px rgb(0 0 0 / 0.9), 0 0 0 1px rgb(150 160 255 / 0.14);
  --check-a: #2b2545; --check-b: #221d3a; --well: rgb(7 4 18 / 0.55);
  --mono: var(--font-jb), ui-monospace, monospace; --display: var(--font-space), var(--font-inter), sans-serif;
  --r-sm: 7px; --r: 10px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px;
  position: absolute; inset: 0; display: flex; flex-direction: column; min-width: 0; overflow: hidden; isolation: isolate;
  color: var(--ink); font-size: 13px; line-height: 1.45; font-feature-settings: "ss01", "cv11";
}
html[data-theme="light"] .cyrus-root .cys {
  --line-3: rgb(91 33 182 / 0.32);
  --accent-solid: #7c3aed; --accent-soft: rgb(109 61 240 / 0.09); --accent-line: rgb(109 61 240 / 0.4);
  --ok: #047a52; --warn: #8a4b00; --bad: #c8204f;
  --ok-soft: rgb(4 122 82 / 0.08); --warn-soft: rgb(196 110 0 / 0.08); --bad-soft: rgb(200 32 79 / 0.07);
  --pop-shadow: 0 24px 60px -20px rgb(20 22 60 / 0.3), 0 0 0 1px rgb(30 36 90 / 0.1);
  --check-a: #ece8f6; --check-b: #f8f6fd; --well: #f6f3fd;
}
/* deep space: a faint aurora curtain + sparse stars (the mockup's .cyrus::before) */
.cyrus-root .cys::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(1px 1px at 12% 18%, rgb(255 255 255 / .55), transparent 60%), radial-gradient(1px 1px at 78% 12%, rgb(255 255 255 / .4), transparent 60%),
    radial-gradient(1px 1px at 64% 72%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 28% 84%, rgb(255 255 255 / .3), transparent 60%),
    radial-gradient(1px 1px at 91% 58%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 44% 30%, rgb(255 255 255 / .25), transparent 60%),
    linear-gradient(118deg, transparent 8%, rgb(40 200 170 / .07) 18%, transparent 28%, transparent 62%, rgb(124 77 255 / .07) 74%, transparent 86%),
    radial-gradient(120% 70% at 50% -10%, rgb(60 30 130 / .35), transparent 60%), var(--bg); }
html[data-theme="light"] .cyrus-root .cys::before { background: linear-gradient(118deg, transparent 8%, rgb(8 145 178 / .05) 18%, transparent 30%, transparent 60%, rgb(124 58 237 / .06) 74%, transparent 88%), radial-gradient(120% 70% at 50% -10%, rgb(124 58 237 / .07), transparent 60%), var(--bg); }
.cys :where(button, input, select, textarea) { font: inherit; color: inherit; }
.cys :where(button) { cursor: pointer; background: none; border: 0; padding: 0; text-align: inherit; }
.cys :where(a) { color: inherit; text-decoration: none; }
.cys :focus-visible { outline: 2px solid var(--accent-ink); outline-offset: 2px; border-radius: 6px; }
.cys * { scrollbar-width: thin; scrollbar-color: rgb(var(--glow) / .28) transparent; }
.cys .mono { font-family: var(--mono); }
.cys svg.cys-i { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }

/* surfaces */
.cys .cys-glass { background: linear-gradient(180deg, var(--surface-2), var(--surface)); backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%); border: 1px solid var(--line); box-shadow: var(--panel-shadow); }
.cys .cys-soft { background: var(--surface-soft); border: 1px solid var(--line); }
.cys .cys-hairline { position: relative; }
.cys .cys-hairline::before { content: ""; position: absolute; inset: 0 12% auto 12%; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgb(var(--glow) / .55), rgb(103 232 249 / .4), transparent); }
html[data-theme="light"] .cyrus-root .cys .cys-hairline::before { background: linear-gradient(90deg, transparent, rgb(124 58 237 / .3), rgb(8 145 178 / .25), transparent); }
.cys .cys-panel { border-radius: var(--r-lg); min-height: 0; display: flex; flex-direction: column; }
.cys .cys-ph { display: flex; align-items: center; gap: 8px; padding: 12px 14px 8px; }
.cys .cys-eyebrow { font: 600 10px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
.cys .cys-ph .cys-eyebrow { flex: 1; }
.cys .cys-sep { height: 1px; background: var(--line); margin: 4px 0; }
.cys .cys-hint { font-size: 11.5px; color: var(--muted); line-height: 1.45; }

/* top bar (TopBar.tsx anatomy) */
.cys .cys-top { height: 60px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 18px; position: relative; z-index: 5; }
.cys .cys-brand { display: flex; flex-direction: column; line-height: 1; }
.cys .cys-brand small { margin-top: 4px; font: 600 8px/1 var(--font-inter), sans-serif; letter-spacing: .36em; text-transform: uppercase; color: var(--muted); }
.cys .cys-crumbs { display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px; margin-left: 10px; min-width: 0; }
.cys .cys-crumb { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }
.cys a.cys-crumb:hover { color: var(--ink); background: rgb(var(--glow) / .07); }
.cys .cys-crumb.on { color: var(--ink); font-weight: 500; background: rgb(var(--glow) / .12); }
.cys .cys-crumb .core { width: 10px; height: 10px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--accent) 55%, var(--cyan)); box-shadow: 0 0 8px var(--accent); }
.cys .cys-crumbs > svg { font-size: 11px; color: var(--faint); }
.cys .cys-tbr { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.cys .cys-chip { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px; border-radius: 12px; font-size: 12.5px; font-weight: 500; color: var(--ink-2); white-space: nowrap; }
.cys .cys-chip:hover { color: var(--ink); border-color: var(--line-2); }
.cys .cys-chip.icon { width: 36px; padding: 0; justify-content: center; font-size: 16px; }
.cys .cys-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 12px; }
.cys .cys-seg > * { height: 28px; padding: 0 11px; border-radius: 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.cys .cys-seg > *:hover { color: var(--ink); }
.cys .cys-seg > .on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
.cys .cys-seg.sm > * { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; }
.cys .cys-kbd { font: 500 10px/1 var(--mono); padding: 3px 5px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); background: rgb(var(--glow) / .06); }

/* buttons / fields */
.cys .cys-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: var(--r); font-size: 12.5px; font-weight: 500; color: var(--ink); border: 1px solid var(--line-2); background: var(--surface-2); white-space: nowrap; transition: background .15s, border-color .15s; }
.cys .cys-btn:hover:not(:disabled) { background: rgb(var(--glow) / .14); border-color: var(--line-3); }
.cys .cys-btn.primary { color: var(--on-accent); border-color: transparent; background: var(--accent-solid); box-shadow: inset 0 1px 0 rgb(255 255 255 / .18), 0 8px 22px -12px rgb(124 77 255 / .9); }
.cys .cys-btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: var(--accent-solid); }
.cys .cys-btn.ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
.cys .cys-btn.ghost:hover:not(:disabled) { background: rgb(var(--glow) / .1); color: var(--ink); }
.cys .cys-btn.sm { height: 28px; padding: 0 10px; font-size: 12px; border-radius: 8px; }
.cys .cys-btn.xs { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; gap: 5px; }
.cys .cys-btn:disabled { opacity: .45; cursor: not-allowed; }
.cys .cys-ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: var(--muted); font-size: 16px; transition: color .15s, background .15s; }
.cys .cys-ib:hover:not(:disabled) { color: var(--ink); background: rgb(var(--glow) / .1); }
.cys .cys-ib:disabled { opacity: .4; cursor: not-allowed; }
.cys .cys-ib.on { color: var(--accent-ink); background: var(--accent-soft); }
.cys .cys-ib.sm { width: 24px; height: 24px; font-size: 14px; border-radius: 7px; }
.cys .cys-field { height: 32px; width: 100%; border-radius: var(--r); border: 1px solid var(--line-2); background: var(--well); padding: 0 10px; font-size: 12.5px; color: var(--ink); outline: none; }
.cys .cys-field:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }
.cys .cys-field::placeholder { color: var(--faint); }
.cys select.cys-field { appearance: none; -webkit-appearance: none; padding-right: 26px; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: calc(100% - 13px) 14px, calc(100% - 9px) 14px; background-size: 4px 4px; background-repeat: no-repeat; }

/* tags / status */
.cys .cys-tag { display: inline-flex; align-items: center; gap: 5px; font: 500 9.5px/1 var(--mono); letter-spacing: .08em; text-transform: uppercase; padding: 4px 6px; border-radius: 5px; color: var(--ink-2); border: 1px solid var(--line-2); white-space: nowrap; }
.cys .cys-tag.acc { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .cys-tag.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 40%, transparent); background: var(--ok-soft); }
.cys .cys-tag.warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
.cys .cys-tag.bad { color: var(--bad); border-color: color-mix(in srgb, var(--bad) 40%, transparent); background: var(--bad-soft); }
.cys .cys-tag.dim { color: var(--muted); }
.cys .cys-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--faint); }
.cys .cys-dot.ok { background: var(--ok); } .cys .cys-dot.warn { background: var(--warn); } .cys .cys-dot.bad, .cys .cys-dot.fail { background: var(--bad); }
.cys .cys-dot.live { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.cys .cys-chiprow { display: flex; flex-wrap: wrap; gap: 6px; }
.cys .cys-fchip { white-space: nowrap; flex: none; height: 26px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--line-2); font-size: 11.5px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.cys button.cys-fchip:hover { border-color: var(--line-3); color: var(--ink); }
.cys .cys-fchip.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .cys-fchip i { font-style: normal; font: 500 10px/1 var(--mono); color: var(--muted); }

/* tabs (inspector anatomy) */
.cys .cys-tabs { display: flex; gap: 2px; padding: 0 10px; border-bottom: 1px solid var(--line); flex: none; }
.cys .cys-tab { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); white-space: nowrap; }
.cys .cys-tab:hover { color: var(--ink); }
.cys .cys-tab.on { color: var(--ink); }
.cys .cys-tab.on::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--accent); box-shadow: 0 0 10px rgb(var(--glow) / .7); }
.cys .cys-tab .n { font: 500 10px/1 var(--mono); padding: 2px 5px; border-radius: 5px; background: rgb(var(--glow) / .1); color: var(--muted); }

/* lists */
.cys .cys-row { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: var(--r); color: var(--ink-2); font-size: 12.5px; width: 100%; text-align: left; }
.cys button.cys-row:hover { background: rgb(var(--glow) / .07); color: var(--ink); }
.cys .cys-row.on { background: rgb(var(--glow) / .13); color: var(--ink); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); }
.cys .cys-row .grow { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .cys-row .sub { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); }
.cys .cys-row.later { opacity: .72; cursor: default; }
.cys .cys-thumb { flex: none; width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 8px 8px; border: 1px solid var(--line); overflow: hidden; color: var(--muted); }
.cys .cys-thumb canvas { width: 24px; height: 24px; image-rendering: pixelated; }

/* quality checks */
.cys .cys-verdict { display: flex; align-items: center; gap: 10px; padding: 10px 12px; margin: 10px 12px 6px; border-radius: var(--r-md); border: 1px solid var(--line-2); background: rgb(var(--glow) / .05); }
.cys .cys-verdict b { font: 600 14px/1.1 var(--display); }
.cys .cys-verdict .cys-hint { margin-top: 2px; }
.cys .cys-verdict .badge { margin-left: auto; }
.cys .cys-checks { list-style: none; margin: 0; padding: 4px 12px 12px; display: flex; flex-direction: column; gap: 2px; }
.cys .cys-check { display: grid; grid-template-columns: 18px 1fr auto; gap: 2px 10px; padding: 9px 4px; border-bottom: 1px solid var(--line); }
.cys .cys-check:last-child { border-bottom: 0; }
.cys .cys-check .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; margin-top: 1px; }
.cys .cys-check.pass .ic { color: var(--ok); background: var(--ok-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ok) 40%, transparent); }
.cys .cys-check.warn .ic { color: var(--warn); background: var(--warn-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--warn) 40%, transparent); }
.cys .cys-check.fail .ic { color: var(--bad); background: var(--bad-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bad) 40%, transparent); }
.cys .cys-check.not_run .ic { color: var(--faint); box-shadow: inset 0 0 0 1px var(--line-2); }
.cys .cys-check .id { font: 500 12px/1.3 var(--mono); color: var(--ink); }
.cys .cys-check .val { font: 500 11.5px/1.3 var(--mono); color: var(--ink-2); text-align: right; }
.cys .cys-check .msg { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.4; }
.cys .cys-check .lim { grid-column: 2 / 4; font: 400 10.5px/1.3 var(--mono); color: var(--faint); }
.cys .cys-fix { margin: 4px 12px 12px; display: flex; gap: 8px; align-items: center; padding: 10px 12px; border-radius: 10px; background: var(--warn-soft); border: 1px solid color-mix(in srgb, var(--warn) 35%, transparent); font-size: 12px; color: var(--ink-2); }
.cys .cys-fix svg { color: var(--warn); font-size: 15px; flex: none; }

/* prompt dock (PromptDock anatomy, conic rim while active) */
@property --cys-ang { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
.cys .cys-dock { position: relative; border-radius: 20px; padding: 10px 10px 10px 14px; display: flex; align-items: center; gap: 10px; flex: none; }
.cys .cys-dock::before { content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none; z-index: 2;
  background: conic-gradient(from var(--cys-ang), rgb(var(--glow) / .18) 0%, rgb(103 232 249 / .7) 12%, rgb(var(--glow) / .18) 26%, rgb(var(--glow) / .18) 48%, rgb(240 171 252 / .6) 62%, rgb(var(--glow) / .18) 76%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; }
.cys .cys-dock[data-active="true"]::before, .cys .cys-dock[data-busy="true"]::before { animation: cys-spin 6s linear infinite; }
.cys .cys-dock[data-busy="true"]::before { animation-duration: 1.3s; }
@keyframes cys-spin { to { --cys-ang: 360deg; } }
.cys .cys-dock .route { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border-radius: 8px; font-size: 12px; font-weight: 500; color: var(--accent-ink); background: var(--accent-soft); white-space: nowrap; }
.cys .cys-dock input { flex: 1; min-width: 0; height: 34px; border: 0; outline: none; background: transparent; font-size: 13.5px; color: var(--ink); }
.cys .cys-dock input::placeholder { color: var(--faint); }
.cys .cys-dock .model { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 600; border: 1px solid var(--line); color: var(--ink); }
.cys .cys-dock .send { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; color: #fff; background: var(--accent-solid); font-size: 16px; box-shadow: inset 0 1px 0 rgb(255 255 255 / .2); flex: none; }
.cys .cys-dock .send:disabled { opacity: .5; cursor: not-allowed; }
.cys .cys-dock .est { font: 500 11px/1 var(--mono); color: var(--muted); white-space: nowrap; display: inline-flex; align-items: center; gap: 4px; }
.cys .cys-dock .cyt-est-get { margin-left: 6px; }

/* candidate card (AI edit, non-destructive) */
.cys .cys-cand { margin: 10px 12px; border-radius: var(--r-md); border: 1px dashed var(--accent-line); background: linear-gradient(180deg, rgb(var(--glow) / .07), transparent 70%); }
.cys .cys-cand-h { display: flex; gap: 10px; align-items: flex-start; padding: 12px 12px 8px; }
.cys .cys-cand-h .av { width: 28px; height: 28px; border-radius: 9px; flex: none; display: grid; place-items: center; font-size: 14px; background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / .22), rgb(var(--glow) / .07) 70%); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .25); }
.cys .cys-cand-h b { display: block; font-size: 12.5px; font-weight: 600; }
.cys .cys-cand-h q { display: block; font-size: 12px; color: var(--muted); margin-top: 2px; quotes: "\201C" "\201D"; }
.cys .cys-cand-act { display: flex; gap: 6px; padding: 10px 12px 12px; flex-wrap: wrap; }
.cys .cys-cand-act .cys-btn { flex: 1; }
.cys .cys-ba { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 0 12px; }
.cys .cys-ba figure { margin: 0; border-radius: 10px; border: 1px solid var(--line); padding: 8px; background: var(--well); }
.cys .cys-ba figure.cand { border-color: var(--accent-line); }
.cys .cys-ba figure > div { height: 92px; display: grid; place-items: center; border-radius: 7px; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 12px 12px; }
.cys .cys-ba canvas { width: 80px; height: 80px; image-rendering: pixelated; }
.cys .cys-ba figcaption { display: flex; justify-content: space-between; align-items: center; margin-top: 7px; font: 500 10.5px/1 var(--mono); color: var(--muted); }
.cys .cys-viewseg { padding: 10px 12px 0; display: flex; align-items: center; gap: 8px; }
.cys .cys-viewseg .cys-eyebrow { margin-right: auto; }
.cys .cys-chg { list-style: none; margin: 10px 12px 0; padding: 0; border-radius: 10px; border: 1px solid var(--line); }
.cys .cys-chg li { display: flex; align-items: flex-start; gap: 10px; padding: 9px 10px; font-size: 12px; color: var(--ink-2); }
.cys .cys-chg li + li { border-top: 1px solid var(--line); }
.cys .cys-chg input { accent-color: var(--accent-solid); margin-top: 2px; }
.cys .cys-chg b { display: block; color: var(--ink); font-weight: 500; }
.cys .cys-chg small { font: 400 10.5px/1.35 var(--mono); color: var(--muted); }
.cys .cys-chg .sw { display: inline-block; width: 9px; height: 9px; border-radius: 2px; vertical-align: -1px; box-shadow: 0 0 0 1px var(--line-3); margin-right: 3px; }
.cys .cys-qdelta { display: flex; gap: 6px; flex-wrap: wrap; padding: 10px 12px 0; }
.cys .cys-empty { padding: 24px 18px; text-align: center; color: var(--muted); font-size: 12.5px; }
.cys .cys-empty > svg { font-size: 20px; color: var(--accent-ink); }

/* toast */
.cys .cys-toast { position: absolute; left: 50%; bottom: 22px; transform: translateX(-50%); z-index: 60; padding: 10px 14px; border-radius: 12px; background: var(--solid); box-shadow: var(--pop-shadow); font-size: 12.5px; display: flex; align-items: center; gap: 8px; max-width: min(560px, calc(100% - 32px)); animation: cys-rise .3s var(--ease-out-expo); }
.cys .cys-toast svg { color: var(--ok); flex: none; } .cys .cys-toast.err svg { color: var(--bad); }
@keyframes cys-rise { from { opacity: 0; transform: translate(-50%, 8px); } }

/* ═══ Texture Studio ═══ */
.cys .tx-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 248px minmax(0, 1fr) 340px; gap: 12px; padding: 0 14px 14px; }
.cys .tx-col { display: flex; flex-direction: column; gap: 12px; min-height: 0; min-width: 0; }
.cys .tx-list { padding: 0 6px 8px; display: flex; flex-direction: column; gap: 2px; }
.cys .tx-layer { display: grid; grid-template-columns: 24px 30px 1fr auto; align-items: center; gap: 8px; padding: 6px 6px 6px 4px; border-radius: var(--r); font-size: 12.5px; color: var(--ink-2); border: 1px solid transparent; }
.cys .tx-layer.on { background: rgb(var(--glow) / .13); color: var(--ink); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); }
.cys .tx-layer:hover:not(.on) { background: rgb(var(--glow) / .06); }
.cys .tx-layer .nm { min-width: 0; text-align: left; }
.cys .tx-layer .nm b { display: block; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .tx-layer .nm small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); }
.cys .tx-layer.cand { border: 1px dashed var(--accent-line); }
.cys .tx-steps { flex: 1; min-height: 0; }
.cys .tx-steps .tx-list { overflow: auto; flex: 1; }
.cys .tx-step { display: flex; align-items: center; gap: 8px; width: 100%; padding: 6px 8px; border-radius: 8px; font-size: 12px; color: var(--ink-2); text-align: left; }
.cys .tx-step:hover { background: rgb(var(--glow) / .07); }
.cys .tx-step .n { font: 500 10px/1 var(--mono); color: var(--faint); width: 18px; }
.cys .tx-step.cur { color: var(--ink); background: rgb(var(--glow) / .1); }
.cys .tx-step.cur .n { color: var(--accent-ink); }
.cys .tx-step.future { opacity: .45; }
.cys .tx-bar { display: flex; align-items: center; gap: 8px; height: 46px; padding: 0 8px 0 10px; border-radius: 14px; flex: none; }
.cys .tx-bar .ttl { display: flex; align-items: center; gap: 10px; min-width: 0; }
.cys .tx-bar .ttl b { font: 600 13px/1 var(--mono); }
.cys .tx-bar .ttl small { font-size: 11.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .tx-bar .vr { width: 1px; height: 20px; background: var(--line-2); margin: 0 2px; }
.cys .tx-bar .sp { flex: 1; }
.cys .tx-zoomv { font: 500 11.5px/1 var(--mono); color: var(--ink-2); min-width: 44px; text-align: center; }
.cys .tx-stage { position: relative; flex: 1; min-height: 0; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--line); background: radial-gradient(circle, rgb(var(--glow) / .13) 1px, transparent 1.2px) 0 0 / 22px 22px, var(--well); }
html[data-theme="light"] .cyrus-root .cys .tx-stage { background: radial-gradient(circle, rgb(var(--glow) / .14) 1px, transparent 1.2px) 0 0 / 22px 22px, #f4f1fb; }
.cys .tx-stage canvas.tx-cv { position: absolute; left: 50%; top: 50%; image-rendering: pixelated; box-shadow: 0 0 0 1px var(--line-2), 0 30px 70px -30px rgb(0 0 0 / .8); border-radius: 2px; cursor: crosshair; touch-action: none; }
.cys .tx-tools { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 2px; padding: 5px; border-radius: 14px; z-index: 2; }
.cys .tx-tools .cys-ib { width: 34px; height: 34px; font-size: 17px; position: relative; }
.cys .tx-tools .cys-ib.on { color: var(--on-accent); background: var(--accent-solid); box-shadow: 0 6px 16px -8px rgb(124 77 255 / .9); }
.cys .tx-tools .cys-ib.tog.on { color: var(--accent-ink); background: var(--accent-soft); box-shadow: inset 0 0 0 1px var(--accent-line); }
.cys .tx-tools .cys-sep { width: 22px; margin: 4px auto; }
.cys .tx-tools .cys-ib[data-tip]:hover::after { content: attr(data-tip); position: absolute; left: 42px; top: 50%; transform: translateY(-50%); white-space: pre; padding: 5px 8px; border-radius: 7px; background: var(--solid); box-shadow: var(--pop-shadow); font: 500 11.5px/1 var(--font-inter), sans-serif; color: var(--ink); z-index: 4; }
.cys .tx-well { width: 34px; height: 34px; border-radius: 9px; position: relative; margin-top: 4px; }
.cys .tx-well i { position: absolute; inset: 5px; border-radius: 6px; box-shadow: inset 0 0 0 1px rgb(255 255 255 / .25), 0 0 0 1px rgb(0 0 0 / .4); }
.cys .tx-hud { position: absolute; bottom: 10px; display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 10px; font: 500 11px/1 var(--mono); color: var(--ink-2); z-index: 2; }
.cys .tx-hud.l { left: 60px; } .cys .tx-hud.r { right: 10px; }
.cys .tx-hud .sw { width: 12px; height: 12px; border-radius: 3px; box-shadow: 0 0 0 1px var(--line-3); }
