"use client";
// Pixel helpers for the studios: draw a Raster ({ size, px }) on a canvas at an integer scale, crisp.
import { useEffect, useRef } from "react";
import type { Raster } from "@/lib/cyrus/textures/render";

export function paintRaster(cv: HTMLCanvasElement, r: Raster, scale = 1) {
  const n = r.size;
  cv.width = n * scale; cv.height = n * scale;
  const c = cv.getContext("2d");
  if (!c) return;
  c.imageSmoothingEnabled = false;
  const tmp = document.createElement("canvas");
  tmp.width = n; tmp.height = n;
  tmp.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(r.px), n, n), 0, 0);
  c.clearRect(0, 0, cv.width, cv.height);
  c.drawImage(tmp, 0, 0, n * scale, n * scale);
}

/** A canvas showing a raster (CSS decides the displayed size; image-rendering: pixelated). */
export function RasterCanvas({ raster, scale = 1, className, style, label }: { raster: Raster | null; scale?: number; className?: string; style?: React.CSSProperties; label?: string }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => { if (ref.current && raster) paintRaster(ref.current, raster, scale); }, [raster, scale]);
  return <canvas ref={ref} className={className} style={style} aria-label={label} role={label ? "img" : undefined} />;
}
EOF
