"use client";
// Cyrus TEXTURE STUDIO (R1b), full page. Layout and anatomy from the approved mockup
// (/root/agent-notes/cyrus-designs/texture-studio.html): left = this mod's textures, layers, edit steps; centre = the
// pixel canvas with the tool rail, palette + Style DNA strip and the prompt dock; right = live preview and the
// Cyrus / Checks / History / Library tabs. Narrow screens get the read-only preview + approve view.
// Pure logic lives in lib/cyrus/studios/{editor,paint,held}.ts (unit-tested); this file is state + drawing.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CyrusGlyph } from "@/components/cyrus/icons/CyrusLogo";
import { CyrusTokenEstimate } from "@/components/cyrus-tokens";
import { textureQuality, type QualityReport } from "@/lib/cyrus/textures/quality";
import type { Raster } from "@/lib/cyrus/textures/render";
import { MAX_PALETTE } from "@/lib/cyrus/textures/dsl";
import {
  ALL_VISIBLE, applyPixels, canRedo, canUndo, changeRegions, composite, DNA_RULES, floodPts, followsDna, generateRamp, historyInit, historyJump, historyPush,
  linePts, outlineColor, paintedPixels, paletteRamps, pickColor, qualityDelta, rectPts, selectionPixels, selFrom, stroke, TOOLS, toolForKey,
  type History, type Layers, type Pt, type Region, type Sel, type ToolId, type Visibility,
} from "@/lib/cyrus/studios/editor";
import { paintFromBuffers, paintToBuffers, type TextureDoc } from "@/lib/cyrus/studios/paint";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { heldScene, type HeldView } from "@/lib/cyrus/studios/held";
import { ApiError, studioApi, type AssetsView, type TextureEntry } from "./api";
import { SI } from "./icons";
import { paintRaster, RasterCanvas } from "./raster";
import { LibraryBrowser } from "./LibraryBrowser";
import { StudioShell, useToast, type StudioMod } from "./StudioShell";

type Cand = { requestId: string; status: "pending" | "ready" | "failed"; doc?: TextureDoc; summary: string; picks: Record<number, boolean>; show: boolean; error?: string; persisted: boolean };
type Ed = { entry: TextureEntry; hist: History<Layers>; vis: Visibility; dirty: boolean; accepted: string | null; cand: Cand | null; layer: "paint" | "base" };
type Backdrop = "checker" | "dark" | "light";
type CmpMode = "split" | "onion" | "diff" | "after";

const layersOf = (doc: TextureDoc): Layers => { const b = paintToBuffers(doc.size, doc.paint); return { spec: doc.spec, size: doc.size, paint: b.rgba, cut: b.cut }; };
const docOf = (key: string, l: Layers, tile: TextureDoc["tile"]): TextureDoc => ({ v: 1, name: key, size: l.size as TextureDoc["size"], spec: l.spec, paint: paintFromBuffers(l.size as TextureDoc["size"], l.paint, l.cut), ...(tile ? { tile } : {}) });
const qOf = (r: Raster, tile: TextureDoc["tile"]) => textureQuality(r, tile ? { profile: "tile", tileable: tile.tileable, framed: tile.framed } : {});
const vClass = (v: string) => (v === "pass" ? "ok" : v === "warn" ? "warn" : v === "fail" ? "bad" : "dim");
const kindOf = (e: TextureEntry) => (e.doc.tile ? "block texture" : "item texture");
function edFor(entry: TextureEntry, label: string): Ed {
  const c = entry.candidates[entry.candidates.length - 1];
  return {
    entry, hist: historyInit(label, layersOf(entry.doc)), vis: { ...ALL_VISIBLE }, dirty: false, accepted: null, layer: "paint",
    cand: c ? { requestId: c.buildId, status: "ready", doc: c.doc, summary: "Cyrus edit from a change build", picks: {}, show: false, persisted: true } : null,
  };
}

export function TextureStudio({ mod, initialKey }: { mod: StudioMod; initialKey: string | null }) {
  return (
    <StudioShell mod={mod} current="Texture Studio" studio="texture">
      <TextureStudioBody mod={mod} initialKey={initialKey} />
    </StudioShell>
  );
}

function TextureStudioBody({ mod, initialKey }: { mod: StudioMod; initialKey: string | null }) {
  const toast = useToast();
  const [view, setView] = useState<AssetsView | null>(null);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [eds, setEds] = useState<Record<string, Ed>>({});
  const [cur, setCur] = useState<string | null>(initialKey);

  const load = useCallback(async (keep?: { key: string; label: string }) => {
    try {
      const v = await studioApi.assets(mod.rootId);
      setView(v);
      setEds((prev) => {
        const next: Record<string, Ed> = {};
        for (const t of v.textures) next[t.key] = keep && t.key === keep.key ? edFor(t, keep.label) : prev[t.key] && prev[t.key].dirty ? { ...prev[t.key], entry: t } : edFor(t, `Opened revision ${v.revisionSeq[t.revisionId] ?? ""}`.trim());
        return next;
      });
      setCur((c) => (c && v.textures.some((t) => t.key === c) ? c : v.textures[0]?.key ?? null));
    } catch (e) { setLoadErr((e as Error).message); }
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);

  if (loadErr) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{loadErr}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s textures…</div>;
  if (!view.project || !view.textures.length || !cur || !eds[cur]) {
    return (
      <main className="tx-ws" style={{ gridTemplateColumns: "minmax(0,1fr) 380px" }}>
        <section className="tx-col"><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
          <div className="cys-empty" style={{ maxWidth: 420 }}><SI n="image" /><p><b>This mod has no custom textures yet.</b></p><p className="cys-hint">Ask Cyrus for one in your next change (for example “give the pistol a custom texture”), or add one from the Texture Library.</p></div>
        </div></section>
        <section className="tx-col">{view.project && <div className="cys-panel cys-glass" style={{ flex: 1 }}><LibraryBrowser kind="texture" projectId={view.project.id} uploadsOn={view.uploads} onUse={async (item, key) => { await studioApi.use({ projectId: view.project!.id, ref: item.ref, key, expectedHeadId: view.headRevisionId }); toast(`Added ${key} from the library`); await load(); setCur(key); }} /></div>}</section>
      </main>
    );
  }
  return <Editor mod={mod} view={view} eds={eds} setEds={setEds} cur={cur} setCur={setCur} reload={load} />;
}

function Editor({ mod, view, eds, setEds, cur, setCur, reload }: { mod: StudioMod; view: AssetsView; eds: Record<string, Ed>; setEds: React.Dispatch<React.SetStateAction<Record<string, Ed>>>; cur: string; setCur: (k: string) => void; reload: (keep?: { key: string; label: string }) => Promise<void> }) {
  const toast = useToast();
  const project = view.project!;
  const ed = eds[cur];
  const L = ed.hist.steps[ed.hist.at].snap;
  const n = L.size;
  const tile = ed.entry.doc.tile;
  const update = (k: string, f: (e: Ed) => Ed) => setEds((p) => ({ ...p, [k]: f(p[k]) }));
  const commit = (label: string, next: Layers, extra: Partial<Ed> = {}) => update(cur, (e) => ({ ...e, hist: historyPush(e.hist, label, next), dirty: true, layer: "paint", ...extra }));

  const [tool, setTool] = useState<ToolId>("pencil");
  const [color, setColor] = useState("#e8a63a");
  const [zoom, setZoom] = useState(12);
  const [grid, setGrid] = useState(true);
  const [mirror, setMirror] = useState(false);
  const [sel, setSel] = useState<Sel>(null);
  const [hover, setHover] = useState<{ x: number; y: number } | null>(null);
  const [bd, setBd] = useState<Backdrop>("checker");
  const [cmp, setCmp] = useState<CmpMode>("split");
  const [splitX, setSplitX] = useState(0.5);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [tab, setTab] = useState<"ai" | "qc" | "hist" | "lib">(ed.cand ? "ai" : "qc");
  const [rampGen, setRampGen] = useState<string[] | null>(null);
  const [swatches, setSwatches] = useState<string[]>([]);
  const [prompt, setPrompt] = useState("");
  const [busy, setBusy] = useState(false);
  const [saving, setSaving] = useState(false);
  const [dockActive, setDockActive] = useState(false);

  useEffect(() => { if (ed.entry.doc.spec) { const o = outlineColor(ed.entry.doc.spec); const pal = Object.values(ed.entry.doc.spec.palette); setColor(pal.find((c) => c !== o) ?? pal[0] ?? "#e8a63a"); } setSel(null); setPan({ x: 0, y: 0 }); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [cur]);

  // ---------------------------------------------------------------- derived pixels
  const now = useMemo(() => composite(L, ed.vis), [L, ed.vis]);
  const nowAll = useMemo(() => composite(L), [L]);
  const quality = useMemo(() => qOf(nowAll, tile), [nowAll, tile]);
  const cand = ed.cand;
  const candReady = cand?.status === "ready" && cand.doc ? cand : null;
  const candFull = useMemo(() => (candReady ? composite(L, ALL_VISIBLE, candReady.doc!.spec) : null), [candReady, L]);
  const regions = useMemo<Region[]>(() => (candFull ? changeRegions(nowAll, candFull) : []), [candFull, nowAll]);
  const picked = useMemo(() => regions.filter((r) => candReady?.picks[r.id] !== false), [regions, candReady]);
  const candAfter = useMemo(() => {
    if (!candFull) return null;
    if (picked.length === regions.length) return candFull;
    return composite(applyPixels(L, candFull, picked.flatMap((r) => r.pixels)));
  }, [candFull, picked, regions, L]);
  const candQ = useMemo(() => (candAfter ? qOf(candAfter, tile) : null), [candAfter, tile]);
  const comparing = !!(candReady && candReady.show && candAfter);

  // ---------------------------------------------------------------- canvas
  const cvRef = useRef<HTMLCanvasElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const work = useRef<{ layers: Layers; last?: { x: number; y: number }; a?: { x: number; y: number }; preview?: Pt[]; panFrom?: { x: number; y: number; px: number; py: number } } | null>(null);
  const spaceHeld = useRef(false);
  const draw = useCallback(() => {
    const cv = cvRef.current;
    if (!cv) return;
    const z = zoom, W = n * z;
    if (cv.width !== W) { cv.width = W; cv.height = W; }
    cv.style.width = W + "px"; cv.style.height = W + "px";
    cv.style.transform = `translate(calc(-50% + ${pan.x}px), calc(-50% + ${pan.y}px))`;
    const ctx = cv.getContext("2d")!;
    const dark = document.documentElement.getAttribute("data-theme") !== "light";
    const ca = bd === "dark" ? "#2a2440" : bd === "light" ? "#f2f0f7" : dark ? "#2b2545" : "#ebe7f5";
    const cb = bd === "dark" ? "#2a2440" : bd === "light" ? "#f2f0f7" : dark ? "#221d3a" : "#f9f8fd";
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { ctx.fillStyle = (x + y) & 1 ? ca : cb; ctx.fillRect(x * z, y * z, z, z); }
    const live = work.current ? composite(work.current.layers, ed.vis) : now;
    const put = (r: Raster, x0: number, x1: number, alpha: number) => {
      for (let y = 0; y < n; y++) for (let x = x0; x < x1; x++) { const i = (y * n + x) * 4; if (!r.px[i + 3]) continue; ctx.globalAlpha = alpha; ctx.fillStyle = `rgb(${r.px[i]},${r.px[i + 1]},${r.px[i + 2]})`; ctx.fillRect(x * z, y * z, z, z); }
      ctx.globalAlpha = 1;
    };
    const after = comparing ? candAfter : null;
    if (!after) put(live, 0, n, 1);
    else if (cmp === "split") { const sx = Math.round(splitX * n); put(live, 0, sx, 1); put(after, sx, n, 1); }
    else if (cmp === "onion") { put(live, 0, n, 1); put(after, 0, n, 0.55); }
    else if (cmp === "after") put(after, 0, n, 1);
    else {
      put(live, 0, n, 0.28);
      const cyan = getComputedStyle(cv).getPropertyValue("--cyan").trim() || "#67e8f9";
      ctx.strokeStyle = cyan; ctx.lineWidth = Math.max(1, z / 8);
      for (let i = 0; i < n * n; i++) {
        const o = i * 4; let d = false;
        for (let j = 0; j < 4; j++) if (live.px[o + j] !== after.px[o + j]) d = true;
        if (!d) continue;
        const x = i % n, y = (i / n) | 0;
        if (after.px[o + 3]) { ctx.fillStyle = `rgb(${after.px[o]},${after.px[o + 1]},${after.px[o + 2]})`; ctx.fillRect(x * z, y * z, z, z); }
        ctx.strokeRect(x * z + 0.5, y * z + 0.5, z - 1, z - 1);
      }
    }
    if (grid && z >= 6) {
      ctx.strokeStyle = dark ? "rgba(200,190,255,.08)" : "rgba(60,30,120,.08)"; ctx.lineWidth = 1; ctx.beginPath();
      for (let k = 1; k < n; k++) { ctx.moveTo(k * z + 0.5, 0); ctx.lineTo(k * z + 0.5, W); ctx.moveTo(0, k * z + 0.5); ctx.lineTo(W, k * z + 0.5); }
      ctx.stroke();
      ctx.strokeStyle = dark ? "rgba(200,190,255,.2)" : "rgba(60,30,120,.18)"; ctx.beginPath();
      for (let k = 8; k < n; k += 8) { ctx.moveTo(k * z + 0.5, 0); ctx.lineTo(k * z + 0.5, W); ctx.moveTo(0, k * z + 0.5); ctx.lineTo(W, k * z + 0.5); }
      ctx.stroke();
    }
    const accent = getComputedStyle(cv).getPropertyValue("--accent").trim() || "#a78bfa";
    const cyan = getComputedStyle(cv).getPropertyValue("--cyan").trim() || "#67e8f9";
    if (mirror) { ctx.setLineDash([6, 6]); ctx.strokeStyle = accent; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, W); ctx.stroke(); ctx.setLineDash([]); }
    if (sel) { ctx.setLineDash([4, 3]); ctx.strokeStyle = cyan; ctx.lineWidth = 1.5; ctx.strokeRect(sel.x * z + 0.5, sel.y * z + 0.5, sel.w * z - 1, sel.h * z - 1); ctx.setLineDash([]); }
    if (work.current?.preview) { ctx.globalAlpha = 0.85; ctx.fillStyle = color; for (const [x, y] of work.current.preview) ctx.fillRect(x * z, y * z, z, z); ctx.globalAlpha = 1; }
    if (hover && !after) { ctx.strokeStyle = cyan; ctx.lineWidth = 1.5; ctx.strokeRect(hover.x * z + 0.75, hover.y * z + 0.75, z - 1.5, z - 1.5); }
  }, [zoom, n, pan, bd, now, ed.vis, comparing, candAfter, cmp, splitX, grid, mirror, sel, color, hover]);
  useEffect(() => { draw(); }, [draw]);
  useEffect(() => { const on = () => draw(); window.addEventListener("cyrus:theme", on); const mo = new MutationObserver(on); mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] }); return () => { window.removeEventListener("cyrus:theme", on); mo.disconnect(); }; }, [draw]);

  const fit = useCallback(() => {
    const r = stageRef.current?.getBoundingClientRect();
    if (!r || !r.width) return;
    setZoom(Math.max(4, Math.min(28, Math.floor(Math.min(r.width - 140, r.height - 70) / n))));
    setPan({ x: 0, y: 0 });
  }, [n]);
  useEffect(() => { fit(); const ro = new ResizeObserver(() => fit()); if (stageRef.current) ro.observe(stageRef.current); return () => ro.disconnect(); }, [fit, cur]);

  const cell = (e: React.PointerEvent | PointerEvent) => {
    const r = cvRef.current!.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) / zoom), y = Math.floor((e.clientY - r.top) / zoom);
    return x >= 0 && y >= 0 && x < n && y < n ? { x, y } : null;
  };
  const toolLabel = (t: ToolId) => (t === "eraser" ? "Erase" : t === "line" ? "Line" : t === "rect" ? "Rectangle" : `Pencil ${color}`);
  const onDown = (e: React.PointerEvent) => {
    if (e.button === 1 || spaceHeld.current) { work.current = { layers: L, panFrom: { x: e.clientX, y: e.clientY, px: pan.x, py: pan.y } }; cvRef.current!.setPointerCapture(e.pointerId); return; }
    const c = cell(e);
    if (!c) return;
    cvRef.current!.setPointerCapture(e.pointerId);
    if (candReady?.show) update(cur, (x) => ({ ...x, cand: x.cand ? { ...x.cand, show: false } : null }));
    if (tool === "picker") { const h = pickColor(now, c.x, c.y); if (h) setColor(h); return; }
    if (tool === "fill") { const pts = floodPts(nowAll, c.x, c.y, sel); if (pts.length) commit(`Fill ${color}`, stroke(L, pts, color, { mirror, sel })); return; }
    if (tool === "select") { work.current = { layers: L, a: c }; setSel({ x: c.x, y: c.y, w: 1, h: 1 }); return; }
    if (tool === "line" || tool === "rect") { work.current = { layers: L, a: c, preview: [[c.x, c.y]] }; draw(); return; }
    work.current = { layers: stroke(L, [[c.x, c.y]], tool === "eraser" ? null : color, { mirror, sel }), last: c };
    draw();
  };
  const onMove = (e: React.PointerEvent) => {
    const w = work.current;
    if (w?.panFrom) { setPan({ x: w.panFrom.px + e.clientX - w.panFrom.x, y: w.panFrom.py + e.clientY - w.panFrom.y }); return; }
    const c = cell(e);
    setHover(c);
    if (!w || !c) return;
    if (tool === "select" && w.a) setSel(selFrom(w.a, c));
    else if (tool === "line" && w.a) { w.preview = linePts(w.a, c); draw(); }
    else if (tool === "rect" && w.a) { w.preview = rectPts(w.a, c); draw(); }
    else if (w.last) { w.layers = stroke(w.layers, linePts(w.last, c), tool === "eraser" ? null : color, { mirror, sel }); w.last = c; draw(); }
  };
  const onUp = () => {
    const w = work.current;
    work.current = null;
    if (!w || w.panFrom) return;
    if (tool === "select") { if (sel) toast(`Selection ${sel.w} × ${sel.h}: tools and partial AI apply stay inside it. Esc clears.`); return; }
    if ((tool === "line" || tool === "rect") && w.preview) { commit(toolLabel(tool), stroke(L, w.preview, color, { mirror, sel })); return; }
    if (w.last) commit(toolLabel(tool), w.layers);
  };

  const undo = () => update(cur, (e) => (canUndo(e.hist) ? { ...e, hist: historyJump(e.hist, e.hist.at - 1), dirty: true } : e));
  const redo = () => update(cur, (e) => (canRedo(e.hist) ? { ...e, hist: historyJump(e.hist, e.hist.at + 1), dirty: true } : e));
  const setZ = (z: number) => setZoom(Math.max(4, Math.min(28, z)));

  // keyboard: tools B E G I M L U, X mirror, # grid, +/- zoom, Esc selection, Ctrl Z / Ctrl Shift Z / Ctrl Y
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable)) return;
      const k = e.key.toLowerCase();
      if ((e.ctrlKey || e.metaKey) && k === "z") { e.preventDefault(); if (e.shiftKey) redo(); else undo(); return; }
      if ((e.ctrlKey || e.metaKey) && k === "y") { e.preventDefault(); redo(); return; }
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.key === " ") { spaceHeld.current = true; return; }
      const tl = toolForKey(k);
      if (tl) { setTool(tl); return; }
      if (k === "x") setMirror((m) => !m);
      else if (e.key === "#") setGrid((g) => !g);
      else if (k === "+" || k === "=") setZ(zoom + 2);
      else if (k === "-") setZ(zoom - 2);
      else if (k === "escape") setSel(null);
    };
    const onUpKey = (e: KeyboardEvent) => { if (e.key === " ") spaceHeld.current = false; };
    window.addEventListener("keydown", onKey);
    window.addEventListener("keyup", onUpKey);
    return () => { window.removeEventListener("keydown", onKey); window.removeEventListener("keyup", onUpKey); };
  });
  useEffect(() => {
    const st = stageRef.current;
    if (!st) return;
    const wheel = (e: WheelEvent) => { if (!e.ctrlKey) return; e.preventDefault(); setZoom((z) => Math.max(4, Math.min(28, z + (e.deltaY < 0 ? 1 : -1)))); };
    st.addEventListener("wheel", wheel, { passive: false });
    return () => st.removeEventListener("wheel", wheel);
  }, []);

  // ---------------------------------------------------------------- save, candidates
  const save = async (opts: { acceptCandidate?: string } = {}) => {
    setSaving(true);
    try {
      const doc = docOf(cur, L, tile);
      const r = await studioApi.save(project.id, cur, { doc, baseAssetId: ed.entry.assetId, expectedHeadId: view.headRevisionId, ...(opts.acceptCandidate ?? ed.accepted ? { acceptCandidate: (opts.acceptCandidate ?? ed.accepted)! } : {}) });
      const packMsg = "sha1" in r.pack ? (r.pack.hosted ? " The resource pack was rebuilt; players get it the next time they join." : " The resource pack was rebuilt; delivery to servers isn't switched on yet.") : ` ${r.pack.skipped.charAt(0).toUpperCase()}${r.pack.skipped.slice(1)}.`;
      toast(`Saved as revision ${r.seq}.${packMsg}`);
      await reload({ key: cur, label: `Saved revision ${r.seq}` });
    } catch (e) {
      toast(e instanceof ApiError ? e.message : "Couldn't save. Nothing was changed.", true);
    } finally { setSaving(false); }
  };

  const pollRef = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(pollRef.current), []);
  const poll = useCallback((key: string, requestId: string, tries = 0) => {
    pollRef.current = window.setTimeout(async () => {
      try {
        const r = await studioApi.pollCandidate(project.id, key, requestId);
        if (r.status === "pending" && tries < 400) return poll(key, requestId, tries + 1);
        setBusy(false);
        update(key, (e) => ({ ...e, cand: e.cand && e.cand.requestId === requestId ? (r.status === "ready" ? { ...e.cand, status: "ready", doc: r.doc, summary: e.cand.summary, show: true } : { ...e.cand, status: "failed", error: r.status === "failed" ? r.error : "Cyrus took too long. Try again." }) : e.cand }));
        if (r.status === "ready") { setTab("ai"); toast("Cyrus drew a candidate. Compare it, apply part of it, or reject it."); }
      } catch (e) { setBusy(false); toast((e as Error).message, true); }
    }, tries ? 1500 : 900);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [project.id]);
  const ask = async (text?: string) => {
    const p = (text ?? prompt).trim();
    if (p.length < 4) { toast("Describe the change in a few words.", true); return; }
    setBusy(true); setPrompt("");
    try {
      const r = await studioApi.requestCandidate(project.id, cur, p);
      update(cur, (e) => ({ ...e, cand: { requestId: r.requestId, status: "pending", summary: p, picks: {}, show: false, persisted: r.backend !== "fake" } }));
      setTab("ai");
      poll(cur, r.requestId);
    } catch (e) { setBusy(false); toast(e instanceof ApiError ? e.message : "Cyrus couldn't start that edit.", true); }
  };
  const acceptAll = () => {
    if (!candReady || !candFull) return;
    if (picked.length === regions.length) commit("Accepted Cyrus candidate", { ...L, spec: candReady.doc!.spec }, { cand: null, accepted: candReady.requestId });
    else commit(`Applied ${picked.length} of ${regions.length} changes`, applyPixels(L, candFull, picked.flatMap((r) => r.pixels)), { cand: null, accepted: candReady.requestId });
    toast("Candidate applied as one edit step. Undo brings the old base back.");
  };
  const acceptInSel = () => {
    if (!candReady || !candFull || !sel) return;
    commit("Candidate inside selection", applyPixels(L, candFull, selectionPixels(n, sel)), { cand: null, accepted: candReady.requestId });
  };
  const reject = async () => {
    if (!cand) return;
    if (!ed.dirty && cand.persisted && cand.status === "ready") {
      try { await studioApi.rejectCandidate(project.id, cur, cand.requestId, view.headRevisionId); toast("Candidate rejected. Your texture stays as it is (recorded in History)."); await reload({ key: cur, label: "Rejected Cyrus candidate" }); }
      catch (e) { toast((e as Error).message, true); }
      return;
    }
    update(cur, (e) => ({ ...e, cand: null }));
    toast("Candidate discarded");
  };

  // ---------------------------------------------------------------- side data
  const allRasters = useMemo(() => Object.fromEntries(Object.entries(eds).map(([k, e]) => [k, k === cur ? nowAll : composite(e.hist.steps[e.hist.at].snap)])), [eds, cur, nowAll]);
  const follow = useMemo(() => Object.entries(allRasters).filter(([k, r]) => followsDna(qOf(r, eds[k].entry.doc.tile))).length, [allRasters, eds]);
  const seqOf = (revId: string) => view.revisionSeq[revId] ?? null;
  const curSeq = seqOf(ed.entry.revisionId);
  const palette = L.spec?.palette ?? {};
  const ramps = useMemo(() => paletteRamps(palette), [palette]);
  const outline = outlineColor(L.spec);
  const palCheck = quality.checks.find((c) => c.id === "palette_size");
  const keys = Object.keys(eds).sort();

  const est = STUDIO_DEFAULTS.showEditEstimate ? <CyrusTokenEstimate text={prompt} model="yakko" change /> : null;
  const candCount = cand ? 1 : 0;

  return (
    <>
      <main className="tx-ws" aria-label="Texture Studio">
        {/* LEFT */}
        <section className="tx-col">
          <div className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">{mod.name} · textures</span><span className="cys-tag">{keys.length}</span><button type="button" className="cys-ib sm" title="Add a texture from the library" aria-label="Add a texture from the library" onClick={() => setTab("lib")}><SI n="plus" /></button></div>
            <div className="tx-list">
              {keys.map((k) => {
                const q = k === cur ? quality : qOf(allRasters[k], eds[k].entry.doc.tile);
                return (
                  <button key={k} type="button" className={`cys-row ${k === cur ? "on" : ""}`} onClick={() => setCur(k)} aria-current={k === cur}>
                    <span className="cys-thumb"><RasterCanvas raster={allRasters[k]} scale={2} /></span>
                    <span className="grow"><span className="mono" style={{ fontSize: 12 }}>{k}</span><span className="sub">{eds[k].entry.doc.size}×{eds[k].entry.doc.size} · {kindOf(eds[k].entry)}{eds[k].dirty ? " · unsaved" : ""}</span></span>
                    <span className={`cys-dot ${vClass(q.verdict)}`} title={`Quality ${q.verdict}`} />
                  </button>
                );
              })}
              {STUDIO_DEFAULTS.mobSkin === "coming_soon" && (
                <div className="cys-row later" title="Mob skins need a per-mob UV template; not built yet">
                  <span className="cys-thumb" style={{ opacity: 0.6 }}><SI n="lock" /></span>
                  <span className="grow">Mob skin<span className="sub">coming soon · not editable yet</span></span>
                </div>
              )}
            </div>
          </div>
          <div className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Layers</span></div>
            <div className="tx-list">
              {cand && (
                <div className="tx-layer cand">
                  <button type="button" className="cys-ib sm" disabled={!candReady} aria-label={candReady?.show ? "Stop comparing" : "Compare candidate"} onClick={() => update(cur, (e) => ({ ...e, cand: e.cand ? { ...e.cand, show: !e.cand.show } : null }))}><SI n={candReady?.show ? "eye" : "eyeoff"} /></button>
                  <span className="cys-thumb">{candAfter && <RasterCanvas raster={candAfter} />}</span>
                  <span className="nm"><b>Cyrus candidate</b><small>{cand.status === "pending" ? "drawing…" : cand.status === "failed" ? "failed" : picked.length ? "not applied" : "nothing picked"}</small></span>
                  <span className="cys-tag acc">AI</span>
                </div>
              )}
              <div className={`tx-layer ${ed.layer === "paint" ? "on" : ""}`}>
                <button type="button" className="cys-ib sm" aria-label={ed.vis.paint ? "Hide paint layer" : "Show paint layer"} aria-pressed={ed.vis.paint} onClick={() => update(cur, (e) => ({ ...e, vis: { ...e.vis, paint: !e.vis.paint } }))}><SI n={ed.vis.paint ? "eye" : "eyeoff"} /></button>
                <span className="cys-thumb"><RasterCanvas raster={{ size: n, px: L.paint }} /></span>
                <span className="nm"><b>Paint</b><small>{paintedPixels(L)} px edited</small></span>
                <span />
              </div>
              <div className="tx-layer" onClick={() => toast("The generated base is locked. Paint above it, or ask Cyrus for a candidate.")}>
                <button type="button" className="cys-ib sm" aria-label={ed.vis.base ? "Hide generated base" : "Show generated base"} aria-pressed={ed.vis.base} onClick={(e) => { e.stopPropagation(); update(cur, (x) => ({ ...x, vis: { ...x.vis, base: !x.vis.base } })); }}><SI n={ed.vis.base ? "eye" : "eyeoff"} /></button>
                <span className="cys-thumb"><RasterCanvas raster={composite({ ...L, paint: new Uint8ClampedArray(L.paint.length), cut: new Uint8Array(L.cut.length) })} /></span>
                <span className="nm"><b>Generated base</b><small>{L.spec ? `TextureSpec · ${L.spec.ops.length} ops` : "none (all paint)"}</small></span>
                <span className="cys-ib sm" title="Locked: change it through Cyrus or accept a candidate"><SI n="lock" /></span>
              </div>
            </div>
          </div>
          <div className="cys-panel cys-glass tx-steps">
            <div className="cys-ph"><span className="cys-eyebrow">Edit steps</span><span className="cys-kbd">Ctrl Z</span></div>
            <div className="tx-list">
              {ed.hist.steps.length < 3 && <p className="cys-hint" style={{ padding: "2px 8px 8px", margin: 0 }}>Every stroke, fill or accepted candidate is one step. Click a step to go back to it.</p>}
              {ed.hist.steps.map((s, i) => (
                <button key={i} type="button" className={`tx-step ${i === ed.hist.at ? "cur" : ""} ${i > ed.hist.at ? "future" : ""}`} onClick={() => update(cur, (e) => ({ ...e, hist: historyJump(e.hist, i), dirty: i !== 0 || e.dirty }))}>
                  <span className="n">{i + 1}</span>{s.label}
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* CENTRE */}
        <section className="tx-col">
          <div className="tx-bar cys-soft">
            <div className="ttl"><span className="cys-thumb"><RasterCanvas raster={nowAll} /></span><b>{cur}</b><span className="cys-tag">{n} × {n}</span><small>{kindOf(ed.entry)} · {project.namespace}</small></div>
            <span className="sp" />
            <button type="button" className="cys-ib" onClick={undo} disabled={!canUndo(ed.hist)} title="Undo (Ctrl Z)" aria-label="Undo"><SI n="undo" /></button>
            <button type="button" className="cys-ib" onClick={redo} disabled={!canRedo(ed.hist)} title="Redo (Ctrl Shift Z)" aria-label="Redo"><SI n="redo" /></button>
            <span className="vr" />
            <button type="button" className="cys-ib" onClick={() => setZ(zoom - 2)} title="Zoom out (-)" aria-label="Zoom out"><SI n="minus" /></button>
            <span className="tx-zoomv" aria-live="polite">{zoom * 100}%</span>
            <button type="button" className="cys-ib" onClick={() => setZ(zoom + 2)} title="Zoom in (+)" aria-label="Zoom in"><SI n="plus" /></button>
            <button type="button" className="cys-btn sm ghost" onClick={fit}>Fit</button>
            <span className="vr" />
            <button type="button" className={`cys-btn sm ${ed.dirty ? "primary" : ""}`} disabled={!ed.dirty || saving} onClick={() => void save()} data-testid="save-revision">{saving ? "Saving…" : "Save revision"}</button>
          </div>
          <div className="tx-stage" ref={stageRef}>
            <div className="tx-tools cys-glass" role="toolbar" aria-label="Tools">
              {TOOLS.map((t) => (
                <button key={t.id} type="button" className={`cys-ib ${tool === t.id ? "on" : ""}`} data-tip={`${t.label}  ${t.key}`} aria-label={`${t.label} (${t.key})`} aria-pressed={tool === t.id} onClick={() => setTool(t.id)}><SI n={t.id} /></button>
              ))}
              <div className="cys-sep" />
              <button type="button" className={`cys-ib tog ${mirror ? "on" : ""}`} data-tip="Mirror  X" aria-label="Mirror (X)" aria-pressed={mirror} onClick={() => setMirror(!mirror)}><SI n="mirror" /></button>
              <button type="button" className={`cys-ib tog ${grid ? "on" : ""}`} data-tip="Pixel grid  #" aria-label="Pixel grid (#)" aria-pressed={grid} onClick={() => setGrid(!grid)}><SI n="grid" /></button>
              <div className="tx-well cys-soft" title={`Current colour ${color}`}><i style={{ background: color }} /></div>
            </div>
            <canvas ref={cvRef} className="tx-cv" aria-label={`Pixel canvas, ${cur}, ${n} by ${n}`} data-testid="pixel-canvas"
              onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onPointerLeave={() => setHover(null)} />
            {comparing && <Splitter cvRef={cvRef} stageRef={stageRef} n={n} zoom={zoom} pan={pan} splitX={splitX} setSplitX={setSplitX} show={cmp === "split"} />}
            {comparing && (
              <div className="tx-cmpbar cys-glass">
                <span>Comparing with <b>Cyrus candidate</b></span>
                <div className="cys-seg sm cys-soft">
                  {([["split", "Split"], ["onion", "Onion"], ["diff", "Changed pixels"], ["after", "Candidate"]] as const).map(([v, l]) => <button key={v} type="button" className={cmp === v ? "on" : ""} onClick={() => setCmp(v)}>{l}</button>)}
                </div>
                <button type="button" className="cys-ib sm" aria-label="Stop comparing" onClick={() => update(cur, (e) => ({ ...e, cand: e.cand ? { ...e.cand, show: false } : null }))}><SI n="close" /></button>
              </div>
            )}
            <div className="tx-hud cys-soft l"><Hud c={hover} img={now} palette={palette} L={L} /></div>
            <div className="tx-hud cys-soft r"><span>{n} × {n}</span>
              <div className="cys-seg sm" aria-label="Canvas backdrop">{(["checker", "dark", "light"] as const).map((v) => <button key={v} type="button" className={bd === v ? "on" : ""} onClick={() => setBd(v)}>{v[0].toUpperCase() + v.slice(1)}</button>)}</div>
            </div>
          </div>
          <div className="tx-pal cys-glass">
            <div className="tx-ramps">
              {ramps.map((g) => (
                <div className="tx-ramp" key={g.label}><small>{g.label}</small>
                  <div className="tx-sws">{g.keys.map((k) => <button key={k} type="button" className={`tx-swatch ${palette[k] === color ? "on" : ""}`} style={{ background: palette[k] }} title={`${k} ${palette[k]}`} aria-label={`Colour ${k} ${palette[k]}`} onClick={() => setColor(palette[k])} />)}</div>
                </div>
              ))}
              {swatches.length > 0 && (
                <div className="tx-ramp"><small>Yours</small><div className="tx-sws">{swatches.map((h) => <button key={h} type="button" className={`tx-swatch ${h === color ? "on" : ""}`} style={{ background: h }} title={h} aria-label={`Colour ${h}`} onClick={() => setColor(h)} />)}</div></div>
              )}
              <div className="tx-ramp"><small>New ramp</small><div className="tx-sws plain"><button type="button" className="cys-btn xs" onClick={() => setRampGen(generateRamp(color))}><SI n="sparkle" />From {color}</button></div></div>
            </div>
            <div className="tx-count"><b>{Object.keys(palette).length}</b> / {MAX_PALETTE} palette colours<br /><span style={{ color: `var(--${palCheck?.status === "pass" ? "muted" : "warn"})` }}>{palCheck?.value} distinct after shading</span></div>
            {rampGen && (
              <div className="tx-rampgen">
                <span className="cys-eyebrow" style={{ whiteSpace: "nowrap" }}>Generated ramp</span>
                <div className="tx-sws" style={{ display: "flex" }}>{rampGen.map((h) => <button key={h} type="button" className="tx-swatch gen" style={{ background: h }} title={h} onClick={() => setColor(h)} />)}</div>
                <span className="cys-hint" style={{ flex: 1 }}>5 shades from {rampGen[2]}: shadows shift cooler, highlights warmer.</span>
                <button type="button" className="cys-btn xs primary" onClick={() => { setSwatches((s) => [...new Set([...s, ...rampGen])].slice(-20)); setRampGen(null); toast("Ramp added to your swatches. Painted colours are saved with the paint layer."); }}>Add to swatches</button>
                <button type="button" className="cys-btn xs ghost" onClick={() => setRampGen(null)}>Discard</button>
              </div>
            )}
            <div className="tx-dna">
              <span className="cys-eyebrow" title="Applies to every texture in this mod">Mod Style DNA</span>
              <div className="cys-chiprow">
                {outline && <span className="cys-fchip"><span className="s" style={{ background: outline }} />Outline {outline}</span>}
                {DNA_RULES.map((r) => <span className="cys-fchip" key={r}>{r}</span>)}
              </div>
              <button type="button" className={`cys-btn xs ghost follow ${follow === keys.length ? "" : "warn"}`} onClick={() => { setTab("qc"); toast(`Checked ${keys.length} textures against the mod's Style DNA: ${follow} follow it (noise and outline checks).`); }}><SI n={follow === keys.length ? "check" : "warn"} />{follow} of {keys.length} textures follow</button>
            </div>
          </div>
          <div className="cys-dock cys-glass" data-active={dockActive} data-busy={busy}>
            <span className="route"><SI n="edit" />Edit {cur}</span>
            <input value={prompt} onChange={(e) => setPrompt(e.target.value)} onFocus={() => setDockActive(true)} onBlur={() => setDockActive(false)} onKeyDown={(e) => { if (e.key === "Enter") void ask(); }}
              placeholder={busy ? "Cyrus is drawing a candidate…" : "Ask Cyrus to change this texture…"} aria-label="Ask Cyrus to change this texture" maxLength={600} disabled={busy} />
            {est && <span className="est">{est}</span>}
            <span className="model"><CyrusGlyph id="tx-dock-y" style={{ fontSize: 13 }} />Yakko</span>
            <button type="button" className="send" aria-label="Send" onClick={() => void ask()} disabled={busy || prompt.trim().length < 4}><SI n="send" /></button>
          </div>
        </section>

        {/* RIGHT */}
        <section className="tx-col">
          <LivePreview cur={cur} rasters={allRasters} keys={keys} />
          <div className="cys-panel cys-glass tx-side">
            <div className="cys-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={tab === "ai"} className={`cys-tab ${tab === "ai" ? "on" : ""}`} onClick={() => setTab("ai")}><SI n="sparkle" />Cyrus <span className="n">{candCount}</span></button>
              <button type="button" role="tab" aria-selected={tab === "qc"} className={`cys-tab ${tab === "qc" ? "on" : ""}`} onClick={() => setTab("qc")}><SI n="check" />Checks <span className="n" style={{ color: `var(--${vClass(quality.verdict) === "bad" ? "bad" : vClass(quality.verdict)})` }}>{quality.verdict}</span></button>
              <button type="button" role="tab" aria-selected={tab === "hist"} className={`cys-tab ${tab === "hist" ? "on" : ""}`} onClick={() => setTab("hist")}><SI n="history" />History <span className="n">{ed.entry.history.length}</span></button>
              <button type="button" role="tab" aria-selected={tab === "lib"} className={`cys-tab ${tab === "lib" ? "on" : ""}`} onClick={() => setTab("lib")}><SI n="library" />Library</button>
            </div>
            <div className="tx-pane" role="tabpanel">
              {tab === "ai" && (
                <CandidatePane cur={cur} cand={cand} before={nowAll} after={candAfter} q={quality} candQ={candQ} regions={regions} sel={sel}
                  onPick={(id, on) => update(cur, (e) => ({ ...e, cand: e.cand ? { ...e.cand, picks: { ...e.cand.picks, [id]: on } } : null }))}
                  onShow={() => update(cur, (e) => ({ ...e, cand: e.cand ? { ...e.cand, show: !e.cand.show } : null }))}
                  onAccept={acceptAll} onInSel={acceptInSel} onReject={() => void reject()} />
              )}
              {tab === "qc" && <ChecksPane q={quality} hasCand={!!cand} onFix={() => void ask("Reduce the palette to match the mod's Style DNA: flat areas, no noise, one outline colour")} />}
              {tab === "hist" && (
                <div>
                  {ed.dirty && (
                    <div className="tx-rev"><span className="cys-thumb"><RasterCanvas raster={nowAll} /></span><div><b>Unsaved edits</b><small>{ed.hist.at} edit step{ed.hist.at === 1 ? "" : "s"} since revision {curSeq ?? "?"}</small></div><button type="button" className="cys-btn xs primary" disabled={saving} onClick={() => void save()}>Save</button></div>
                  )}
                  {ed.entry.history.map((h, i) => (
                    <div className="tx-rev" key={h.assetId}>
                      <span className="cys-thumb"><RasterCanvas raster={composite(layersOf(h.doc))} /></span>
                      <div><b>Revision {seqOf(h.revisionId) ?? "?"} · {h.label}{i === 0 && !ed.dirty && <span className="cur">Current</span>}</b><small>{new Date(h.createdAt).toLocaleString(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}</small></div>
                      {(i > 0 || ed.dirty) && <button type="button" className="cys-btn xs ghost" onClick={() => { commit(`Restored revision ${seqOf(h.revisionId) ?? ""}`.trim(), layersOf(h.doc)); toast("Restored as an edit step. Save to make it a new revision."); }}><SI n="restore" />Restore</button>}
                    </div>
                  ))}
                  <p className="cys-hint" style={{ padding: "12px 16px" }}>Every revision keeps its pixels and quality report. Restoring makes a new revision; nothing is deleted.</p>
                </div>
              )}
              {tab === "lib" && <LibraryBrowser kind="texture" projectId={project.id} uploadsOn={view.uploads} onUse={async (item, key) => { await studioApi.use({ projectId: project.id, ref: item.ref, key, expectedHeadId: view.headRevisionId }); toast(`Added ${key} to ${mod.name}. A build wires it to an item.`); await reload(); setCur(key); }} />}
            </div>
          </div>
        </section>
      </main>

      <Narrow keys={keys} cur={cur} setCur={setCur} rasters={allRasters} quality={quality} ed={ed} curSeq={curSeq} candAfter={candAfter} candQ={candQ}
        onApprove={() => { if (!candReady) return; void save({ acceptCandidate: candReady.requestId }); }} onReject={() => void reject()} kind={kindOf(ed.entry)} cand={candReady} />
    </>
  );
}

function Hud({ c, img, palette, L }: { c: { x: number; y: number } | null; img: Raster; palette: Record<string, string>; L: Layers }) {
  if (!c) return <><span>x –</span><span>y –</span></>;
  const o = (c.y * img.size + c.x) * 4;
  const h = img.px[o + 3] ? "#" + [0, 1, 2].map((j) => img.px[o + j].toString(16).padStart(2, "0")).join("") : null;
  const key = h ? Object.entries(palette).find(([, v]) => v === h)?.[0] ?? (L.paint[o + 3] ? "paint" : "derived") : "clear";
  return <><span>x {String(c.x).padStart(2, "0")}</span><span>y {String(c.y).padStart(2, "0")}</span>{h && <><span className="sw" style={{ background: h }} /><span>{h}</span></>}<span style={{ color: "var(--muted)" }}>{key}</span></>;
}

function Splitter({ cvRef, stageRef, n, zoom, pan, splitX, setSplitX, show }: { cvRef: React.RefObject<HTMLCanvasElement | null>; stageRef: React.RefObject<HTMLDivElement | null>; n: number; zoom: number; pan: { x: number; y: number }; splitX: number; setSplitX: (v: number) => void; show: boolean }) {
  const [box, setBox] = useState<{ left: number; top: number; h: number } | null>(null);
  const drag = useRef(false);
  useEffect(() => {
    const cv = cvRef.current, st = stageRef.current;
    if (!cv || !st) return;
    const r = cv.getBoundingClientRect(), s = st.getBoundingClientRect();
    setBox({ left: r.left - s.left + Math.round(splitX * n) * zoom, top: r.top - s.top, h: n * zoom });
  }, [cvRef, stageRef, n, zoom, pan, splitX]);
  if (!show || !box) return null;
  return (
    <div className="tx-split" style={{ left: box.left, top: box.top, height: box.h }} role="slider" aria-label="Compare split" aria-valuenow={Math.round(splitX * 100)} aria-valuemin={0} aria-valuemax={100} tabIndex={0}
      onKeyDown={(e) => { if (e.key === "ArrowLeft") setSplitX(Math.max(0, splitX - 1 / n)); if (e.key === "ArrowRight") setSplitX(Math.min(1, splitX + 1 / n)); }}
      onPointerDown={(e) => { drag.current = true; (e.target as HTMLElement).setPointerCapture(e.pointerId); }}
      onPointerMove={(e) => { if (!drag.current || !cvRef.current) return; const r = cvRef.current.getBoundingClientRect(); setSplitX(Math.max(0, Math.min(1, (e.clientX - r.left) / r.width))); }}
      onPointerUp={() => { drag.current = false; }}>
      <span className="b">Current</span><span className="a">Candidate</span>
    </div>
  );
}

function LivePreview({ cur, rasters, keys }: { cur: string; rasters: Record<string, Raster>; keys: string[] }) {
  const [pv, setPv] = useState<"slot" | "hand" | "tile">("slot");
  const [bg, setBg] = useState<"dark" | "light">("dark");
  const [hv, setHv] = useState<HeldView>("firstperson");
  const r = rasters[cur];
  const hint = pv === "slot" ? "Hotbar, then the item at GUI scale 1, 2 and 4" : pv === "tile" ? "3 × 3 repeat: seams show for block textures" : hv === "firstperson" ? "First person, right hand, with the pack's display transform" : "Third person, right hand, with the pack's display transform";
  return (
    <div className="cys-panel cys-glass tx-prev">
      <div className="cys-ph"><span className="cys-eyebrow">Live preview</span>
        <div className="cys-seg sm cys-soft">{([["slot", "Hotbar"], ["hand", "In hand"], ["tile", "Tile"]] as const).map(([v, l]) => <button key={v} type="button" className={pv === v ? "on" : ""} onClick={() => setPv(v)}>{l}</button>)}</div>
      </div>
      <div className={`tx-pvstage ${bg}`}>
        {pv === "slot" && (
          <div>
            <div className="tx-hotbar">{Array.from({ length: 9 }, (_, i) => <div key={i} className={`tx-slot ${keys[i] === cur ? "sel" : ""}`}>{keys[i] && <RasterCanvas raster={rasters[keys[i]]} />}</div>)}</div>
            <div className="tx-scales">{[[2, "1×"], [4, "2×"], [8, "4×"]].map(([k, l]) => <figure key={l}><RasterCanvas raster={r} style={{ width: 16 * (k as number), height: 16 * (k as number) }} />{l}</figure>)}</div>
          </div>
        )}
        {pv === "tile" && <TileCanvas r={r} />}
        {pv === "hand" && (
          <>
            <HeldCanvas r={r} name={cur} view={hv} />
            <div className="cys-seg sm cys-soft tx-heldtag" aria-label="Hand view">{([["firstperson", "First person"], ["thirdperson", "Third person"]] as const).map(([v, l]) => <button key={v} type="button" className={hv === v ? "on" : ""} onClick={() => setHv(v)}>{l}</button>)}</div>
            <span className="cys-tag dim" style={{ position: "absolute", right: 8, top: 8 }} title="The display transforms are the pack's (the game's own handheld values for tools); the camera and the hand are drawn by Cyrus, so this is close to, not exactly, the game">approximate</span>
          </>
        )}
      </div>
      <div className="tx-pvopts"><span className="cys-hint">{hint}</span>
        <div className="cys-seg sm cys-soft">{(["dark", "light"] as const).map((v) => <button key={v} type="button" className={bg === v ? "on" : ""} onClick={() => setBg(v)}>{v === "dark" ? "Dark" : "Light"}</button>)}</div>
      </div>
    </div>
  );
}

function TileCanvas({ r }: { r: Raster }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const n = r.size; c.width = n * 3; c.height = n * 3;
    const t = document.createElement("canvas"); paintRaster(t, r, 1);
    const x = c.getContext("2d")!; x.clearRect(0, 0, c.width, c.height);
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) x.drawImage(t, i * n, j * n);
  }, [r]);
  return <canvas ref={ref} className="tx-tilecv" aria-label="Tiled 3 by 3" />;
}

function HeldCanvas({ r, name, view }: { r: Raster; name: string; view: HeldView }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const W = c.clientWidth || 316, H = c.clientHeight || 150, dpr = Math.min(2, window.devicePixelRatio || 1);
    c.width = W * dpr; c.height = H * dpr;
    const x = c.getContext("2d")!; x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, W, H);
    const s = heldScene(r, name, view, W, H);
    x.lineJoin = "round";
    for (const p of s.polys) {
      x.beginPath(); p.pts.forEach(([a, b], i) => (i ? x.lineTo(a, b) : x.moveTo(a, b))); x.closePath();
      x.fillStyle = p.fill; x.fill();
      if (p.stroke) { x.strokeStyle = p.stroke; x.lineWidth = 1; x.stroke(); }
      else { x.strokeStyle = p.fill; x.lineWidth = 0.6; x.stroke(); } // close hairline gaps between texels
    }
  }, [r, name, view]);
  return <canvas ref={ref} className="tx-held" aria-label={`${name} held in the right hand, ${view === "firstperson" ? "first" : "third"} person`} />;
}

const ICK: Record<string, string> = { pass: "check", warn: "minus", fail: "close", not_run: "minus" };
function ChecksPane({ q, hasCand, onFix }: { q: QualityReport; hasCand: boolean; onFix: () => void }) {
  const head = { pass: ["Passes the quality bar", "Every check is green."], warn: ["Ships, with warnings", "Warnings never block a build; fixing them keeps the mod consistent."], fail: ["Will not ship as is", "A failing texture can't be saved and is dropped from builds with a notice, never shipped."] }[q.verdict];
  const busy = q.checks.find((c) => c.id === "palette_size" && c.status !== "pass");
  return (
    <div>
      <div className="cys-verdict"><span className={`cys-dot ${vClass(q.verdict)}`} style={{ width: 10, height: 10 }} /><div><b>{head[0]}</b><div className="cys-hint">{head[1]}</div></div><span className="cys-tag badge">{q.version} · {q.size}px</span></div>
      <ul className="cys-checks">
        {q.checks.map((c) => (
          <li key={c.id} className={`cys-check ${c.status}`} data-check={c.id} data-status={c.status}>
            <span className="ic"><SI n={ICK[c.status]} label={c.status} /></span><span className="id">{c.id}</span><span className="val">{c.value === null ? "not run" : c.value}</span>
            <span className="msg">{c.message}</span><span className="lim">limit {c.limit}</span>
          </li>
        ))}
      </ul>
      {busy && !hasCand && <div className="cys-fix"><SI n="warn" /><span style={{ flex: 1 }}>{busy.value} colours is busy for a {q.size}px item.</span><button type="button" className="cys-btn xs" onClick={onFix}>Fix with Cyrus</button></div>}
      <p className="cys-hint" style={{ padding: "0 16px 16px" }}>Checks run on the rendered pixels (paint layer included), the same way the build service checks every texture. They update as you draw.</p>
    </div>
  );
}

function CandidatePane({ cur, cand, before, after, q, candQ, regions, sel, onPick, onShow, onAccept, onInSel, onReject }: {
  cur: string; cand: Cand | null; before: Raster; after: Raster | null; q: QualityReport; candQ: QualityReport | null; regions: Region[]; sel: Sel;
  onPick: (id: number, on: boolean) => void; onShow: () => void; onAccept: () => void; onInSel: () => void; onReject: () => void;
}) {
  if (!cand) return <div className="cys-empty"><SI n="sparkle" /><p>No candidates for <span className="mono">{cur}</span>.</p><p className="cys-hint">Ask below. Cyrus answers with a candidate you can compare, apply in part, or throw away. Your layers are never overwritten.</p></div>;
  if (cand.status === "pending") return <div className="cys-cand"><div className="cys-cand-h"><span className="av"><CyrusGlyph id="cand-y1" /></span><div><b>Cyrus is drawing a candidate</b><q>{cand.summary}</q></div></div><p className="cys-hint" style={{ padding: "0 12px 12px" }}>It arrives as a separate layer to compare. Nothing changes until you accept it.</p></div>;
  if (cand.status === "failed") return <div className="cys-cand"><div className="cys-cand-h"><span className="av"><CyrusGlyph id="cand-y2" /></span><div><b>The edit didn&apos;t come through</b><q>{cand.error ?? "Try again."}</q></div></div><div className="cys-cand-act"><button type="button" className="cys-btn sm ghost" onClick={onReject}>Dismiss</button></div></div>;
  const picked = regions.filter((r) => cand.picks[r.id] !== false).length;
  const delta = candQ ? qualityDelta(q, candQ) : [];
  return (
    <>
      <div className="cys-cand" data-testid="candidate">
        <div className="cys-cand-h"><span className="av"><CyrusGlyph id="cand-y3" /></span><div><b>Candidate · not applied</b><q>{cand.summary}</q></div></div>
        <div className="cys-ba">
          <figure><div><RasterCanvas raster={before} /></div><figcaption><span>Current</span><span className={`cys-tag ${vClass(q.verdict)}`}>{q.verdict}</span></figcaption></figure>
          <figure className="cand"><div>{after && <RasterCanvas raster={after} />}</div><figcaption><span>Candidate</span>{candQ && <span className={`cys-tag ${vClass(candQ.verdict)}`}>{candQ.verdict}</span>}</figcaption></figure>
        </div>
        <div className="cys-viewseg"><span className="cys-eyebrow">On canvas</span><button type="button" className={`cys-btn xs ${cand.show ? "primary" : ""}`} onClick={onShow}><SI n="eye" />{cand.show ? "Comparing" : "Compare"}</button></div>
        {regions.length > 0 ? (
          <ul className="cys-chg">
            {regions.map((r) => (
              <li key={r.id}><input type="checkbox" id={`rg${r.id}`} checked={cand.picks[r.id] !== false} onChange={(e) => onPick(r.id, e.target.checked)} />
                <label htmlFor={`rg${r.id}`}><b>{r.pixels.length === 1 ? `1 pixel at ${r.x},${r.y}` : `${r.pixels.length} pixels around ${r.x + (r.w >> 1)},${r.y + (r.h >> 1)}`}</b>
                  <small>{r.colors.map((c) => <span key={c}><span className="sw" style={{ background: c }} />{c} </span>)}{r.cleared ? `${r.cleared} cleared` : ""}</small></label></li>
            ))}
          </ul>
        ) : <p className="cys-hint" style={{ padding: "8px 12px 0" }}>The candidate looks the same as your texture.</p>}
        <div className="cys-qdelta">{delta.length ? delta.map((d) => <span key={d.id} className={`cys-tag ${vClass(d.to)}`}>{d.id} {d.from} → {d.to}</span>) : <span className="cys-tag dim">quality unchanged · {candQ?.verdict ?? q.verdict}</span>}</div>
        <div className="cys-cand-act">
          <button type="button" className="cys-btn sm primary" disabled={!picked} onClick={onAccept} data-testid="accept-candidate"><SI n="check" />{picked && picked < regions.length ? `Apply ${picked} of ${regions.length}` : "Accept"}</button>
          <button type="button" className="cys-btn sm" disabled={!sel} title={sel ? "Apply only inside the selection" : "Make a selection first (M)"} onClick={onInSel}>Inside selection</button>
          <button type="button" className="cys-btn sm ghost" onClick={onReject}>Reject</button>
        </div>
      </div>
      <p className="cys-hint" style={{ padding: "2px 16px 14px" }}>Accepting replaces the generated base with the candidate&apos;s and adds one edit step; your Paint layer stays on top. Applying part of it paints just those pixels. Nothing is saved until you save a revision.</p>
    </>
  );
}

function Narrow({ keys, cur, setCur, rasters, quality, ed, curSeq, cand, candAfter, candQ, onApprove, onReject, kind }: {
  keys: string[]; cur: string; setCur: (k: string) => void; rasters: Record<string, Raster>; quality: QualityReport; ed: Ed; curSeq: number | null; cand: Cand | null; candAfter: Raster | null; candQ: QualityReport | null; onApprove: () => void; onReject: () => void; kind: string;
}) {
  return (
    <main className="tx-narrow" aria-label="Texture review">
      <div className="n-assets">{keys.map((k) => <button key={k} type="button" className={`cys-soft ${k === cur ? "on" : ""}`} onClick={() => setCur(k)}><span className="cys-thumb"><RasterCanvas raster={rasters[k]} /></span>{k}</button>)}</div>
      <div className="n-card cys-glass">
        <div className="n-h"><div style={{ flex: 1 }}><h1>{cur}</h1><p>{ed.entry.doc.size} × {ed.entry.doc.size} · {kind}{curSeq ? ` · revision ${curSeq}` : ""}</p></div><span className={`cys-tag ${vClass(quality.verdict)}`}>{quality.verdict}</span></div>
        <div className="n-prev"><RasterCanvas raster={rasters[cur]} /></div>
        <div className="n-sum">{quality.checks.map((c) => <span key={c.id} className={`cys-tag ${c.status === "pass" ? "ok" : c.status === "not_run" ? "dim" : vClass(c.status)}`}>{c.id}{c.value !== null ? ` ${c.value}` : ""}</span>)}</div>
      </div>
      {cand && candAfter && (
        <div className="n-card cys-glass"><div className="cys-cand" style={{ margin: 12 }}>
          <div className="cys-cand-h"><span className="av"><CyrusGlyph id="n-cand-y" /></span><div><b>Cyrus candidate</b><q>{cand.summary}</q></div></div>
          <div className="cys-ba">
            <figure><div><RasterCanvas raster={rasters[cur]} /></div><figcaption><span>Current</span><span className={`cys-tag ${vClass(quality.verdict)}`}>{quality.verdict}</span></figcaption></figure>
            <figure className="cand"><div><RasterCanvas raster={candAfter} /></div><figcaption><span>Candidate</span>{candQ && <span className={`cys-tag ${vClass(candQ.verdict)}`}>{candQ.verdict}</span>}</figcaption></figure>
          </div>
          {STUDIO_DEFAULTS.mobile === "review_and_approve" && <div className="cys-cand-act"><button type="button" className="cys-btn primary" onClick={onApprove}><SI n="check" />Approve</button><button type="button" className="cys-btn ghost" onClick={onReject}>Reject</button></div>}
        </div></div>
      )}
      <div className="n-card cys-glass"><div className="n-note"><SI n="info" /><span>Drawing and layers need a larger screen. Here you can look, compare and approve; approvals are saved as a new revision.</span></div></div>
    </main>
  );
}

