input.content:
"use client";
// The shared asset Library browser (Texture Studio now, Sound Studio next): search, category chips, subcategory and
// facet filters, results with previews, a detail card with the licence ledger, and "Use in project". Backed by
// GET /api/cyrus/assets/v1/library (lib/cyrus/library browse service, plan-gated server side).
// The Sound Studio plugs in with kind="sound" and its own `renderLead` (a play button) and `onUse`.
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { renderDoc } from "@/lib/cyrus/studios/paint";
import { ApiError, studioApi, type LibraryItem } from "./api";
import { SI } from "./icons";
import { RasterCanvas } from "./raster";
import { useToast } from "./StudioShell";

type Result = Awaited<ReturnType<typeof studioApi.browse>>;
const FACETS: Record<"texture" | "sound", { key: string; label: string }[]> = {
  texture: [{ key: "size", label: "Any size" }, { key: "material", label: "Any material" }],
  sound: [{ key: "durationClass", label: "Any length" }, { key: "intensity", label: "Any intensity" }],
};
const label = (s: string) => s.replace(/_/g, " ");
const keyFrom = (id: string) => { const k = id.toLowerCase().replace(/[^a-z0-9_]+/g, "_").replace(/^[^a-z]+/, "").slice(0, 32); return k.length >= 2 ? k : "custom_texture"; };

export type LibraryBrowserProps = {
  kind: "texture" | "sound";
  projectId: string;
  uploadsOn?: boolean;
  /** add the item to the project under `key`; throw ApiError to show its message */
  onUse: (item: LibraryItem, key: string) => Promise<void>;
  /** optional lead cell (e.g. an audition button for sounds); default: the texture thumbnail */
  renderLead?: (item: LibraryItem) => ReactNode;
  placeholder?: string;
};

export function LibraryBrowser({ kind, projectId, uploadsOn, onUse, renderLead, placeholder }: LibraryBrowserProps) {
  const toast = useToast();
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("");
  const [sub, setSub] = useState("");
  const [facet, setFacet] = useState<Record<string, string>>({});
  const [res, setRes] = useState<Result | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [selRef, setSelRef] = useState<string | null>(null);
  const [key, setKey] = useState("");
  const [busy, setBusy] = useState(false);
  const [cats, setCats] = useState<Record<string, number>>({});
  const file = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const t = window.setTimeout(async () => {
      try {
        const r = await studioApi.browse({ kind, q, category: cat || undefined, sub: sub || undefined, projectId, limit: 40 });
        // descriptor facets are filtered client-side over the page (the API facets count the whole result)
        setRes(r); setErr(null);
        if (!q && !cat && !sub) setCats(r.facets.category);
      } catch (e) { setErr((e as Error).message); }
    }, 180);
    return () => window.clearTimeout(t);
  }, [kind, q, cat, sub, projectId]);

  const items = useMemo(() => (res?.items ?? []).filter((i) => Object.entries(facet).every(([k, v]) => !v || String(i.descriptors[k]) === v)), [res, facet]);
  const sel = items.find((i) => i.ref === selRef) ?? null;
  useEffect(() => { if (sel) setKey(keyFrom(sel.id.split(":").pop() ?? sel.id)); }, [sel]);
  const denied = res?.denied.find((d) => d.source === "builtin");

  const use = async () => {
    if (!sel) return;
    setBusy(true);
    try { await onUse(sel, key); setSelRef(null); }
    catch (e) { toast(e instanceof ApiError ? e.message : "Couldn't add it. Nothing was changed.", true); }
    finally { setBusy(false); }
  };
  const upload = async (f: File) => {
    const form = new FormData();
    form.set("file", f); form.set("projectId", projectId); form.set("key", keyFrom(f.name.replace(/\.png$/i, ""))); form.set("profile", "item");
    try { await studioApi.upload(form); toast(`Uploaded ${f.name}. It's in your library under Uploads; use it from there.`); setCat(""); setQ("uploads"); }
    catch (e) { toast(e instanceof ApiError ? e.message : "Upload failed.", true); }
  };

  return (
    <div className="lib" data-kind={kind}>
      <div className="lib-q">
        <div style={{ display: "flex", gap: 6 }}>
          <div className="lib-srch" style={{ flex: 1 }}><SI n="search" /><input className="cys-field" value={q} onChange={(e) => setQ(e.target.value)} placeholder={placeholder ?? (kind === "texture" ? "Search textures: sword, ore, potion…" : "Search sounds: scream, door, 9mm…")} aria-label="Search the library" /></div>
          {kind === "texture" && (
            <>
              <button type="button" className="cys-btn sm" disabled={!uploadsOn} title={uploadsOn ? "Upload a 16, 32 or 64 px PNG" : "Uploads aren't switched on yet"} onClick={() => file.current?.click()}><SI n="upload" />Upload</button>
              <input ref={file} type="file" accept="image/png" hidden onChange={(e) => { const f = e.target.files?.[0]; if (f) void upload(f); e.target.value = ""; }} />
            </>
          )}
        </div>
        <div className="cys-chiprow" role="group" aria-label="Category">
          <button type="button" className={`cys-fchip ${!cat ? "on" : ""}`} onClick={() => { setCat(""); setSub(""); }}>All</button>
          {Object.entries(cats).sort((a, b) => b[1] - a[1]).map(([c, nn]) => <button key={c} type="button" className={`cys-fchip ${cat === c ? "on" : ""}`} onClick={() => { setCat(c); setSub(""); }}>{label(c)}<i>{nn}</i></button>)}
        </div>
        <div className="lib-facets">
          <select className="cys-field" value={sub} onChange={(e) => setSub(e.target.value)} aria-label="Subcategory">
            <option value="">{cat ? `All ${label(cat)}` : "All kinds"} ({res?.total ?? 0})</option>
            {Object.entries(res?.facets.subcategory ?? {}).sort((a, b) => b[1] - a[1]).map(([s, nn]) => <option key={s} value={s}>{label(s)} · {nn}</option>)}
          </select>
          {FACETS[kind].map((f) => {
            const vals = res?.facets.descriptors[f.key] ?? {};
            if (!Object.keys(vals).length) return null;
            return (
              <select key={f.key} className="cys-field" value={facet[f.key] ?? ""} onChange={(e) => setFacet((x) => ({ ...x, [f.key]: e.target.value }))} aria-label={f.label}>
                <option value="">{f.label}</option>
                {Object.entries(vals).sort((a, b) => b[1] - a[1]).map(([v, nn]) => <option key={v} value={v}>{f.key === "size" ? `${v} px` : label(v)} · {nn}</option>)}
              </select>
            );
          })}
        </div>
      </div>
      {denied && <div className="lib-lock"><SI n="lock" /><span style={{ flex: 1 }}>{denied.reason}</span></div>}
      {err && <div className="cys-empty">{err}</div>}
      {sel && (
        <div className="lib-detail" data-testid="library-detail">
          <div className="pv">{sel.preview?.doc ? <RasterCanvas raster={renderDoc(sel.preview.doc)} /> : sel.preview?.png ? /* eslint-disable-next-line @next/next/no-img-element */ <img src={sel.preview.png} alt="" /> : <SI n={kind === "texture" ? "image" : "wave"} />}</div>
          <div className="meta">
            <b>{sel.name}</b>
            <span className="cys-hint">{label(sel.category)}{sel.subcategory ? ` · ${label(sel.subcategory)}` : ""} · {sel.source === "builtin" ? "Cyrus library" : sel.source === "project" ? "this mod" : "your uploads and mods"}</span>
            <span className="cys-hint" title={sel.ledger.licenceStatus}>{sel.ledger.original ? "Original Cyrus art" : sel.ledger.provenance}</span>
            <div className="cys-chiprow">{sel.tags.slice(0, 5).map((t) => <button key={t} type="button" className="cys-fchip" onClick={() => setQ(t)}>{t}</button>)}</div>
            <label className="cys-hint" htmlFor="lib-key">Name in this mod</label>
            <div style={{ display: "flex", gap: 6 }}>
              <input id="lib-key" className="cys-field" value={key} onChange={(e) => setKey(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, "").slice(0, 32))} aria-describedby="lib-key-hint" />
              <button type="button" className="cys-btn sm primary" disabled={busy || key.length < 2} onClick={() => void use()} data-testid="use-in-project"><SI n="plus" />{busy ? "Adding…" : "Use in project"}</button>
            </div>
            <span id="lib-key-hint" className="cys-hint">Saved as a new revision of the mod, with this mod&apos;s Style DNA.</span>
          </div>
        </div>
      )}
      <div role="list">
        {items.map((i) => (
          <button key={i.ref} type="button" role="listitem" className={`lib-row ${i.ref === selRef ? "on" : ""}`} onClick={() => setSelRef(i.ref === selRef ? null : i.ref)} aria-expanded={i.ref === selRef}>
            {renderLead ? renderLead(i) : <span className="cys-thumb">{i.preview?.doc ? <RasterCanvas raster={renderDoc(i.preview.doc)} /> : i.preview?.png ? /* eslint-disable-next-line @next/next/no-img-element */ <img src={i.preview.png} alt="" width={24} height={24} style={{ imageRendering: "pixelated" }} /> : <SI n="image" />}</span>}
            <span style={{ minWidth: 0 }}><b>{i.name}</b><small>{label(i.subcategory ?? i.category)}{i.descriptors.size ? ` · ${i.descriptors.size} px` : ""}{i.descriptors.material ? ` · ${label(String(i.descriptors.material))}` : ""}{i.source !== "builtin" ? ` · ${i.source === "project" ? "in this mod" : "yours"}` : ""}</small></span>
            <span className={`cys-tag ${i.descriptors.quality === "pass" ? "ok" : i.descriptors.quality === "warn" ? "warn" : "dim"}`}>{String(i.descriptors.quality ?? i.source)}</span>
          </button>
        ))}
        {res && !items.length && !err && <div className="cys-empty">Nothing matches. Try a broader word.</div>}
      </div>
      {res && <p className="cys-hint lib-foot">Showing {items.length} of {res.total}. Library art is original Cyrus work; picks are recoloured with this mod&apos;s Style DNA.</p>}
    </div>
  );
}

