"use client";
// Cyrus studios: the locked / included / plan-unknown states (approved mockup locked-states.html). The decision is the
// server's (GET /api/cyrus/assets/v1/projects -> access, from lib/cyrus/engine-core/asset-gate.ts); this page only
// shows it. The copy is the gate's own reason strings and the router downgrade notices. Assets already in the mod
// are always shown (read only): keeping, installing and exporting are never gated.
import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { cyrusTokens } from "@/components/cyrus-tokens";
import { PLAN_LABEL, type AssetPlan } from "@/lib/cyrus/engine-core/asset-gate";
import { buildNotices, PLAN_MATRIX, PLAN_ORDER, STUDIO_NAME } from "@/lib/cyrus/studios/access";
import { renderDoc } from "@/lib/cyrus/studios/paint";
import { studioApi, type AssetsView } from "./api";
import { SI } from "./icons";
import { RasterCanvas } from "./raster";
import { StudioShell, assetsHref, studioHref, type StudioMod } from "./StudioShell";

export function StudioLock({ mod, studio }: { mod: StudioMod; studio: "texture" | "sound" }) {
  return (
    <StudioShell mod={mod} current={STUDIO_NAME[studio]} studio={null}>
      <LockBody mod={mod} studio={studio} />
    </StudioShell>
  );
}

function LockBody({ mod, studio }: { mod: StudioMod; studio: "texture" | "sound" }) {
  const [view, setView] = useState<AssetsView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [tick, setTick] = useState(0);
  const [texSel, setTexSel] = useState<string | null>(null);
  useEffect(() => { studioApi.assets(mod.rootId).then(setView, (e) => setErr((e as Error).message)); }, [mod.rootId, tick]);
  const plan = view?.access.plan ?? null;
  const [previewAs, setPreviewAs] = useState<AssetPlan | "unknown" | null>(null);
  const shownPlan = previewAs ?? (view ? plan ?? "unknown" : null);
  if (err) return <div className="cys-empty" style={{ margin: "auto" }}>{err}</div>;
  if (!view || !shownPlan) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Checking your plan…</div>;
  const d = view.access.edit[studio];
  const name = STUDIO_NAME[studio];
  const tex = view.textures;
  const cur = tex.find((t) => t.key === texSel) ?? tex[0];
  const notes = buildNotices(shownPlan === "unknown" ? null : shownPlan, { sound: view.sounds[0]?.set ?? (view.soundRender ? "sounds" : null), texture: tex[0]?.key ?? null });
  const kindWord = studio === "texture" ? "textures" : "sounds";

  return (
    <main className="lk-ws">
      <section className="lk-col">
        <div className="lk-view cys-glass cys-hairline">
          <div className="lk-vh">
            <span style={{ fontSize: 18, color: "var(--accent-ink)", display: "flex" }}><SI n={studio === "texture" ? "image" : "wave"} /></span>
            <h1>{name}</h1>
            <span className={`cys-tag ${d.ok ? "ok" : "dim"}`}>{d.ok ? "included" : studio === "texture" ? "view only" : "listen only"}</span>
            <span className="sp" />
            <div className="cys-seg sm cys-soft">
              <Link href={studioHref(mod, "plans", "?studio=texture")} className={studio === "texture" ? "on" : ""}>Texture</Link>
              <Link href={studioHref(mod, "plans", "?studio=sound")} className={studio === "sound" ? "on" : ""}>Sound</Link>
            </div>
          </div>
          <div className="lk-vb">
            {studio === "texture" ? (
              <div className="lk-canvas">
                <span className="cys-tag ro"><SI n={d.ok ? "edit" : "eye"} />{d.ok ? "editable" : "read only"}</span>
                {cur ? <div className="chk"><RasterCanvas raster={renderDoc(cur.doc)} /></div> : <div className="cys-empty">This mod has no custom textures yet.</div>}
                <div className="lk-thumbs">{tex.map((t) => <button key={t.key} type="button" className={`cys-thumb ${t.key === cur?.key ? "on" : ""}`} title={t.key} aria-label={t.key} onClick={() => setTexSel(t.key)}><RasterCanvas raster={renderDoc(t.doc)} /></button>)}</div>
              </div>
            ) : (
              <div className="lk-events">
                {view.sounds.length ? view.sounds.map((s) => (
                  <div className="lk-er" key={s.key}><span className="pb" aria-hidden><SI n="wave" /></span><span className="e">{s.set}.{s.event}</span><span className="s">{s.subtitle ? `“${s.subtitle}”` : "Subtitle missing"}</span><span className={`cys-dot ${s.quality === "pass" ? "ok" : "warn"}`} title={`quality ${s.quality}`} /></div>
                )) : <div className="cys-empty">{view.soundRender === "off" ? "This mod's sounds are designed, but sound rendering isn't switched on yet." : "This mod has no custom sounds yet."}</div>}
                <p className="cys-hint" style={{ margin: "6px 2px 0" }}>Players hear these from the mod&apos;s resource pack. Listening in the portal arrives with the Sound Studio.</p>
              </div>
            )}
            <LockCard mod={mod} studio={studio} d={d} plan={plan} kindWord={kindWord} onRetry={() => { setView(null); setTick((x) => x + 1); }} />
          </div>
        </div>
        <div className="lk-note cys-glass">
          <h3><SI n="note" />What a build says on this plan</h3>
          {notes.length ? (
            <>
              {notes.map((t) => <div className="lk-gtk w" key={t}><SI n="info" /><span>{t}</span></div>)}
              <p className="cys-hint" style={{ margin: "10px 2px 0" }}>Shown under “Good to know” on the build. The mod is still built and does what was asked; only the custom asset is left out.</p>
            </>
          ) : <div className="lk-gtk"><SI n="check" /><span>Nothing extra: on {PLAN_LABEL[shownPlan as AssetPlan]}, Cyrus can make custom textures and sounds inside builds.</span></div>}
        </div>
      </section>
      <section className="lk-col">
        <PlanMatrix plan={plan} shown={shownPlan} onShow={setPreviewAs} />
      </section>
    </main>
  );
}

function LockCard({ mod, studio, d, plan, kindWord, onRetry }: { mod: StudioMod; studio: "texture" | "sound"; d: AssetsView["access"]["edit"]["texture"]; plan: AssetPlan | null; kindWord: string; onRetry: () => void }) {
  const name = STUDIO_NAME[studio];
  if (d.ok) return (
    <div className="lk-lock">
      <span className="lk-li ok"><SI n="check" /></span>
      <h2>{name} is in your plan</h2>
      {studio === "texture" ? (
        <><p>Edit any texture in {mod.name}. Cyrus edits arrive as candidates you approve.</p>
          <div className="lk-acts"><Link className="cys-btn primary" href={studioHref(mod, "texture")}><SI n="image" />Open Texture Studio</Link></div></>
      ) : (
        <><p>The Sound Studio editor opens here in the next release. Until then, this mod&apos;s sound events are listed in Mod assets.</p>
          <div className="lk-acts"><Link className="cys-btn" href={assetsHref(mod)}><SI n="package" />Mod assets</Link></div></>
      )}
      <p className="lk-small">{plan ? PLAN_LABEL[plan] : ""} plan</p>
    </div>
  );
  if (d.code === "plan_unknown") return (
    <div className="lk-lock">
      <span className="lk-li unk"><SI n="warn" /></span>
      <h2>We couldn&apos;t check your plan</h2>
      <p>{d.reason}</p>
      <p>Everything that&apos;s already in your mod keeps working.</p>
      <div className="lk-acts"><button type="button" className="cys-btn primary" onClick={onRetry}><SI n="restore" />Try again</button></div>
      <p className="lk-small">If this keeps happening, contact support from the portal.</p>
    </div>
  );
  const needs = (d.needs ?? "all") as AssetPlan;
  return (
    <div className="lk-lock">
      <span className="lk-li"><SI n="lock" /></span>
      <h2>{name} is part of the {PLAN_LABEL[needs]} plan{needs === "saka" ? " and up" : ""}</h2>
      <p>You&apos;re on {plan ? PLAN_LABEL[plan] : "your current plan"}. This mod&apos;s {kindWord} stay exactly as they are and keep working on your servers.</p>
      <ul>
        <li className="y"><SI n="check" />View, install and export this mod&apos;s {kindWord}</li>
        <li className="y"><SI n="check" />Rebuild the mod with them unchanged</li>
        <li className="y"><SI n="check" />Mod Packs and importing your own mod</li>
        <li className="n"><SI n="lock" />{studio === "texture" ? "Drawing, Style DNA fixes and AI texture edits" : "Editing waveforms, layers and AI sound edits"}</li>
        <li className="n"><SI n="lock" />The {studio === "texture" ? "Texture" : "Sound"} Library, and Cyrus making new {kindWord} in builds</li>
      </ul>
      <div className="lk-acts">
        <button type="button" className="cys-btn primary" onClick={() => cyrusTokens.open({ tab: "plans" })}>See {PLAN_LABEL[needs]}</button>
        <button type="button" className="cys-btn" onClick={() => cyrusTokens.open({ tab: "plans" })}>Compare plans</button>
      </div>
      <p className="lk-small">{studio === "texture" ? "Texture Studio comes with All models, which also includes the Yakko model." : "Sound Studio and the Sound Library come with Saka and All models."}</p>
    </div>
  );
}

export function PlanMatrix({ plan, shown, onShow }: { plan: AssetPlan | null; shown: AssetPlan | "unknown"; onShow: (p: AssetPlan | "unknown" | null) => void }) {
  const rows = useMemo(() => PLAN_MATRIX, []);
  return (
    <div className="lk-matrix cys-glass">
      <div className="lk-previewas">
        <span className="cys-eyebrow" style={{ whiteSpace: "nowrap" }}>Preview as</span>
        <div className="cys-seg sm" role="group" aria-label="Preview a plan">
          {PLAN_ORDER.map((p) => <button key={p} type="button" className={shown === p ? "on" : ""} aria-pressed={shown === p} onClick={() => onShow(p === plan ? null : p)}>{PLAN_LABEL[p]}{p === plan ? "" : ""}</button>)}
          {!plan && <button type="button" className={shown === "unknown" ? "on" : ""} title="Plan lookup failed" onClick={() => onShow(null)}>?</button>}
        </div>
      </div>
      <table className="lk-mx">
        <thead><tr><th scope="col">Feature</th>{PLAN_ORDER.map((p) => <th key={p} scope="col" className={p === shown ? "on" : ""}>{PLAN_LABEL[p]}{p === plan ? <span className="sr-only"> (your plan)</span> : null}</th>)}</tr></thead>
        <tbody>
          {rows.map((r, i) => "group" in r
            ? <tr key={i} className="grp"><td colSpan={5}>{r.group}</td></tr>
            : <tr key={i}><td>{r.label}</td>{PLAN_ORDER.map((p) => <td key={p} className={p === shown ? "on" : ""}>{r.allowed(p) ? <span className="y" aria-label="included"><SI n="check" /></span> : <span className="n" aria-label="not included"><SI n="lock" /></span>}</td>)}</tr>)}
        </tbody>
      </table>
      <p className="cys-hint" style={{ padding: "10px 14px 14px", margin: 0 }}>From the plan gate: Free and Katara get no studios, Saka adds sound, All models adds textures. The server checks every request again; this page is only a hint.</p>
    </div>
  );
}

