            <div className="note"><SI n="info" /><span>{P[2]}{view.pack.editedSinceBuild ? " Studio edits saved since the last build are in the mod's revisions; the next build ships them in the pack." : ""}</span></div>
            <div className="note plain"><SI n="phone" /><span>Bedrock players (Geyser/Floodgate) see vanilla looks and hear vanilla sounds: the pack is Java Edition only.</span></div>
          </div>
        ) : <div className="card" style={{ padding: "12px 14px" }}><span className="hint">No resource pack yet: this mod has no custom textures or sounds. Ask Cyrus for some in a change, or add a texture from the library.</span></div>}
      </div>

      <div className="sec">
        <div className="sec-h"><h2>Textures</h2><span className="tag">{view.textures.length}</span><span className="sp" />
          {tx.ok ? <Link className="btn" href={`${base}/texture`}><SI n="image" />Open Texture Studio</Link> : <span className="tag dim"><SI n="lock" />view only</span>}</div>
        <div className="texgrid">
          {view.textures.map((t) => {
            const q = docQuality(t.doc);
            return (
              <div className="card tex" key={t.key}>
                <div className="pv"><RasterCanvas raster={renderDoc(t.doc)} /></div>
                <div className="nm"><b>{t.key}</b><span className={`tag ${q.verdict === "pass" ? "ok" : q.verdict === "warn" ? "warn" : "bad"}`}>{q.verdict}</span></div>
                <div className="meta"><span>{t.doc.size}×{t.doc.size} · {t.doc.tile ? "block" : "item"}</span>{tx.ok && <Link className="btn" href={`${base}/texture?asset=${t.key}`}><SI n="edit" />Edit</Link>}</div>
              </div>
            );
          })}
          {STUDIO_DEFAULTS.mobSkin === "coming_soon" && (
            <div className="card tex later"><div className="pv"><SI n="lock" /></div><div className="nm"><b>mob skin</b><span className="tag dim">soon</span></div><div className="meta"><span>Mob skins need a per-mob template</span></div></div>
          )}
        </div>
        {!tx.ok && <div className="lockline"><SI n="lock" /><span>{tx.reason}</span><span className="sp" /><Link className="btn" href={plans("texture")}>See plans</Link></div>}
      </div>

      <div className="sec">
        <div className="sec-h"><h2>Sound events</h2><span className="tag">{view.sounds.length}</span><span className="sp" />
          {sd.ok ? <Link className="btn" href={`${base}/sound`}><SI n="wave" />Open Sound Studio</Link> : <span className="tag dim"><SI n="lock" />listen only</span>}</div>
        {sets.length ? sets.map((set) => (
          <div className="card sndset" key={set}>
            <div className="ssh"><svg className="cys-i" viewBox="0 0 24 24" aria-hidden dangerouslySetInnerHTML={{ __html: CREATURES_PATH }} /><b>{set}</b>sound set</div>
            {view.sounds.filter((s) => s.set === set).map((s) => (
              <div className="ev" key={s.key}>
                <span className="pb" aria-hidden><SI n="wave" /></span><span className="e">{s.event}</span>
                <span className="s">{s.subtitle ? `“${s.subtitle}”` : "Subtitle missing"}</span><span className="n">{s.variants} var</span>
                <span className={`dot ${s.quality === "pass" ? "ok" : "warn"}`} title={`quality ${s.quality}`} />
              </div>
            ))}
          </div>
        )) : <div className="card" style={{ padding: "12px 14px" }}><span className="hint">{view.soundRender === "off" ? "The sounds are designed, but sound rendering isn't switched on yet." : "No custom sounds in this mod."}</span></div>}
        {!sd.ok && <div className="lockline"><SI n="lock" /><span>{sd.reason}</span><span className="sp" /><Link className="btn" href={plans("sound")}>See plans</Link></div>}
      </div>

      <div className="sec">
        <div className="sec-h"><h2>Studios</h2><span className="sp" /><span className="hint">{plan ? PLAN_LABEL[plan] : "Plan unknown"} plan</span></div>
        <div className="studios">
          {([["texture", "image", "Texture Studio", tx, "Pixel editor, Style DNA, AI candidates"], ["sound", "wave", "Sound Studio", sd, "Waveforms, layers, the sound library"]] as const).map(([k, ic, name, d, sub]) => d.ok
            ? <Link key={k} className="card studio" href={k === "texture" ? `${base}/texture` : plans("sound")}><span className="si"><SI n={ic} /></span><span><b>{name}</b><small>{k === "sound" ? "In your plan · editor in the next release" : sub}</small></span><span className="go"><SI n="chevR" /></span></Link>
            : <div key={k} className="card studio lock"><span className="si"><SI n="lock" /></span><span><b>{name}</b><small>{d.code === "plan_unknown" ? "We couldn't check your plan" : `Part of the ${PLAN_LABEL[(d.needs ?? "all") as AssetPlan]} plan`}</small></span><Link className="btn" style={{ marginLeft: "auto" }} href={plans(k)}>See plans</Link></div>)}
        </div>
      </div>
      <p className="hint" style={{ margin: "14px 2px 0" }}>Keeping, installing, rebuilding unchanged and exporting these assets works on every plan.</p>
    </div>
  );
}

