import type { Metadata } from "next";
import { redirect } from "next/navigation";
import { modBuilderMetadata } from "@/lib/modbuilder/access";
import { TextureStudio } from "@/components/cyrus/studios/TextureStudio";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Texture Studio · Cyrus");
}

/** Full-page Texture Studio. Plans that may not edit textures (and an unknown plan) go to the locked state. */
export default async function TextureStudioPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ asset?: string | string[] }> }) {
