// Cyrus studios (R1b): seed the devhost THROWAWAY database with a "Banshee Hunt" mod per test account (one per plan),
// textures from the real reference spec + the texture library templates, a sound set and a pack record, then print
// session tokens for Playwright. Refuses to run against anything but devhost's wt_* database on 127.0.0.1:5433.
//   devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
import { SignJWT } from "jose";
import { db } from "../../lib/db";
import { GLOCK } from "../../lib/cyrus/textures/sample-glock";
import { canonicalJson, sha256Hex } from "../../lib/cyrus/assets/textures";
import { TEXTURE_SPEC_MIME } from "../../lib/cyrus/assets/sync";
import { addRevision, createProject, recordAsset } from "../../lib/cyrus/engine-core/store";
import { textureQuality } from "../../lib/cyrus/textures/quality";
import { render } from "../../lib/cyrus/textures/render";
import { encodePng } from "../../lib/cyrus/textures/png";
import { saveTexture, type StudioServiceDeps } from "../../lib/cyrus/studios/service";
import { chainOf, prismaStudioStore } from "../../lib/cyrus/studios/deps";
import { useTextureFromLibrary } from "../../lib/cyrus/library/use-in-project";
import { docFromSpec } from "../../lib/cyrus/studios/paint";
import type { MbAssets } from "../../lib/modbuilder/types";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }

const PLANS = [
  { id: "usr_studio_all", email: "studio-all@example.test", tier: "all" },
  { id: "usr_studio_saka", email: "studio-saka@example.test", tier: "saka" },
  { id: "usr_studio_katara", email: "studio-katara@example.test", tier: "katara" },
  { id: "usr_studio_free", email: "studio-free@example.test", tier: null },
  { id: "usr_studio_unknown", email: "studio-unknown@example.test", tier: "all" }, // the lookup is faulted by env
  { id: "usr_studio_outsider", email: "studio-outsider@example.test", tier: "all" }, // not on the preview list
] as const;

const SOUNDS: NonNullable<MbAssets["sounds"]> = [
  ["banshee", "ambient", "Banshee moans", 3], ["banshee", "hurt", "Banshee shrieks", 2], ["banshee", "death", "Banshee fades away", 1], ["banshee", "attack", "Banshee lunges", 1],
  ["banshee", "step", "Banshee drifts", 2], ["glock_9mm", "fire", "Pistol fires", 3], ["glock_9mm", "reload", "Pistol reloads", 1], ["banshee", "wail", "Banshee wails", 1],
].map(([set, event, subtitle, variants]) => ({ set: set as string, event: event as string, key: `nx_x:${set}.${event}`, subtitle: subtitle as string, role: "hostile", category: "hostile", variants: variants as number, quality: event === "fire" ? "warn" as const : "pass" as const, specSha256: "0".repeat(64) }));

async function seedUser(p: (typeof PLANS)[number]) {
  await db.user.upsert({ where: { id: p.id }, update: {}, create: { id: p.id, email: p.email, name: p.email.split("@")[0], passwordHash: "x", emailVerifiedAt: new Date() } as never });
  await db.cyrusTokenAccount.upsert({ where: { userId: p.id }, update: { tierOverride: p.tier, balance: 250 }, create: { userId: p.id, balance: 250, lifetimeGranted: 250, tierOverride: p.tier } });
  const old = await db.modBuild.findMany({ where: { userId: p.id }, select: { id: true } });
  if (old.length) {
    const projects = await db.cyrusProject.findMany({ where: { userId: p.id }, select: { id: true } });
    for (const pr of projects) { await db.cyrusProjectAsset.deleteMany({ where: { projectId: pr.id } }); await db.cyrusIdentifier.deleteMany({ where: { projectId: pr.id } }); await db.$executeRawUnsafe(`ALTER TABLE "CyrusRevision" DISABLE TRIGGER USER`).catch(() => 0); await db.cyrusProject.update({ where: { id: pr.id }, data: { headRevisionId: null, lastPassingRevisionId: null } }); await db.cyrusRevision.deleteMany({ where: { projectId: pr.id } }); await db.$executeRawUnsafe(`ALTER TABLE "CyrusRevision" ENABLE TRIGGER USER`).catch(() => 0); await db.cyrusProject.delete({ where: { id: pr.id } }); }
    await db.modBuild.deleteMany({ where: { userId: p.id } });
  }
  const meta = { title: "Banshee Hunt", category: "creatures", categorySource: "owner", description: "A wailing banshee that haunts the night, and the handgun to stop it." };
  const v1 = await db.modBuild.create({ data: { userId: p.id, status: "succeeded", prompt: "A wailing banshee mob that haunts the night, and a 9mm handgun to stop it.", mcVersion: "1.21.11", pluginName: "BansheeHunt", version: "1.0.0", cyrus: meta, result: { summary: "Banshee mob + handgun" }, jarName: "BansheeHunt-1.0.0.jar", jarSha256: "a".repeat(64), createdAt: new Date(Date.now() - 2 * 86400e3) } });
  const project = await createProject({ userId: p.id, game: "minecraft", rootBuildId: v1.id });
  const glockSha = sha256Hex(canonicalJson(GLOCK));
  const rev = await addRevision(project.id, {
    kind: "generated", status: "passed", modBuildId: v1.id, expectedHeadId: null, message: "1 custom texture; pack seeded",
    manifest: [{ path: "plugin/BansheeHunt-1.0.0.jar", sha256: "a".repeat(64), role: "artifact" }, { path: "assets/textures/glock_9mm.json", sha256: glockSha, role: "asset" }, { path: `resourcepack/${"b".repeat(40)}.zip`, sha256: "c".repeat(64), role: "resourcePack" }],
  });
  await recordAsset(project.id, { revisionId: rev.id, assetKey: "glock_9mm", kind: "texture", sha256: glockSha, size: canonicalJson(GLOCK).length, origin: "generated", mime: TEXTURE_SPEC_MIME, path: "assets/textures/glock_9mm.json",
    provenance: { generator: "cyrus-texture-dsl", spec: GLOCK, quality: textureQuality(render(GLOCK)), pngSha256: sha256Hex(encodePng(render(GLOCK))), modBuildId: v1.id, kept: false } });
  const assets: MbAssets = {
    status: "ready", namespace: project.namespace, projectId: project.id, revisionId: rev.id,
    textures: [{ name: "glock_9mm", model: `${project.namespace}:glock_9mm`, specSha256: glockSha, pngSha256: "d".repeat(64), quality: "warn" }],
    sounds: SOUNDS.map((s) => ({ ...s, key: `${project.namespace}:${s.set}.${s.event}` })), soundRender: "rendered", dropped: [],
    pack: { sha1: "b".repeat(40), sha256: "c".repeat(64), bytes: 48213, format: 75, clientVerified: false, url: `https://packs.example.test/p/${"b".repeat(40)}.zip` },
    loader: { id: `${project.namespace}-main`, url: `https://packs.example.test/p/${"b".repeat(40)}.zip`, sha1: "b".repeat(40), prompt: "Banshee Hunt uses custom item textures and sounds.", required: false }, notices: [],
  };
  await db.modBuild.update({ where: { id: v1.id }, data: { result: { summary: "Banshee mob + handgun", assets } as never } });
  // two more textures from the texture library, through the studio's own save path (library origin)
  const deps: StudioServiceDeps = { store: prismaStudioStore, planOf: async () => "all", chain: chainOf, deliveryOn: () => false };
  for (const [itemId, key] of [["ghost_veil_ecto", "banshee_veil"], ["gem_azure", "soul_gem"]] as const) {
    const used = await useTextureFromLibrary({ itemId, key, namespace: project.namespace }, (k, path) => prismaStudioStore.reserve(project.id, k, path));
    if (!used.ok) throw new Error(used.error);
    const head = (await db.cyrusProject.findUnique({ where: { id: project.id } }))!.headRevisionId;
    await saveTexture(deps, { userId: p.id, projectId: project.id, key, doc: docFromSpec(used.spec), baseAssetId: null, expectedHeadId: head, origin: "library", provenance: { library: used.provenance.library } });
  }
  return { userId: p.id, buildId: v1.id, projectId: project.id };
}

(async () => {
  await db.setting.upsert({ where: { key: "preview_access_emails_modbuilder" }, update: { value: PLANS.filter((p) => p.id !== "usr_studio_outsider").map((p) => p.email).join(",") }, create: { key: "preview_access_emails_modbuilder", value: PLANS.filter((p) => p.id !== "usr_studio_outsider").map((p) => p.email).join(",") } });
  await db.setting.upsert({ where: { key: "cyrus_studios_enabled" }, update: { value: "false" }, create: { key: "cyrus_studios_enabled", value: "false" } });
  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const out: Record<string, unknown> = { cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" };
  for (const p of PLANS) {
    const s = await seedUser(p);
    const u = await db.user.findUniqueOrThrow({ where: { id: p.id } });
    out[p.id.replace("usr_studio_", "")] = { ...s, token: await new SignJWT({ sub: u.id, sv: u.sessionVersion ?? 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(secret) };
  }
  process.stdout.write(JSON.stringify(out, null, 1));
  await db.$disconnect();
})().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

