// Cyrus studios (R1b): screenshots of every studio screen and state (run ON node-2 against the devhost dev server).
//   devhost db reset && devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//   devhost dev            (env: CYRUS_STUDIO_CANDIDATES=fake CYRUS_STUDIO_TEST_PLAN_UNKNOWN=usr_studio_unknown)
//   devhost run -- node test/e2e/cyrus-studios.shots.mjs .studio-tokens.json .studio-shots [only]
//   devhost pull .studio-shots /root/agent-notes/cyrus-designs/impl-shots
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".studio-shots", only = ""] = process.argv;
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900 }, narrow: { width: 390, height: 844 } };

async function shot(name, who, path, { view = "desktop", theme = "dark", act, full = false, wait = 1800 } = {}) {
  if (only && !name.includes(only)) return;
  const ctx = await browser.newContext({ viewport: VIEW[view], deviceScaleFactor: 1, isMobile: view === "narrow", hasTouch: view === "narrow", colorScheme: theme, reducedMotion: "reduce" });
  await ctx.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-sound", "off"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  const res = await page.goto(BASE + path.replace("{build}", T[who].buildId), { waitUntil: "networkidle", timeout: 180000 }).catch((e) => (errs.push("goto " + e), null));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForTimeout(wait);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(600);
  const file = `${out}/${name}.png`;
  await page.screenshot({ path: file, fullPage: full });
  console.log(file, res?.status() ?? "-", page.url().replace(BASE, ""), errs.length ? "ERR " + errs.join(" | ").slice(0, 500) : "");
  await ctx.close();
}

const tex = "/dashboard/cyrus/{build}/studio/texture";
const askCandidate = async (page) => {
  await page.getByLabel("Ask Cyrus to change this texture").fill("Remove the grip noise and brighten the front sight");
  await page.getByLabel("Send").click();
  await page.getByTestId("candidate").waitFor({ timeout: 30000 });
};
await shot("texture-dark", "all", tex, { act: askCandidate });
await shot("texture-light", "all", tex, { theme: "light", act: askCandidate });
await shot("texture-dark-checks", "all", tex, { act: async (p) => { await p.getByRole("tab", { name: /Checks/ }).click(); } });
await shot("texture-dark-library", "all", tex, { act: async (p) => { await p.getByRole("tab", { name: /Library/ }).click(); await p.waitForTimeout(1200); await p.locator(".lib-row").nth(2).click(); } });
await shot("texture-dark-history", "all", tex, { act: async (p) => { await p.getByRole("tab", { name: /History/ }).click(); } });
await shot("texture-dark-inhand-fp", "all", tex, { act: async (p) => { await p.getByRole("button", { name: "In hand", exact: true }).click(); } });
await shot("texture-dark-inhand-tp", "all", tex, { act: async (p) => { await p.getByRole("button", { name: "In hand", exact: true }).click(); await p.getByRole("button", { name: "Third person", exact: true }).click(); } });
await shot("texture-dark-inhand-veil", "all", tex + "?asset=soul_gem", { act: async (p) => { await p.getByRole("button", { name: "In hand", exact: true }).click(); } });
await shot("texture-narrow", "all", tex, { view: "narrow", full: true, act: askCandidate });
await shot("assets-dark", "all", "/dashboard/cyrus/{build}?tab=assets", { wait: 4000 });
await shot("assets-light", "all", "/dashboard/cyrus/{build}?tab=assets", { theme: "light", wait: 4000 });
await shot("assets-saka-dark", "saka", "/dashboard/cyrus/{build}?tab=assets", { wait: 4000 });
await shot("assets-narrow", "all", "/dashboard/cyrus/{build}?tab=assets", { view: "narrow", wait: 4000 });
await shot("locked-saka-texture-dark", "saka", tex);
await shot("locked-all-dark", "all", "/dashboard/cyrus/{build}/studio/plans?studio=texture");
await shot("locked-katara-sound-light", "katara", "/dashboard/cyrus/{build}/studio/sound", { theme: "light" });
await shot("locked-free-narrow", "free", tex, { view: "narrow", full: true });
await shot("locked-unknown-dark", "unknown", tex);
await shot("locked-saka-sound-dark", "saka", "/dashboard/cyrus/{build}/studio/sound");
await shot("gate-outsider-404", "outsider", tex);
await browser.close();

