export default async function TextureStudioPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ asset?: string | string[] }> }) {
  const { id } = await params;
  const { mod, plan } = await studioContext(id);
  if (!plan.edit.texture.ok) return <StudioLock mod={mod} studio="texture" />;
  const a = (await searchParams).asset;
  return <TextureStudio mod={mod} initialKey={typeof a === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(a) ? a : null} />;
}

