import { applyDisplay, rotate } from "/tank/dev-worktrees/cyrus-r5/lib/cyrus/textures/display";
const H=[0.56,-0.52,-0.72]; const f=1/Math.tan(35*Math.PI/180);
const P=(t:any,v:any)=>{const p=applyDisplay(t,v).map((x:number)=>x/16);const w=[H[0]+p[0],H[1]+p[1],H[2]+p[2]];return [f*w[0]/-w[2],-f*w[1]/-w[2],w[2]];};
const view=(()=>{const l=Math.hypot(...H);return H.map(x=>-x/l);})();
const res:any[]=[];
for (let rx=-30; rx<=30; rx+=10) for (let ry=-180; ry<180; ry+=10) for (let rz=-60; rz<=60; rz+=5) {
  const t={rotation:[rx,ry,rz],translation:[0,0,0],scale:[1,1,1]};
  const n=rotate(t.rotation as any,[0,0,1]); const facing=Math.abs(n[0]*view[0]+n[1]*view[1]+n[2]*view[2]);
  const back=P(t,[4,10,8]), muzzle=P(t,[15,10,8]), top=P(t,[8,13,8]), grip=P(t,[5,3,8]);
  const dx=muzzle[0]-back[0], dy=muzzle[1]-back[1], dz=muzzle[2]-back[2];
  if (!(grip[1]>top[1])) continue; if (dz> -0.15) continue; // away from camera
  const ang=Math.atan2(-dy,dx)*180/Math.PI; // screen angle, 90=up
  if (ang<100||ang>170) continue; // pointing up-left
  res.push({rx,ry,rz,facing:+facing.toFixed(2),ang:+ang.toFixed(0),dz:+dz.toFixed(2),len:+Math.hypot(dx,dy).toFixed(2)});
}
res.sort((a,b)=>b.facing*b.len-a.facing*a.len); console.log(JSON.stringify(res.slice(0,12)));
EOF
