    headRevisionId: async (projectId) => mem.revisions.filter((r) => r.projectId === projectId).at(-1)?.id ?? null,
    addRevision: async (projectId, input) => { const r = { id: `rev${mem.revisions.length + 1}`, projectId, modBuildId: input.modBuildId ?? null, seq: mem.revisions.length + 1, input }; mem.revisions.push(r); return r; },
    recordAsset: async (projectId, a) => { const k = `${projectId}|${a.kind}|${a.assetKey}|${a.sha256}`; if (!mem.assets.has(k)) mem.assets.set(k, a); return mem.assets.get(k); },
  };
