// Cyrus studios UI (R1b), pure + API tests with fakes (no DB, no network, no model):
// paint-layer persistence and compositing, the pack + quality bar on the composite, editor logic (history, tools,
// compare regions, ramps), the studio gates per plan, held-item display transforms, the studio service on an
// in-memory store (save = new revision, stale head, quality refusal, candidates accept / reject), the asset-sync
// merge that keeps studio edits, and the /api/cyrus/assets/v1 handlers end to end with fake deps.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { inflateRawSync } from "node:zlib";
import { GLOCK } from "../lib/cyrus/textures/sample-glock";
import { render, type Raster } from "../lib/cyrus/textures/render";
import { textureQuality } from "../lib/cyrus/textures/quality";
import { MAX_OPS, type TextureSpec } from "../lib/cyrus/textures/dsl";
import { buildPack } from "../lib/cyrus/textures/pack";
import { decodePng } from "../lib/cyrus/library/png-decode";
import { encodePng } from "../lib/cyrus/textures/png";
import { applyDisplay, displayFor, gripKindOf, gripPoint, HANDHELD_DISPLAY, GENERATED_DISPLAY, TOOL_HANDLE, GUN_ROTATION } from "../lib/cyrus/textures/display";
import { applyPaint, checkDoc, checkPaint, docFromRaster, docFromSpec, docQuality, paintFromBuffers, paintToBuffers, renderDoc, type TextureDoc } from "../lib/cyrus/studios/paint";
import {
  applyPixels, canRedo, canUndo, changeRegions, composite, floodPts, followsDna, generateRamp, historyInit, historyJump, historyPush, historyRedo, historyUndo,
  linePts, paletteRamps, qualityDelta, rectPts, selectionPixels, stroke, toolForKey, type Layers,
} from "../lib/cyrus/studios/editor";
import { buildNotices, PLAN_MATRIX, PLAN_ORDER, studioPlanView, studiosOpen } from "../lib/cyrus/studios/access";
import { heldScene } from "../lib/cyrus/studios/held";
import { candidateKeyOf, candidateRequestText } from "../lib/cyrus/studios/marker";
import {
  currentStudioDoc, docSha, fakeCandidates, rejectCandidate, resolveTextures, saveTexture, StudioError,
  type AssetRow, type ChainInfo, type ProjectRow, type RevRow, type StudioServiceDeps, type StudioStore,
} from "../lib/cyrus/studios/service";
import * as H from "../lib/cyrus/studios/http";
import { memoryUploadStore } from "../lib/cyrus/studios/uploads";
import { SoundLibraryProvider, TextureLibraryProvider } from "../lib/cyrus/library/providers";
import { userAssetProviders } from "../lib/cyrus/library/user-assets";
import { buildIdentifier } from "../lib/cyrus/engine-core/identifiers";
import { syncBuildAssets, TEXTURE_SPEC_MIME, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { libraryTexture, librarySpec } from "../lib/cyrus/texture-library/library";

const NS = "nx_7k2qf9wd";
const glockSha = sha256Hex(canonicalJson(GLOCK));
const px = (r: Raster, x: number, y: number) => Array.from(r.px.subarray((y * r.size + x) * 4, (y * r.size + x) * 4 + 4));
const layers = (doc: TextureDoc): Layers => { const b = paintToBuffers(doc.size, doc.paint); return { spec: doc.spec, size: doc.size, paint: b.rgba, cut: b.cut }; };
const unzip = (z: Buffer) => {
  const eocd = z.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  const n = z.readUInt16LE(eocd + 10); let p = z.readUInt32LE(eocd + 16); const out = new Map<string, Buffer>();
  for (let i = 0; i < n; i++) {
    const csz = z.readUInt32LE(p + 20), nl = z.readUInt16LE(p + 28), el = z.readUInt16LE(p + 30), cl = z.readUInt16LE(p + 32), off = z.readUInt32LE(p + 42);
    const name = z.subarray(p + 46, p + 46 + nl).toString("utf8");
    const lnl = z.readUInt16LE(off + 26), lel = z.readUInt16LE(off + 28);
    out.set(name, inflateRawSync(z.subarray(off + 30 + lnl + lel, off + 30 + lnl + lel + csz))); p += 46 + nl + el + cl;
  }
  return out;
};

// ------------------------------------------------------------------------------------------------ paint layer
describe("paint layer persistence (sparse layer stored with the asset, composited everywhere)", () => {
  it("round-trips editor buffers <-> stored layer, sorted and minimal", () => {
    const l = layers(docFromSpec(GLOCK));
    const s = stroke(stroke(l, [[1, 1], [2, 1]], "#ff0000"), [[5, 5]], null);
    const p = paintFromBuffers(32, s.paint, s.cut)!;
    assert.deepEqual(p.colors, ["#ff0000"]);
    assert.deepEqual(p.set, [33, 0, 34, 0]);
    assert.deepEqual(p.clear, [165]);
    const back = paintToBuffers(32, p);
    assert.deepEqual(Array.from(back.rgba), Array.from(s.paint));
    assert.deepEqual(Array.from(back.cut), Array.from(s.cut));
    assert.equal(paintFromBuffers(32, new Uint8ClampedArray(32 * 32 * 4), new Uint8Array(32 * 32)), null);
  });
  it("composite: painted pixels replace the base (opaque), cleared pixels erase it", () => {
    const base = render(GLOCK);
    const out = applyPaint(base, { size: 32, colors: ["#00ff00"], set: [10 * 32 + 6, 0], clear: [10 * 32 + 10] });
    assert.deepEqual(px(out, 6, 10), [0, 255, 0, 255]);
    assert.deepEqual(px(out, 10, 10), [0, 0, 0, 0]);
    assert.deepEqual(px(out, 20, 10), px(base, 20, 10));
    assert.notEqual(out.px, base.px); // a new raster: the cached base is never mutated
  });
  it("the 400-op DSL limit never applies to painting: every pixel of a 64x64 can be painted", () => {
    const rgba = new Uint8ClampedArray(64 * 64 * 4);
    for (let i = 0; i < 64 * 64; i++) { rgba[i * 4] = i % 7 * 30; rgba[i * 4 + 1] = 40; rgba[i * 4 + 2] = 90; rgba[i * 4 + 3] = (i % 64) > 3 && (i % 64) < 60 && i > 256 && i < 3800 ? 255 : 0; }
    const paint = paintFromBuffers(64, rgba, new Uint8Array(64 * 64))!;
    assert.ok(paint.set.length / 2 > MAX_OPS * 5);
    const d = checkDoc({ v: 1, name: "big_paint", size: 64, spec: null, paint });
    assert.ok(d.ok, d.ok ? "" : d.error);
  });
  it("validates untrusted docs and layers", () => {
    assert.equal(checkDoc({ v: 1, name: "x", size: 32, spec: null, paint: null }).ok, false); // bad name
    assert.equal(checkDoc({ v: 1, name: "glock_9mm", size: 32, spec: null, paint: null }).ok, false); // nothing to draw
    assert.equal(checkDoc({ v: 1, name: "glock_9mm", size: 16, spec: GLOCK, paint: null }).ok, false); // size mismatch
    assert.equal(checkDoc({ v: 1, name: "glock_9mm", size: 32, spec: GLOCK, paint: null, evil: 1 }).ok, false);
    assert.equal(checkDoc({ v: 2, name: "glock_9mm", size: 32, spec: GLOCK, paint: null }).ok, false);
    assert.equal(checkPaint({ size: 32, colors: ["#fff"], set: [], clear: [] }, 32).ok, false);
    assert.equal(checkPaint({ size: 32, colors: ["#ffffff"], set: [5, 0, 4, 0], clear: [] }, 32).ok, false); // unsorted
    assert.equal(checkPaint({ size: 32, colors: ["#ffffff"], set: [5, 0], clear: [5] }, 32).ok, false); // painted and cleared
    assert.equal(checkPaint({ size: 32, colors: ["#ffffff"], set: [5000, 0], clear: [] }, 32).ok, false); // out of range
    assert.equal(checkPaint({ size: 32, colors: ["#ffffff"], set: [5, 1], clear: [] }, 32).ok, false); // colour index
    const ok = checkDoc({ v: 1, name: "glock_9mm", size: 32, spec: GLOCK, paint: { size: 32, colors: ["#FFFFFF"], set: [5, 0], clear: [] } });
    assert.ok(ok.ok && ok.doc.paint!.colors[0] === "#ffffff");
  });
  it("an all-paint doc from an upload refuses semi-transparent pixels", () => {
    const r = render(GLOCK);
    assert.ok(docFromRaster("glock_copy", r).ok);
    const bad = { size: 32, px: new Uint8ClampedArray(r.px) }; bad.px[3 + 4 * 300] = 128;
    assert.equal(docFromRaster("glock_copy", bad).ok, false);
  });
});

describe("the pack builder and the quality bar consume the COMPOSITE", () => {
  const painted: TextureDoc = { ...docFromSpec(GLOCK), paint: { size: 32, colors: ["#ff00ff"], set: [12 * 32 + 16, 0], clear: [] } };
  it("buildPack ships the composite pixels for a doc and the plain render for a spec", () => {
    const a = buildPack({ namespace: NS, description: "t", mcVersion: "1.21.11", textures: [painted] });
    const b = buildPack({ namespace: NS, description: "t", mcVersion: "1.21.11", textures: [GLOCK] });
    assert.ok(a.ok && b.ok);
    if (!a.ok || !b.ok) return;
    const pa = decodePng(unzip(a.pack.zip).get(`assets/${NS}/textures/item/glock_9mm.png`)!, { maxBytes: 1 << 20, sizes: [16, 32, 64], maxChunks: 64 });
    const pb = decodePng(unzip(b.pack.zip).get(`assets/${NS}/textures/item/glock_9mm.png`)!, { maxBytes: 1 << 20, sizes: [16, 32, 64], maxChunks: 64 });
    assert.ok(pa.ok && pb.ok);
    if (!pa.ok || !pb.ok) return;
    assert.deepEqual(Array.from(pa.raster.px), Array.from(renderDoc(painted).px));
    assert.deepEqual(Array.from(pb.raster.px), Array.from(render(GLOCK).px));
    assert.notEqual(a.pack.sha1, b.pack.sha1);
    assert.equal(buildPack({ namespace: NS, description: "t", mcVersion: "1.21.11", textures: [{ ...painted, paint: { size: 32, colors: [], set: [1, 0], clear: [] } }] }).ok, false);
  });
  it("the quality bar runs on the composite (tq-1 ids unchanged); painting can change the verdict", () => {
    const q = docQuality(docFromSpec(GLOCK));
    assert.deepEqual(q.checks.map((c) => c.id), ["transparency", "palette_size", "contrast", "noise", "outline", "vanilla_lookalike"]);
    assert.deepEqual(q, textureQuality(render(GLOCK)));
    const all = new Uint8ClampedArray(32 * 32 * 4).fill(255);
    const solid = { ...docFromSpec(GLOCK), paint: paintFromBuffers(32, all, new Uint8Array(32 * 32)) };
    assert.equal(docQuality(solid).verdict, "fail"); // every pixel solid: the item reads as a square
  });
  it("model JSON carries the display block the In-hand preview shows", () => {
    const sword = librarySpec(libraryTexture("sword_iron")!)!;
    const p = buildPack({ namespace: NS, description: "t", mcVersion: "1.21.11", textures: [GLOCK, { ...sword, name: "sword_iron" }] });
    assert.ok(p.ok);
    if (!p.ok) return;
    const files = unzip(p.pack.zip);
    const sm = JSON.parse(files.get(`assets/${NS}/models/item/sword_iron.json`)!.toString());
    const gm = JSON.parse(files.get(`assets/${NS}/models/item/glock_9mm.json`)!.toString());
    assert.equal(sm.parent, "minecraft:item/handheld");
    assert.deepEqual(sm.display, HANDHELD_DISPLAY);
    assert.deepEqual(gm.display, displayFor("glock_9mm", render(GLOCK)));
    assert.notDeepEqual(gm.display.firstperson_righthand, HANDHELD_DISPLAY.firstperson_righthand);
  });
});

// ------------------------------------------------------------------------------------------------ held-item transforms
describe("In-hand preview: display transforms (pack == preview), grip points, scene", () => {
  it("vanilla handheld / generated values (checked against the 1.21.4 asset mirror)", () => {
    assert.deepEqual(HANDHELD_DISPLAY.firstperson_righthand, { rotation: [0, -90, 25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] });
    assert.deepEqual(HANDHELD_DISPLAY.thirdperson_righthand, { rotation: [0, -90, 55], translation: [0, 4.0, 0.5], scale: [0.85, 0.85, 0.85] });
    assert.deepEqual(GENERATED_DISPLAY.thirdperson_righthand, { rotation: [0, 0, 0], translation: [0, 3, 1], scale: [0.55, 0.55, 0.55] });
  });
  it("grip kinds and points differ for a handgun and a sword", () => {
    assert.equal(gripKindOf("glock_9mm"), "handgun");
    assert.equal(gripKindOf("handgun_iron"), "handgun");
    assert.equal(gripKindOf("sword_iron"), "tool");
    assert.equal(gripKindOf("pickaxe_gold"), "tool");
    const g = gripPoint(render(GLOCK), "handgun");
    // the Glock's grip polygon spans x 4-13, y 15-28 of 32 (model units: x 2-6.5, y 2-8.5)
    assert.ok(g[0] > 2 && g[0] < 6.5 && g[1] > 1.5 && g[1] < 8.5, String(g));
    assert.deepEqual(gripPoint(render(GLOCK), "tool"), TOOL_HANDLE);
  });
  it("a re-gripped handgun puts ITS grip where vanilla puts a tool's handle", () => {
    const d = displayFor("glock_9mm", render(GLOCK));
    const g = gripPoint(render(GLOCK), "handgun");
    for (const view of ["firstperson", "thirdperson"] as const) {
      const t = d[`${view}_righthand`];
      const ref = { ...t, translation: (view === "firstperson" ? HANDHELD_DISPLAY.firstperson_righthand : HANDHELD_DISPLAY.thirdperson_righthand).translation };
      const a = applyDisplay(t, [g[0], g[1], 8]), b = applyDisplay(ref, [TOOL_HANDLE[0], TOOL_HANDLE[1], 8]);
      for (let i = 0; i < 3; i++) assert.ok(Math.abs(a[i] - b[i]) < 0.01, `${view} ${a} vs ${b}`);
      assert.deepEqual(t.rotation, GUN_ROTATION[view]);
    }
    assert.deepEqual(displayFor("sword_iron", render(GLOCK)), HANDHELD_DISPLAY);
  });
  it("the handgun points forward with the grip down (first person: away from the camera, toward the crosshair)", () => {
    const t = displayFor("glock_9mm", render(GLOCK)).firstperson_righthand;
    const w = (v: [number, number, number]) => { const p = applyDisplay(t, v); return [0.56 + p[0] / 16, -0.52 + p[1] / 16, -0.72 + p[2] / 16]; };
    const back = w([4, 10, 8]), muzzle = w([15, 10, 8]), top = w([8, 13, 8]), grip = w([5, 3, 8]);
    assert.ok(muzzle[2] < back[2], "barrel goes away from the camera");
    assert.ok(muzzle[0] < back[0], "toward the crosshair (left of the hand)");
    assert.ok(grip[1] < top[1], "grip below the slide");
  });
  it("scene: item polygons, the fist drawn over the grip, inside the stage", () => {
    for (const view of ["firstperson", "thirdperson"] as const) {
      const s = heldScene(render(GLOCK), "glock_9mm", view, 316, 120);
      assert.ok(s.polys.filter((p) => p.part === "item").length > 200);
      const lastItem = s.polys.map((p) => p.part).lastIndexOf("item"), firstFist = s.polys.findIndex((p) => p.part === "fingers");
      assert.ok(firstFist > lastItem, "the fist closes over the item");
      assert.ok(s.grip[0] > 0 && s.grip[0] < 316 && s.grip[1] > 0 && s.grip[1] < 120);
