// ------------------------------------------------------------------------------------------------ editor
describe("editor logic: history, tools, compare, palette", () => {
  const L0 = layers(docFromSpec(GLOCK));
  it("history: one step per action, undo / redo / jump, redo branch dropped, capped", () => {
    let h = historyInit("Opened", L0);
    assert.equal(canUndo(h), false);
    const a = stroke(L0, [[0, 0]], "#ff0000");
    h = historyPush(h, "Pencil", a);
    h = historyPush(h, "Fill", stroke(a, [[1, 0]], "#ff0000"));
    assert.equal(h.steps.length, 3);
    h = historyUndo(historyUndo(h));
    assert.equal(h.at, 0); assert.equal(canRedo(h), true);
    h = historyRedo(h); assert.equal(h.steps[h.at].label, "Pencil");
    h = historyPush(h, "Erase", L0);
    assert.deepEqual(h.steps.map((s) => s.label), ["Opened", "Pencil", "Erase"]);
    assert.equal(historyJump(h, 99).at, 2);
    let big = historyInit("o", 0);
    for (let i = 0; i < 250; i++) big = historyPush(big, `s${i}`, i, 200);
    assert.equal(big.steps.length, 200); assert.equal(big.at, 199); assert.equal(big.steps[199].snap, 249);
  });
  it("tools: line, rect, mirror, selection clip, eraser clears base, flood fill", () => {
    assert.deepEqual(linePts({ x: 0, y: 0 }, { x: 3, y: 0 }), [[0, 0], [1, 0], [2, 0], [3, 0]]);
    assert.equal(rectPts({ x: 0, y: 0 }, { x: 2, y: 2 }).length, 8);
    const m = stroke(L0, [[1, 2]], "#123456", { mirror: true });
    assert.deepEqual(px(composite(m), 30, 2), [0x12, 0x34, 0x56, 255]);
    const clipped = stroke(L0, [[1, 1], [10, 10]], "#123456", { sel: { x: 8, y: 8, w: 4, h: 4 } });
    assert.equal(clipped.paint[(1 * 32 + 1) * 4 + 3], 0);
    assert.equal(clipped.paint[(10 * 32 + 10) * 4 + 3], 255);
    const e = stroke(L0, [[10, 12]], null);
    assert.equal(composite(e).px[(12 * 32 + 10) * 4 + 3], 0);
    assert.equal(composite(e, { base: true, paint: false }).px[(12 * 32 + 10) * 4 + 3], 255); // hiding paint shows the base again
    const empty = floodPts(composite(L0), 0, 0);
    assert.ok(empty.length > 300 && empty.every(([x, y]) => composite(L0).px[(y * 32 + x) * 4 + 3] === 0));
    assert.equal(toolForKey("b"), "pencil"); assert.equal(toolForKey("G"), "fill"); assert.equal(toolForKey("q"), null);
  });
  it("compare: changed-pixel regions and a partial / in-selection apply into the paint layer", () => {
    const cand: TextureSpec = { ...GLOCK, ops: [...GLOCK.ops.filter((o) => o.op !== "noise").slice(0, -2), { op: "px", x: 26, y: 8, c: "o" }, ...GLOCK.ops.slice(-2)] };
