    const sight = regions.find((r) => r.pixels.includes(8 * 32 + 26));
    assert.ok(sight && sight.pixels.length <= 4);
    const part = applyPixels(L0, after, sight!.pixels);
    assert.deepEqual(px(composite(part), 26, 8), px(after, 26, 8));
    assert.deepEqual(px(composite(part), 8, 20), px(before, 8, 20)); // the grip noise stays (not picked)
    assert.equal(selectionPixels(32, { x: 30, y: 30, w: 5, h: 5 }).length, 4);
    const d = qualityDelta(textureQuality(before), textureQuality(after));
    assert.deepEqual(d.find((x) => x.id === "palette_size"), { id: "palette_size", from: "warn", to: "pass" });
  });
  it("palette: generated 5-shade ramps (dark -> light) and ramp grouping", () => {
    const r = generateRamp("#e8a63a");
    const lum = (h: string) => parseInt(h.slice(1, 3), 16) * 0.2126 + parseInt(h.slice(3, 5), 16) * 0.7152 + parseInt(h.slice(5, 7), 16) * 0.0722;
    assert.equal(r.length, 5);
    for (let i = 1; i < 5; i++) assert.ok(lum(r[i]) > lum(r[i - 1]));
    const g = paletteRamps(GLOCK.palette);
    assert.deepEqual(g.map((x) => x.label), ["Neutral", "Amber"]);
    const lib = paletteRamps({ m1: "#111111", m2: "#333333", h1: "#552200", x1: "#ff0000", fk: "#000000" });
    assert.deepEqual(lib.map((x) => x.label), ["Primary", "Secondary", "Accent", "Fixed"]);
    assert.equal(followsDna(textureQuality(render(GLOCK))), true);
  });
});

// ------------------------------------------------------------------------------------------------ gates
describe("studio gates (server side; the UI only shows them)", () => {
  it("visibility: preview accounts while cyrus_studios_enabled is off; everyone with Cyrus once it is on", () => {
    assert.equal(studiosOpen({ cyrusUser: true, previewUser: true, flagOn: false }), true);
    assert.equal(studiosOpen({ cyrusUser: true, previewUser: false, flagOn: false }), false);
    assert.equal(studiosOpen({ cyrusUser: true, previewUser: false, flagOn: true }), true);
