type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[]; ids: Set<string> };
function memStore(): StudioStore & { mem: Mem } {
  const mem: Mem = { projects: new Map(), revs: [], assets: [], ids: new Set() };
  let t = Date.parse("2026-10-10T10:00:00Z");
  return {
    mem,
    projectForRoot: async (root) => [...mem.projects.values()].find((p) => p.rootBuildId === root) ?? null,
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    assetById: async (id) => mem.assets.find((a) => a.id === id) ?? null,
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const seq = mem.revs.filter((r) => r.projectId === pid).length + 1;
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: input.modBuildId ?? null };
      mem.revs.push(r); p.headRevisionId = r.id;
      return r;
    },
    async recordAsset(pid, a) {
      const hit = mem.assets.find((x) => x.projectId === pid && x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256);
      if (hit) return hit;
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) };
      mem.assets.push(row);
      return row;
    },
    async reserve(pid, kind, key) { const b = buildIdentifier(mem.projects.get(pid)!.namespace, kind, key); if (!b.ok) throw new Error(b.error); mem.ids.add(b.id); return { fullId: b.id }; },
  };
}
const PID = "cp" + "1".repeat(20);
async function seeded(plan: unknown = "all", candidateBuilds: ChainInfo["candidateBuilds"] = []) {
  const store = memStore();
  store.mem.projects.set(PID, { id: PID, userId: "u1", namespace: NS, rootBuildId: "mb1", headRevisionId: null, title: null });
  const rev = await store.addRevision(PID, { kind: "generated", status: "passed", modBuildId: "mb1", expectedHeadId: null, manifest: [{ path: "assets/textures/glock_9mm.json", sha256: glockSha, role: "asset" }, { path: "resourcepack/" + "b".repeat(40) + ".zip", sha256: "c".repeat(64), role: "resourcePack" }] });
  await store.recordAsset(PID, { revisionId: rev.id, assetKey: "glock_9mm", kind: "texture", sha256: glockSha, size: 10, origin: "generated", mime: TEXTURE_SPEC_MIME, path: "assets/textures/glock_9mm.json", provenance: { spec: GLOCK, modBuildId: "mb1" } });
  const chain: ChainInfo = { rootBuildId: "mb1", latestBuildId: "mb1", mcVersion: "1.21.11", pluginName: "BansheeHunt", assets: null, candidateBuilds };
  const published: Buffer[] = [];
  const deps: StudioServiceDeps = { store, planOf: async (u) => (u === "u1" ? plan : "all"), chain: async (u, r) => (u === "u1" && r === "mb1" ? chain : null), deliveryOn: () => false, publish: async (zip) => { published.push(zip); return { ok: true, url: "https://p/x.zip", sha1: "s" }; } };
  return { store, deps, chain, published, headId: () => store.mem.projects.get(PID)!.headRevisionId };
}
const painted = (): TextureDoc => ({ ...docFromSpec(GLOCK), paint: { size: 32, colors: ["#e8a63a"], set: [8 * 32 + 26, 0], clear: [] } });

describe("studio service (in-memory store): save = a NEW revision, never an overwrite", () => {
  it("resolves the current texture and saves an edit as kind=asset with the doc, the pack rebuilt from the composite", async () => {
