    assert.equal(s.store.mem.revs.length, before + 1);
    const rev = s.store.mem.revs.at(-1)!;
    assert.equal(rev.kind, "asset"); assert.equal(rev.status, "passed"); assert.equal(r.seq, 2);
    const entry = rev.manifest.find((e) => e.path === "assets/textures/glock_9mm.json")!;
    assert.notEqual(entry.sha256, glockSha);
    assert.equal(rev.manifest.filter((e) => e.role === "resourcePack").length, 1);
    assert.ok("sha1" in r.pack && r.pack.hosted);
    const row = s.store.mem.assets.at(-1)!;
    assert.equal(row.origin, "edited"); assert.equal(row.revisionId, rev.id);
    const doc = (row.provenance as { doc: TextureDoc }).doc;
    assert.deepEqual(doc.supersedes, [glockSha]); // carried from the generated base: a later unchanged build keeps the edit
    assert.equal(entry.sha256, docSha(doc).sha256);
    // the first revision and row are untouched
    assert.equal(s.store.mem.revs[0].manifest.find((e) => e.path === "assets/textures/glock_9mm.json")!.sha256, glockSha);
    const zip = s.published.at(-1)!;
    const png = decodePng(unzip(zip).get(`assets/${NS}/textures/item/glock_9mm.png`)!, { maxBytes: 1 << 20, sizes: [16, 32, 64], maxChunks: 64 });
    assert.ok(png.ok && Array.from(png.raster.px).join() === Array.from(renderDoc(doc).px).join());
    const [cur] = resolveTextures(await s.store.assets(PID), new Set());
    assert.equal(cur.assetId, row.id); assert.equal(cur.history.length, 2);
  });
  it("refuses: stale head (409), failing quality (422), other users (404), a duplicate new key (409)", async () => {
