    await assert.rejects(saveTexture(s.deps, { userId: "u1", projectId: PID, key: "glock_9mm", doc: painted(), baseAssetId: t.assetId, expectedHeadId: "revOLD" }), (e: StudioError) => e.status === 409 && e.code === "stale_head");
    const solid = { ...docFromSpec(GLOCK), paint: paintFromBuffers(32, new Uint8ClampedArray(32 * 32 * 4).fill(255), new Uint8Array(32 * 32)) };
    await assert.rejects(saveTexture(s.deps, { userId: "u1", projectId: PID, key: "glock_9mm", doc: solid, baseAssetId: t.assetId, expectedHeadId: s.headId() }), (e: StudioError) => e.status === 422);
    await assert.rejects(saveTexture({ ...s.deps, planOf: async () => "all" }, { userId: "u2", projectId: PID, key: "glock_9mm", doc: painted(), baseAssetId: t.assetId, expectedHeadId: s.headId() }), (e: StudioError) => e.status === 404);
    await assert.rejects(saveTexture(s.deps, { userId: "u1", projectId: PID, key: "glock_9mm", doc: painted(), baseAssetId: null, expectedHeadId: s.headId() }), (e: StudioError) => e.status === 409 && e.code === "exists");
    assert.equal(s.store.mem.revs.length, 1);
  });
  it("plan gate on every write: Saka / Katara / Free locked, unknown plan fails closed", async () => {
    for (const [plan, code] of [["saka", "asset_locked"], ["katara", "asset_locked"], ["free", "asset_locked"], [null, "plan_unknown"]] as const) {
