    }
  });
  it("candidates: undecided candidate builds never become current; reject records the decision and supersedes the candidate", async () => {
    const s = await seeded("all", [{ id: "mbC", key: "glock_9mm", status: "succeeded", error: null, createdAt: "" }]);
