    await s.store.recordAsset(PID, { revisionId: "rev1", assetKey: "glock_9mm", kind: "texture", sha256: cSha, size: 1, origin: "generated", mime: TEXTURE_SPEC_MIME, path: "x", provenance: { spec: cand, modBuildId: "mbC" } });
    const cands = new Set(["mbC"]);
