  });
  it("candidate builds are recognised by their change-request marker only", () => {
    assert.equal(candidateKeyOf(candidateRequestText("glock_9mm", "brighten the sight")), "glock_9mm");
    assert.equal(candidateKeyOf("Make the boss faster"), null);
    assert.equal(candidateKeyOf('Texture Studio edit of "X": nope'), null);
  });
