describe("asset sync keeps studio edits a build did not replace", () => {
  const syncDeps = (studio: AssetSyncDeps["studioDocFor"]) => {
    const recorded: { origin: string; sha256: string; provenance: unknown }[] = [];
    let manifest: { path: string; sha256: string }[] = [];
    const d: AssetSyncDeps = {
      selectStore: () => ({ ok: false, reason: "off" }),
      projectForRootBuild: async () => ({ id: PID, namespace: NS, userId: "u1" }),
      createProject: async () => { throw new Error("no"); },
      findRevisionForBuild: async () => null, headRevisionId: async () => null,
      addRevision: async (_p, input) => { manifest = input.manifest as typeof manifest; return { id: "revS" }; },
      recordAsset: async (_p, a) => { recorded.push({ origin: a.origin, sha256: a.sha256, provenance: a.provenance }); return a; },
      studioDocFor: studio,
    };
    return { d, recorded, manifest: () => manifest };
  };
  const build = { id: "mb2", userId: "u1", rootBuildId: "mb1", mcVersion: "1.21.11", pluginName: "BansheeHunt", jarName: "B.jar", jarSha256: "a".repeat(64) };
  const svc = (spec: TextureSpec) => ({ namespace: NS, promptVersion: "p", qualityVersion: "tq-1", kept: true, downgraded: [], warnings: [], textures: [{ name: spec.name, path: `assets/textures/${spec.name}.json`, sha256: sha256Hex(canonicalJson(spec)), spec, quality: null }] });
  it("build returns the spec the edit superseded -> the doc (spec + paint) ships and is recorded", async () => {
    const doc: TextureDoc = { ...painted(), supersedes: [glockSha] };
    const { sha256, canonical } = docSha(doc);
    const x = syncDeps(async () => ({ doc, sha256, canonical }));
    const a = await syncBuildAssets(build, svc(GLOCK) as never, x.d);
    assert.equal(a!.textures[0].specSha256, sha256);
    assert.equal(x.recorded[0].origin, "edited");
    assert.equal((x.recorded[0].provenance as { keptStudioEdit: boolean }).keptStudioEdit, true);
    assert.equal(x.manifest().find((e) => e.path === "assets/textures/glock_9mm.json")!.sha256, sha256);
  });
  it("build CHANGED the texture -> the build's spec wins (the studio edit stays in history)", async () => {
    const doc: TextureDoc = { ...painted(), supersedes: ["f".repeat(64)] };
    const { sha256, canonical } = docSha(doc);
    const x = syncDeps(async () => ({ doc, sha256, canonical }));
    await syncBuildAssets(build, svc(GLOCK) as never, x.d);
    assert.equal(x.recorded[0].origin, "generated"); assert.equal(x.recorded[0].sha256, glockSha);
  });
  it("no studio dep -> byte-identical behaviour (generated spec rows)", async () => {
    const x = syncDeps(undefined);
    await syncBuildAssets(build, svc(GLOCK) as never, x.d);
    assert.equal(x.recorded[0].origin, "generated");
  });
});

