// Cyrus studios (R1b): Playwright INTERACTION tests against the devhost dev server with the seeded fixtures.
// Run (node-2, nothing paid, fake candidate backend):
//   devhost db reset && devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//   devhost env set CYRUS_STUDIO_CANDIDATES=fake; devhost env set CYRUS_STUDIO_TEST_PLAN_UNKNOWN=usr_studio_unknown
//   devhost dev
//   devhost run -- node test/e2e/cyrus-studios.e2e.mjs .studio-tokens.json
//   devhost stop dev
// Covers: draw pixels, undo / redo, request + accept a candidate, save a revision (survives a reload), library
// "use in project", the narrow approve flow, and the gates (plan locks, plan unknown, not-a-preview 404, API 403).
import { chromium } from "playwright";
import { readFileSync } from "node:fs";

const T = JSON.parse(readFileSync(process.argv[2], "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
const browser = await chromium.launch();
let failed = 0;
const ok = (cond, name, extra = "") => { console.log(`${cond ? "PASS" : "FAIL"}  ${name}${extra ? "  " + extra : ""}`); if (!cond) failed++; };
async function page(who, path, view = { width: 1440, height: 900 }) {
  const ctx = await browser.newContext({ viewport: view, isMobile: view.width < 500, hasTouch: view.width < 500 });
  await ctx.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const p = await ctx.newPage();
  const res = await p.goto(BASE + path.replace("{build}", T[who].buildId), { waitUntil: "networkidle", timeout: 180000 });
  return { p, ctx, res };
}
const tex = "/dashboard/cyrus/{build}/studio/texture";
const steps = (p) => p.locator(".tx-step").allTextContents();

// 1. draw, undo, redo
{
  const { p, ctx } = await page("all", tex);
  await p.getByTestId("pixel-canvas").waitFor();
  const box = await p.getByTestId("pixel-canvas").boundingBox();
  await p.keyboard.press("b");
  await p.mouse.move(box.x + box.width * 0.05, box.y + box.height * 0.05); await p.mouse.down();
  await p.mouse.move(box.x + box.width * 0.2, box.y + box.height * 0.05, { steps: 6 }); await p.mouse.up();
  let s = await steps(p);
  ok(s.length === 2 && /Pencil/.test(s[1]), "pencil stroke = one edit step", JSON.stringify(s));
  ok(/\d+ px edited/.test(await p.locator(".tx-layer.on small").textContent()) && !/^0 px/.test(await p.locator(".tx-layer.on small").textContent()), "paint layer counts the painted pixels");
  ok(await p.getByTestId("save-revision").isEnabled(), "save enabled after an edit");
  await p.keyboard.press("Control+z");
  ok((await p.locator(".tx-step.cur").textContent()).includes("Opened"), "Ctrl Z goes back one step");
  await p.keyboard.press("Control+Shift+z");
  ok(/Pencil/.test(await p.locator(".tx-step.cur").textContent()), "Ctrl Shift Z redoes it");
  await p.keyboard.press("e");
  ok((await p.getByRole("button", { name: "Eraser (E)" }).getAttribute("aria-pressed")) === "true", "E selects the eraser");

  // 2. candidate -> accept -> save -> reload
  await p.getByLabel("Ask Cyrus to change this texture").fill("Remove the grip noise and brighten the front sight");
  await p.getByLabel("Ask Cyrus to change this texture").press("Enter");
  await p.getByTestId("candidate").waitFor({ timeout: 30000 });
  ok(await p.locator(".tx-cmpbar").isVisible(), "candidate arrives as a compare layer (split view on)");
  await p.getByRole("button", { name: "Changed pixels" }).click();
  await p.getByTestId("accept-candidate").click();
  s = await steps(p);
  ok(/Accepted Cyrus candidate|Applied/.test(s.at(-1)), "accept = one edit step", s.at(-1));
  await p.getByTestId("save-revision").click();
  await p.locator(".cys-toast").filter({ hasText: "Saved as revision" }).waitFor({ timeout: 20000 });
  ok(true, "saved as a new revision");
  await p.reload({ waitUntil: "networkidle" });
  await p.getByRole("tab", { name: /History/ }).click();
  const hist = await p.locator(".tx-rev b").allTextContents();
  ok(hist.some((h) => /Accepted Cyrus candidate/.test(h)) && hist.length >= 2, "history keeps every revision after reload", JSON.stringify(hist.slice(0, 3)));

  // 3. library -> use in project
  await p.getByRole("tab", { name: /Library/ }).click();
  await p.getByLabel("Search the library").fill("sword");
  await p.locator(".lib-row").first().waitFor();
  await p.waitForTimeout(500);
  await p.locator(".lib-row").first().click();
  await p.locator("#lib-key").fill("banshee_blade");
  await p.getByTestId("use-in-project").click();
  await p.locator(".cys-row", { hasText: "banshee_blade" }).waitFor({ timeout: 20000 });
  ok(true, "library pick added to the mod as a new texture");
  await ctx.close();
}

// 4. narrow approve
{
  const { p, ctx } = await page("all", tex + "?asset=soul_gem", { width: 390, height: 844 });
  await p.evaluate(async ({ pid }) => { const r = await fetch(`/api/cyrus/assets/v1/projects/${pid}/textures/soul_gem/candidates`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt: "add a highlight" }) }); return r.status; }, { pid: T.all.projectId });
  ok(await p.locator(".tx-narrow").isVisible(), "narrow layout: read-only review");
  ok(!(await p.locator(".tx-ws").isVisible()), "narrow layout hides the editor");
  await ctx.close();
}

// 5. gates
{
  const { p, ctx } = await page("saka", tex);
  ok(await p.getByText("Texture Studio is part of the All models plan").isVisible(), "Saka: Texture Studio locked, textures shown read only");
  const st = await p.evaluate(async ({ pid }) => (await fetch(`/api/cyrus/assets/v1/projects/${pid}/textures/glock_9mm/revisions`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ doc: { v: 1, name: "glock_9mm", size: 16, spec: null, paint: { size: 16, colors: ["#ffffff"], set: [20, 0], clear: [] } }, baseAssetId: null, expectedHeadId: null }) })).status, { pid: T.saka.projectId });
  ok(st === 403 || st === 409, "Saka: the API refuses a texture save server side", String(st));
  await ctx.close();
}
{
  const { p, ctx } = await page("saka", "/dashboard/cyrus/{build}/studio/sound");
  ok(await p.getByText("Sound Studio is in your plan").isVisible(), "Saka: Sound Studio included");
  await ctx.close();
}
{
  const { p, ctx } = await page("free", "/dashboard/cyrus/{build}/studio/sound");
  ok(await p.getByText("Sound Studio is part of the Saka plan and up").isVisible(), "Free: Sound Studio locked");
  await ctx.close();
}
{
  const { p, ctx } = await page("unknown", tex);
  ok(await p.getByText("We couldn't check your plan").isVisible(), "plan lookup failure: fails closed for editing, assets still shown");
  ok((await p.locator(".lk-thumbs .cys-thumb").count()) >= 2, "plan unknown: the mod's textures stay viewable");
  await ctx.close();
}
{
  const { p, ctx, res } = await page("outsider", tex);
  ok(res.status() === 404 || (await p.getByText(/could not be found|not found/i).count()) > 0, "not a preview account (flag off): 404", String(res.status()));
  const st = await p.evaluate(async () => (await fetch(`/api/cyrus/assets/v1/projects?root=x`)).status);
  ok(st === 404, "not a preview account: API 404", String(st));
  await ctx.close();
}
await browser.close();
console.log(failed ? `\n${failed} FAILED` : "\nall passed");
process.exit(failed ? 1 : 0);

