    const poll = await deps.candidates.poll({ userId: viewer.userId, project, chain, key, requestId: b.acceptCandidate as string });
    if (poll.status !== "ready") throw new StudioError(409, "candidate_not_ready", "That candidate isn't ready.");
    decision = { candidate: b.acceptCandidate as string, accepted: true };
    also = [poll.specSha256];''','''    const { project, chain, texture } = await textureForEdit(deps.service, viewer.userId, projectId, key);
    const sha = await candidateSpecSha(deps.candidates, { userId: viewer.userId, project, chain, texture, key, requestId: b.acceptCandidate as string });
